window.PEPTIDOS=[{"id":0,"n":"5-Amino-1MQ","al":"","ar":"digestivo","ca":"wellness","cl":"Small-molecule NNMT inhibitor","ev":"baja","u":"Molécula pequeña estudiada por su efecto sobre NNMT y el metabolismo de grasa; no es un péptido. Los resultados preclínicos no establecen pérdida de peso ni seguridad en personas.","c":"Inhibe la enzima NNMT; en células sube NAD+ y frena la formación de grasa.","m":"Oral / inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/5-amino-1mq","ci":["https://doi.org/10.1016/j.bcp.2017.11.007","https://doi.org/10.1038/s41598-021-03670-5","https://pubmed.ncbi.nlm.nih.gov/29155147/","https://pubmed.ncbi.nlm.nih.gov/39161060/","https://www.accessdata.fda.gov/scripts/cder/daf/index.cfm?event=overview.process&ApplNo=213051","https://www.accessdata.fda.gov/scripts/cder/daf/index.cfm?event=overview.process&ApplNo=215866","https://pubmed.ncbi.nlm.nih.gov/39531138/","https://pubmed.ncbi.nlm.nih.gov/29992272/"],"x":{"r":"5-Amino-1MQ es una molécula pequeña que bloquea la enzima NNMT. En células y en ratones obesos redujo la grasa corporal sin bajar el consumo de comida, pero no existe ni un solo estudio publicado en humanos. Se vende junto a péptidos, aunque químicamente no es un péptido, y no está aprobado por la FDA.","q":"Un inhibidor de NNMT (nicotinamida N-metiltransferasa) de bajo peso molecular que se mercadea en clínicas de longevidad y pérdida de peso.","m":"La NNMT es una enzima que se vuelve más activa en el tejido graso de personas con obesidad. Al trabajar, consume recursos que la célula usa para producir energía. La idea detrás de 5-Amino-1MQ es frenar esa enzima para que la célula grasa conserve más NAD+ y SAM, dos moléculas clave del metabolismo energético.","mp":["Bloquea la enzima NNMT dentro del adipocito.","Sube los niveles de NAD+ y SAM en la célula.","En cultivos celulares disminuye la formación de grasa nueva (lipogénesis).","En ratones obesos bajó peso y grasa sin cambiar cuánto comían."],"f":"No está aprobado para ningún uso. Se vende en el mercado wellness y de 'research chemicals'.","e":[["Estudio fundacional de inhibidores de NNMT","Ratones","Demostró por primera vez que inhibir NNMT reduce la obesidad"],["Estudio 2022","Ratones obesos","Inhibición de NNMT + dieta baja en grasa redujo peso y adiposidad"]],"en":"Toda la evidencia es animal o celular. No hay ensayos en humanos, así que no se conocen ni su eficacia ni su seguridad en personas.","s":["Perfil en humanos desconocido: no hay estudios de seguridad."],"sg":["Preocupación teórica por alterar la metilación (SAM elevado de forma sostenida).","NNMT participa en biología del cáncer; efectos a largo plazo sin estudiar.","Productos del mercado gris: pureza, dosis y contaminación inciertas."]}},{"id":1,"n":"Abaloparatide","al":"","ar":"huesos","ca":"fda","cl":"PTHrP analog","ev":"fda","u":"Análogo de PTHrP utilizado para osteoporosis en pacientes seleccionados con alto riesgo de fractura; estimula la formación de hueso.","c":"Análogo de PTHrP: activa el receptor PTH1 y estimula formación de hueso nuevo.","m":"Tymlos · inyección SC diaria","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/abaloparatide","ci":["https://www.ncbi.nlm.nih.gov/books/NBK587447/","https://pmc.ncbi.nlm.nih.gov/articles/PMC6182596/","https://www.ncbi.nlm.nih.gov/books/NBK499863/","https://www.niams.nih.gov/health-topics/bone-mineral-density-tests-what-numbers-mean","https://jamanetwork.com/journals/jama/fullarticle/2544640","https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/208743Orig1s015lbl.pdf","https://www.tymlos.com/?gad_source=1&gad_campaignid=21055082327&gbraid=0AAAAADNsb4qCJgnxNB5pTWCD3N2p3Zm6C&gclid=CjwKCAjw_KjVBhAHEiwAnC0N9Ap1pWaetNr-4XCLa4_tM5peCP-VQTDHPPoLXABXJH0HzzOqanVymRoCXVQQAvD_BwE","http://sciencedirect.com/science/article/abs/pii/S0006295219302126"],"x":{"r":"Abaloparatide (Tymlos) es una versión sintética de 34 aminoácidos de la proteína relacionada a la hormona paratiroidea (PTHrP). Estimula la formación de hueso nuevo y está aprobado desde 2017 para osteoporosis con alto riesgo de fractura. En el ensayo ACTIVE redujo en ~86% las fracturas vertebrales nuevas frente a placebo.","q":"Un agente anabólico óseo (construye hueso) que se inyecta diariamente bajo la piel.","m":"El hueso se destruye (resorción) y se reconstruye (formación) todo el tiempo. Abaloparatide activa el receptor PTH1 de forma que la construcción supera a la destrucción. A ese periodo se le llama 'ventana anabólica': durante el tratamiento el cuerpo fabrica hueso más rápido de lo que lo pierde.","mp":["Activa el receptor PTH1 en las células formadoras de hueso.","Aumenta la densidad mineral en columna, cadera y cuello femoral.","Influye en el balance de calcio y fosfato.","Resultado: menos fracturas vertebrales y no vertebrales."],"f":"Aprobado por la FDA en 2017 (Tymlos) para mujeres posmenopáusicas y, más tarde, hombres con osteoporosis y alto riesgo de fractura.","e":[["ACTIVE","Mujeres posmenopáusicas, doble ciego vs placebo","−86% fracturas vertebrales nuevas; −43% fracturas no vertebrales"],["ACTIVE (densidad ósea)","Misma población","Aumento significativo de densidad en cadera, columna lumbar y cuello femoral"]],"en":"Evidencia sólida de ensayos aleatorizados que respaldan su aprobación.","s":["Mareo y vértigo","Náusea","Dolor de cabeza","Palpitaciones / taquicardia","Fatiga","Enrojecimiento o moretón en el sitio de inyección","Dolor articular u óseo","Distensión o dolor abdominal","Diarrea"],"sg":["Hipercalcemia (calcio alto en sangre).","Hipercalciuria, que puede causar piedras en los riñones.","Hipotensión ortostática al inicio: primeras dosis sentado o acostado."]}},{"id":2,"n":"Acetyl hexapeptide-8","al":"Argireline","ar":"piel","ca":"cosmetico","cl":"Neurotransmitter-inhibiting peptide","ev":"moderada","u":"Ingrediente cosmético tópico estudiado para mejorar la apariencia de líneas de expresión. No equivale a una inyección de toxina botulínica.","c":"Imita un fragmento de SNAP-25 y reduce la contracción de músculos de expresión.","m":"Argireline · crema/sérum","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/acetyl-hexapeptide-8","ci":["https://doi.org/10.1007/s40257-013-0009-9","https://pmc.ncbi.nlm.nih.gov/articles/PMC12193160/","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/fda-authority-over-cosmetics-how-cosmetics-are-not-fda-approved-are-fda-regulated","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/it-cosmetic-drug-or-both-or-it-soap","https://www.cir-safety.org/sites/default/files/acetyl122020revTR.pdf","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=485d9b71-6881-42c5-a620-a4360c7192ab","https://pubmed.ncbi.nlm.nih.gov/23417317/","https://pubmed.ncbi.nlm.nih.gov/38024099/"],"x":{"r":"El acetil hexapéptido-8, conocido como Argireline, es un péptido cosmético que imita un pedazo de la proteína nerviosa SNAP-25. Se vende como alternativa tópica 'tipo Botox' para suavizar líneas de expresión. Un estudio aleatorizado de 2013 mostró mejoría en arrugas alrededor de los ojos en 4 semanas, con efecto modesto.","q":"Péptido sintético de seis aminoácidos usado en sueros y cremas antiedad.","m":"Para que un músculo de la cara se contraiga, el nervio libera un mensajero químico. Esa liberación depende de un grupo de proteínas llamado complejo SNARE, del que forma parte SNAP-25. Argireline imita el extremo de SNAP-25 y compite con ella, de modo que el complejo se arma peor y llega menos señal al músculo. Es el mismo blanco general que el Botox, pero mucho más suave y aplicado sobre la piel.","mp":["Imita el final de la proteína SNAP-25.","Interfiere con el armado del complejo SNARE.","Disminuye la señal que contrae los músculos de expresión.","Limitación: no está claro cuánto penetra la piel."],"f":"Es un ingrediente cosmético, no un medicamento, por lo que no requiere aprobación de la FDA.","e":[["Ensayo aleatorizado 2013","60 personas, crema vs placebo, 4 semanas","Menor apariencia de arrugas periorbitales"],["Revisión 2025 y estudios pequeños","Varios, a menudo financiados por fabricantes","Mejorías modestas y consistentes"]],"en":"Evidencia moderada: hay ensayo controlado, pero los estudios son pequeños y la penetración en la piel es una duda real. El beneficio es cosmético y modesto, no comparable con Botox inyectable.","s":["Enrojecimiento leve","Irritación","Reacción alérgica (rara)"],"sg":["El panel CIR lo consideró seguro en cosméticos; perfil de irritación bajo."]}},{"id":3,"n":"Acetyl octapeptide-3","al":"SNAP-8","ar":"piel","ca":"cosmetico","cl":"Neurotransmitter-inhibiting peptide","ev":"baja","u":"Péptido cosmético tópico investigado para líneas de expresión; la evidencia clínica es limitada y depende de la formulación.","c":"Interfiere con la liberación de neurotransmisor en la unión neuromuscular.","m":"SNAP-8 · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/acetyl-octapeptide-3","ci":["https://doi.org/10.1007/s40257-013-0009-9","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/fda-authority-over-cosmetics-how-cosmetics-are-not-fda-approved-are-fda-regulated","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/it-cosmetic-drug-or-both-or-it-soap","https://doi.org/10.1111/jocd.12314"],"x":{"r":"El acetil octapéptido-3 (SNAP-8) es un pariente de Argireline con dos aminoácidos más. Se mercadea como 'Argireline más fuerte' para líneas de expresión, pero casi toda su evidencia viene del propio fabricante.","q":"Péptido sintético de ocho aminoácidos para cremas y sueros antiedad.","m":"Funciona con la misma lógica que Argireline: imita el extremo de SNAP-25 y entorpece el complejo SNARE que el nervio usa para contraer el músculo. Menos contracción repetida significa líneas de expresión menos marcadas. La gran limitación es la llegada a través de la piel: es una molécula grande y soluble en agua.","mp":["Imita a SNAP-25.","Reduce la liberación del mensajero que contrae el músculo.","Efecto superficial y suave."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Pruebas del fabricante","Voluntarios, sin publicación independiente","Reporta menor profundidad de arrugas"]],"en":"Evidencia baja: no hay ensayo clínico independiente y revisado por pares. Su beneficio se apoya en el mecanismo compartido con Argireline.","s":["Enrojecimiento leve","Irritación","Alergia (rara)"],"sg":["Perfil de seguridad típico de ingrediente cosmético tópico."]}},{"id":4,"n":"Acetyl tetrapeptide-5","al":"Eyeseryl","ar":"piel","ca":"cosmetico","cl":"Signal peptide","ev":"baja","u":"Ingrediente cosmético estudiado para la apariencia de bolsas y edema periocular; no trata causas médicas de hinchazón.","c":"Ayuda a reducir acumulación de líquido y mejora elasticidad bajo los ojos.","m":"Eyeseryl · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/acetyl-tetrapeptide-5","ci":["https://www.lubrizol.com/Personal-Care/Products/Product-Finder/Products-Data/Eyeseryl-peptide-solution-G","https://incidecoder.com/ingredients/acetyl-tetrapeptide-5","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/fda-authority-over-cosmetics-how-cosmetics-are-not-fda-approved-are-fda-regulated","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/it-cosmetic-drug-or-both-or-it-soap"],"x":{"r":"El acetil tetrapéptido-5 (Eyeseryl) es un péptido de cuatro aminoácidos para cremas de contorno de ojos. Se usa para bolsas e hinchazón bajo los ojos y su evidencia viene casi toda del fabricante.","q":"Péptido 'señal' cosmético para el área periocular.","m":"Se le atribuyen dos acciones. Primero, un efecto antiedema: reduce la fuga de líquido de los vasos pequeños bajo el ojo, que es lo que causa la hinchazón. Segundo, limita la glicación, el proceso en que el azúcar se pega al colágeno y lo endurece, para que la piel fina conserve elasticidad.","mp":["Reduce la permeabilidad de capilares → menos líquido acumulado.","Frena la glicación del colágeno.","Mantiene más elástica la piel bajo los ojos."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Paneles de Lipotec (fabricante)","Voluntarios con fórmula del péptido","Reducción visible de bolsas e hinchazón"]],"en":"Evidencia baja: los datos del fabricante no se han reproducido en ensayos independientes.","s":["Enrojecimiento leve","Ardor","Alergia (rara)"],"sg":["Mantener fuera del ojo."]}},{"id":5,"n":"Afamelanotide","al":"","ar":"piel","ca":"fda","cl":"MC1R agonist","ev":"fda","u":"Agonista de melanocortina utilizado para aumentar la tolerancia a la luz en adultos con protoporfiria eritropoyética; no es un bronceador general.","c":"Análogo de α-MSH: activa MC1R y aumenta melanina en la piel.","m":"Scenesse · implante SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/afamelanotide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2019/210797s000lbl.pdf","https://www.mcgill.ca/oss/article/medical-critical-thinking-student-contributors-pseudoscience/barbie-drug-your-dermatologist-has-never-heard","https://www.ema.europa.eu/en/medicines/human/EPAR/scenesse","https://www.biospace.com/fda-approves-first-treatment-to-increase-pain-free-light-exposure-in-patients-with-a-rare-disorder","https://pubmed.ncbi.nlm.nih.gov/26132941/","https://pubmed.ncbi.nlm.nih.gov/32186677/","https://pubmed.ncbi.nlm.nih.gov/36041558/","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=94f53286-11dd-7fbb-e053-2a95a90a7c48"],"x":{"r":"Afamelanotide (Scenesse) es un análogo de larga duración de la hormona α-MSH. Activa el receptor MC1R para que la piel produzca más eumelanina protectora. Está aprobado desde 2019 en implante subcutáneo para adultos con protoporfiria eritropoyética (EPP), un trastorno raro de sensibilidad extrema a la luz.","q":"Un implante bajo la piel que oscurece la piel desde adentro para proteger contra la luz.","m":"En la EPP se acumula protoporfirina IX en la piel. Cuando le da la luz visible, genera especies reactivas de oxígeno que provocan un dolor quemante intenso tras pocos minutos al sol. Afamelanotide se une al receptor MC1R de los melanocitos y les ordena fabricar eumelanina, el pigmento oscuro que funciona como protector solar natural. Así se obtiene pigmento sin necesidad de daño por radiación UV.","mp":["Activa MC1R en los melanocitos.","Aumenta la eumelanina (pigmento oscuro protector).","La melanina absorbe luz y neutraliza radicales libres.","Resultado: más horas al sol sin dolor."],"f":"Aprobado por la FDA en 2019 como Scenesse para aumentar la exposición a la luz sin dolor en adultos con EPP.","e":[["Ensayo EE.UU. 2015","94 pacientes, doble ciego vs placebo","Mediana de 69.4 horas sin dolor al sol vs 40.8 con placebo (p=0.04)"],["Ensayo UE 2015","74 pacientes","6.0 vs 0.8 horas (p=0.005)"]],"en":"Aprobación basada en dos ensayos multicéntricos aleatorizados y controlados.","s":["Reacción en el sitio del implante","Náusea","Dolor de garganta y tos","Fatiga","Oscurecimiento de piel y de lunares","Mareo o somnolencia","Infecciones respiratorias"],"sg":["Hipersensibilidad grave, incluida anafilaxia (postmercadeo).","Requiere exámenes de piel completos periódicos para vigilar lunares."]}},{"id":6,"n":"Albiglutide","al":"","ar":"hormonas","ca":"fda","cl":"GLP-1 receptor agonist","ev":"fda","u":"Agonista GLP-1 desarrollado para diabetes tipo 2. Una aprobación histórica no implica que el producto siga comercializándose.","c":"Agonista GLP-1 unido a albúmina, de dosis semanal.","m":"Tanzeum · SC semanal","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/albiglutide","ci":["https://pmc.ncbi.nlm.nih.gov/articles/PMC4665069/","https://doi.org/10.1016/S0140-6736(18)32261-X","https://www.drugs.com/tanzeum.html"],"x":{"r":"Albiglutide (Tanzeum) fue un agonista GLP-1 semanal unido a albúmina humana, aprobado en 2014 para diabetes tipo 2. Mostró beneficio cardiovascular en HARMONY OUTCOMES, pero GSK lo retiró del mercado en 2018 por razones comerciales.","q":"Un GLP-1 de uso semanal, hoy fuera del mercado.","m":"Imita la hormona intestinal GLP-1 que el cuerpo libera al comer. Unir el péptido a la albúmina alarga mucho su vida media, lo que permite una inyección semanal.","mp":["Libera insulina solo cuando la glucosa está alta (bajo riesgo de hipoglucemia solo).","Baja el glucagón.","Retrasa el vaciado del estómago, menos que otros GLP-1.","Reduce eventos cardiovasculares en pacientes con enfermedad cardíaca."],"f":"Sigue con aprobación FDA, pero ya no se fabrica ni vende.","e":[["HARMONY OUTCOMES","Diabetes tipo 2 con enfermedad cardiovascular","Menos eventos cardiovasculares mayores vs placebo"]],"en":"Respaldado por el programa de ensayos HARMONY.","s":["Diarrea","Náusea","Reacción en sitio de inyección","Infección respiratoria alta"],"sg":["Advertencia en recuadro por tumores de células C de tiroides (roedores).","Pancreatitis.","Anafilaxia.","Hipoglucemia con insulina o sulfonilureas.","Daño renal por deshidratación."]}},{"id":7,"n":"Amycretin","al":"","ar":"digestivo","ca":"ensayos","cl":"Amylin + GLP-1 co-agonist","ev":"moderada","u":"Agonista de receptores de GLP-1 y amilina en investigación para obesidad; los resultados de ensayos no equivalen a una indicación aprobada.","c":"Activa a la vez receptores GLP-1 y de amilina en una sola molécula.","m":"Novo Nordisk · SC / oral (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/amycretin","ci":["https://doi.org/10.1016/S0140-6736(26)01247-X","https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1016/S0140-6736(25)01185-7","https://clinicaltrials.gov/study/NCT07339423","https://doi.org/10.1016/S0140-6736(25)01176-6"],"x":{"r":"Amycretin es una molécula experimental de Novo Nordisk que activa a la vez el receptor GLP-1 y el de amilina. Se estudia en inyección y en tableta para pérdida de peso. En un ensayo fase 1b/2a, la dosis de 60 mg bajó 24.3% del peso en 36 semanas frente a 1.1% con placebo, aunque muchos participantes abandonaron.","q":"Un co-agonista GLP-1 + amilina en una sola molécula, en investigación.","m":"Combina dos señales de saciedad. La parte GLP-1 actúa como semaglutide: sube insulina cuando la glucosa está alta, retrasa el vaciado gástrico y reduce el apetito. La parte de amilina imita una hormona del páncreas que da sensación de llenura. La apuesta es que ambas señales se suman y reducen la ingesta más que cada una por separado.","mp":["Activa receptor GLP-1 → menos apetito y mejor glucosa.","Activa receptor de amilina → más saciedad.","Una sola molécula con efecto doble."],"f":"No aprobado por la FDA ni por ningún regulador. Entrando a fase 3.","e":[["Fase 1b/2a subcutánea","125 adultos con sobrepeso u obesidad, hasta 36 semanas","−24.3% de peso con 60 mg vs −1.1% placebo; muchas descontinuaciones"],["Primer ensayo en humanos (oral)","12 semanas","Enfocado en seguridad y niveles; señales exploratorias de peso"]],"en":"Evidencia moderada: resultados grandes pero en estudios pequeños, cortos y con alta deserción. No hay datos de fase 3.","s":["Efectos gastrointestinales leves a moderados (náusea, vómito, diarrea)."],"sg":["Alta tasa de abandono en el ensayo; tolerabilidad a largo plazo desconocida."]}},{"id":8,"n":"Angiotensin II","al":"","ar":"corazon","ca":"fda","cl":"Vasopressor peptide","ev":"fda","u":"Vasopresor utilizado en el hospital para aumentar la presión arterial en adultos con shock distributivo seleccionado.","c":"Hormona natural que contrae los vasos y sube la presión arterial.","m":"Giapreza · infusión IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/angiotensin-ii","ci":["https://www.ncbi.nlm.nih.gov/books/NBK470410/","https://www.giapreza.com/","https://pubmed.ncbi.nlm.nih.gov/11751697/","https://www.accessdata.fda.gov/drugsatfda_docs/label/2017/209360s000lbl.pdf","https://doi.org/10.1056/NEJMoa1704154"],"x":{"r":"La angiotensina II es la hormona principal del sistema renina-angiotensina, que el cuerpo usa para subir la presión. Su versión sintética, Giapreza, se usa en cuidado intensivo para presión peligrosamente baja en choque séptico o distributivo. En el ensayo ATHOS-3 subió la presión en ~70% de los pacientes frente a 23% con placebo.","q":"Un vasopresor intravenoso de uso exclusivo hospitalario.","m":"Se une al receptor AT1 del músculo de los vasos sanguíneos y los contrae, lo que sube la presión rápidamente. Además estimula la liberación de aldosterona, que retiene sal y agua, y de vasopresina. Es útil porque sube la presión por una vía distinta a la norepinefrina y otras catecolaminas cuando estas no bastan.","mp":["Riñón libera renina → angiotensina I → (ECA) → angiotensina II.","Angiotensina II activa receptor AT1 → vasoconstricción.","Libera aldosterona y vasopresina."],"f":"Aprobado por la FDA como Giapreza para choque séptico u otro choque distributivo en adultos.","e":[["ATHOS-3","Pacientes con choque vasodilatador, doble ciego vs placebo","Presión arterial adecuada en ~70% vs 23% con placebo"]],"en":"Aprobación respaldada por un ensayo aleatorizado y controlado.","s":["Plaquetas bajas","Taquicardia","Infección por hongos","Delirio","Acidosis","Glucosa alta"],"sg":["Riesgo de trombosis (incluida TVP): se requiere profilaxis de tromboembolismo.","Isquemia periférica (manos y pies)."]}},{"id":9,"n":"AOD-9604","al":"","ar":"digestivo","ca":"wellness","cl":"GH fragment (lipolytic)","ev":"baja","u":"Fragmento modificado de hormona de crecimiento investigado para metabolismo de grasa; no hay eficacia clínica establecida para adelgazar.","c":"Fragmento modificado del extremo de la hormona de crecimiento.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/aod-9604","ci":["https://doi.org/10.1159/000053183","https://doi.org/10.1038/sj.ijo.0801740","https://pubmed.ncbi.nlm.nih.gov/23092275/","https://pubmed.ncbi.nlm.nih.gov/25208511/","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1058e17c-9261-459c-a3e6-fae38d196c14","https://pubmed.ncbi.nlm.nih.gov/24124033/","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://www.wada-ama.org/sites/default/files/2025-09/2026list_en_final_clean_september_2025.pdf"],"x":{"r":"AOD-9604 es un fragmento modificado del extremo de la hormona de crecimiento, desarrollado para quemar grasa. A diferencia de casi todos los péptidos wellness, sí se probó en humanos, y fracasó: no superó al placebo y se abandonó su desarrollo para obesidad en 2007. Está prohibido en el deporte.","q":"Un fragmento de la hormona de crecimiento (región 176-191 modificada) que se vende para pérdida de grasa.","m":"La teoría es que la cola de la hormona de crecimiento contiene su efecto quemagrasa sin el resto de efectos de la hormona. En animales y células, AOD-9604 aumentó la degradación y oxidación de grasa y redujo su almacenamiento, aparentemente sin activar el receptor de GH ni causar resistencia a la insulina.","mp":["Estimula la lipólisis (degradación de grasa) en animales.","No activaría el receptor de hormona de crecimiento.","En humanos, estos efectos no se tradujeron en pérdida de peso."],"f":"No aprobado por la FDA. Prohibido por la Agencia Mundial Antidopaje.","e":[["Fase 2b","536 participantes con obesidad, 24 semanas","Sin pérdida de peso significativa vs placebo"],["Estudio previo pequeño","Humanos","Señal inicial que no se replicó"]],"en":"Evidencia baja y además en contra: la mejor evidencia humana muestra que no funciona para bajar de peso.","s":["Sin datos de seguridad robustos fuera de los ensayos de obesidad."],"sg":["Producto del mercado gris: pureza y dosis inciertas."]}},{"id":10,"n":"Apraglutide","al":"","ar":"digestivo","ca":"ensayos","cl":"GLP-2 analog","ev":"moderada","u":"Análogo de GLP-2 investigado para síndrome de intestino corto; busca mejorar la absorción intestinal y reducir soporte parenteral.","c":"Análogo de GLP-2 de larga acción que mejora la absorción intestinal.","m":"SC semanal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/apraglutide","ci":["https://doi.org/10.1016/j.cgh.2026.08.026","https://doi.org/10.1016/j.clnu.2024.10.011"],"x":{"r":"Apraglutide es un análogo de GLP-2 de acción prolongada, desarrollado por Ironwood como inyección semanal para síndrome de intestino corto. En fase 3 redujo la necesidad de nutrición intravenosa frente a placebo, pero la FDA pidió un ensayo confirmatorio adicional.","q":"Un análogo de GLP-2 semanal para pacientes que dependen de nutrición parenteral.","m":"El GLP-2 es una hormona intestinal que hace crecer y adaptar la mucosa del intestino. En el intestino corto, la meta es que el tramo que queda absorba más, para que el paciente dependa menos de la alimentación por vena.","mp":["Estimula el crecimiento de la mucosa intestinal.","Enlentece el tránsito intestinal.","Aumenta la absorción de líquidos y nutrientes."],"f":"No aprobado; la FDA solicitó un ensayo confirmatorio.","e":[["STARS (fase 3)","Adultos con síndrome de intestino corto","Mayor reducción del volumen IV semanal y más pacientes con ≥1 día libre de soporte IV"],["Fase 2","Pacientes con SIC","Mejor absorción y menos soporte parenteral en un año"]],"en":"Evidencia moderada: un ensayo pivotal positivo, todavía sin replicar.","s":["Datos en evaluación (efectos gastrointestinales esperados para la clase)."],"sg":["Como otros GLP-2, se vigila crecimiento de pólipos intestinales."]}},{"id":11,"n":"Aviptadil","al":"","ar":"inmune","ca":"ensayos","cl":"Vasoactive intestinal peptide","ev":"baja","u":"Análogo de VIP investigado en enfermedades pulmonares y otras condiciones; su utilidad clínica depende de la indicación y el producto.","c":"Forma sintética de VIP; actúa sobre receptores pulmonares.","m":"IV / inhalado (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/aviptadil","ci":["https://pubmed.ncbi.nlm.nih.gov/5450698/","https://pmc.ncbi.nlm.nih.gov/articles/PMC10527239/","https://pmc.ncbi.nlm.nih.gov/articles/PMC8630992","https://pubmed.ncbi.nlm.nih.gov/12409234/","https://pubmed.ncbi.nlm.nih.gov/21951273/","https://pubmed.ncbi.nlm.nih.gov/22139413/","https://thepharmaletter.com/pharmaceutical/fda-declines-eua-for-aviptadil-for-patients-with-critical-covid-19-at-immediate-risk","https://www.globenewswire.com/news-release/2020/06/24/2052448/0/en/NeuroRx-and-Relief-Therapeutics-Announce-Fast-Track-Designation-Granted-by-the-FDA-to-RLF-100-Aviptadil-for-the-Treatment-of-Respiratory-Distress-in-COVID-19.html"],"x":{"r":"Aviptadil es una forma sintética del péptido intestinal vasoactivo (VIP). Se estudió sobre todo en insuficiencia respiratoria grave por COVID-19. En el ensayo TESICO de los NIH (461 pacientes) no fue mejor que placebo y se detuvo por futilidad.","q":"VIP sintético, también conocido como RLF-100 o Zyesami.","m":"El VIP es una molécula natural que relaja vasos y vías respiratorias y calma la inflamación, sobre todo en el pulmón. Actúa en los receptores VPAC1 y VPAC2, presentes en el tejido pulmonar y en células del sistema inmune. En animales bajó citoquinas inflamatorias (TNF, IL-6) y protegió a las células alveolares tipo II, que producen surfactante.","mp":["Activa receptores VPAC1/VPAC2.","Relaja músculo liso de vasos y bronquios.","Efecto antiinflamatorio en modelos animales."],"f":"No aprobado por la FDA para ningún uso.","e":[["TESICO (NIH)","461 pacientes críticos con COVID-19","Sin mejoría a 90 días (OR 1.11; p=0.54); mortalidad 38% vs 36%; detenido por futilidad"],["Fase 2b/3 de la compañía (2021)","Pacientes COVID-19","Resultados iniciales favorables reportados por el fabricante"]],"en":"Evidencia baja: el ensayo independiente mejor diseñado no confirmó beneficio.","s":["Hipotensión y diarrea son esperables por su efecto vasodilatador."],"sg":["Eficacia no establecida en sus usos estudiados."]}},{"id":12,"n":"Bacitracin","al":"","ar":"piel","ca":"fda","cl":"Polypeptide antibiotic","ev":"fda","u":"Antibiótico peptídico utilizado en productos tópicos para determinadas infecciones superficiales; puede producir dermatitis de contacto.","c":"Antibiótico polipeptídico que bloquea la pared celular de bacterias gram-positivas.","m":"Ungüento tópico","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/bacitracin","ci":["https://go.drugbank.com/drugs/DB00626","https://www.statpearls.com/point-of-care/18087","https://reference.medscape.com/drug/baciguent-bacitracin-topical-343464","https://pubmed.ncbi.nlm.nih.gov/8805732/","https://www.pharmacytimes.com/view/bacitracin-and-boo-boos-becoming-a-no-no"],"x":{"r":"La bacitracina es un antibiótico polipeptídico cíclico producido por la bacteria Bacillus. Mata bacterias gram-positivas al bloquear la construcción de su pared. Se vende sin receta como ungüento para cortaduras, raspones y quemaduras menores, a menudo combinado con neomicina y polimixina B.","q":"Un antibiótico tópico OTC, muy común en botiquines.","m":"Las bacterias construyen su pared celular con piezas que cruzan la membrana montadas en un transportador lipídico (C55). Ese transportador tiene que soltar un fosfato para reciclarse. La bacitracina se pega al transportador y le impide reciclarse, así que la bacteria se queda sin material para su pared y muere.","mp":["Bloquea el reciclaje del transportador C55-pirofosfato.","Detiene la síntesis de pared celular.","Activa sobre todo contra estafilococos y estreptococos.","Se absorbe poco por la piel: útil solo en superficie."],"f":"Aprobado por la FDA como antibiótico tópico OTC para prevenir infección en heridas menores. La forma inyectable se retiró.","e":[["Décadas de uso clínico","Población general","Prevención de infección en heridas superficiales"]],"en":"Aprobado y de uso establecido.","s":["Irritación local leve"],"sg":["Dermatitis alérgica de contacto: fue 'Alérgeno del Año' en 2003.","Anafilaxia (rara) aun con uso tópico.","La forma inyectable causaba daño renal y se retiró del mercado en EE.UU."]}},{"id":13,"n":"Balixafortide","al":"","ar":"corazon","ca":"ensayos","cl":"CXCR4 antagonist peptide","ev":"baja","u":"Antagonista CXCR4 investigado en oncología; bloquear una diana no garantiza beneficio clínico antitumoral.","c":"Bloquea el receptor CXCR4 junto a quimioterapia.","m":"IV (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/balixafortide","ci":["https://doi.org/10.1016/S1470-2045(18)30147-5","https://www.clinicaltrialsarena.com/news/polyphor-balixafortide-fails-breast-cancer-study/"],"x":{"r":"Balixafortide es un péptido experimental que bloquea el receptor CXCR4. Se estudió con la quimioterapia eribulina en cáncer de mama metastásico. Un estudio inicial pareció prometedor, pero el ensayo de fase 3 FORTRESS no mostró beneficio y el desarrollo se detuvo.","q":"Un antagonista de CXCR4 para oncología, en investigación.","m":"Bloquea la unión entre el receptor CXCR4 y su señal, CXCL12. Esa vía influye en cómo se mueven las células tumorales, en el ambiente que rodea al tumor y en las células inmunes. La hipótesis era que bloquearla haría al tumor más sensible a la quimioterapia.","mp":["Bloquea el eje CXCR4/CXCL12.","Busca sensibilizar el tumor a la quimioterapia."],"f":"No aprobado.","e":[["Fase 1","Cáncer de mama metastásico muy pretratado, sin grupo control","Respuestas parciales en ~30%"],["FORTRESS (fase 3)","Aleatorizado vs eribulina sola","No cumplió su objetivo primario"]],"en":"Evidencia baja: el ensayo controlado fue negativo.","s":["Sin perfil relevante fuera de ensayos."],"sg":[]}},{"id":14,"n":"Bivalirudin","al":"","ar":"corazon","ca":"fda","cl":"Direct thrombin inhibitor","ev":"fda","u":"Anticoagulante inhibidor directo de trombina utilizado en intervenciones coronarias; requiere valorar sangrado y función renal.","c":"Inhibidor directo y reversible de la trombina (derivado de hirudina).","m":"Angiomax · IV hospitalario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/bivalirudin","ci":["https://www.drugs.com/monograph/bivalirudin.html","https://link.springer.com/article/10.2165/00003495-200565130-00010","https://doi.org/10.1056/NEJMoa0708191","http://Drugs.com"],"x":{"r":"Bivalirudin (Angiomax) es un anticoagulante sintético de 20 aminoácidos inspirado en la hirudina de la sanguijuela. Bloquea directamente la trombina y se usa por vena durante angioplastias y colocación de stents, incluso en pacientes que no pueden recibir heparina.","q":"Un inhibidor directo y reversible de la trombina para el laboratorio de cateterismo.","m":"La trombina es la enzima central de la coagulación: convierte fibrinógeno en fibrina y activa plaquetas. Bivalirudin se agarra a la trombina en dos puntos, su sitio activo y una zona de anclaje llamada exositio 1. Por eso bloquea tanto la trombina libre como la que ya está dentro de un coágulo, cosa que la heparina hace peor. Su efecto es corto: desaparece unos 25 minutos después de parar la infusión.","mp":["Se une al sitio activo y al exositio 1 de la trombina.","Bloquea trombina libre y unida a coágulos.","Efecto reversible y breve (vida media ~25 min)."],"f":"Aprobado por la FDA como anticoagulante en procedimientos coronarios percutáneos.","e":[["HORIZONS-AMI","3,602 pacientes con infarto en angioplastia","Menos sangrado mayor y menor mortalidad cardíaca a 30 días vs heparina + inhibidor GPIIb/IIIa"]],"en":"Aprobado y respaldado por ensayos aleatorizados grandes.","s":["Dolor de espalda","Náusea","Hipotensión","Dolor de cabeza"],"sg":["Sangrado.","Mayor trombosis aguda del stent en las primeras 24 h (HORIZONS-AMI).","Ajustar infusión en insuficiencia renal."]}},{"id":15,"n":"BPC-157","al":"","ar":"digestivo","ca":"wellness","cl":"Synthetic pentadecapeptide (gastric-derived)","ev":"baja","u":"Péptido experimental estudiado sobre todo en modelos de reparación tisular y lesión gastrointestinal. No se ha establecido su eficacia ni seguridad para recuperar lesiones en humanos.","c":"Péptido sintético de 15 aminoácidos derivado del jugo gástrico.","m":"Inyectable / oral (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/bpc-157","ci":["https://doi.org/10.3390/ijms27062876","https://doi.org/10.3390/ph18060928","https://www.statnews.com/2026/06/01/bpc-157-researcher-predrag-sikiric-addesses-skeptics-questions/","https://doi.org/10.1177/15563316251355551","https://clinicaltrials.gov/study/NCT02637284","https://www.fda.gov/drugs/human-drug-compounding/bulk-drug-substances-used-compounding-under-section-503a-fdc-act","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://www.statnews.com/2026/07/24/fda-peptide-compounding-panel-backs-epitalon-rejects-emideltide/"],"x":{"r":"BPC-157 es un péptido sintético de 15 aminoácidos basado en una proteína del jugo gástrico. Es de los más pedidos en wellness para reparar tendones, músculo e intestino. En una revisión sistemática de 2025, 35 de 36 estudios eran en animales o laboratorio. El único reporte humano fue una serie de 12 pacientes sin grupo control.","q":"Un pentadecapéptido derivado de la 'Body Protection Compound' gástrica.","m":"Casi todo lo que se sabe viene de ratas y cultivos celulares. El hallazgo más consistente es que promueve la angiogénesis, la formación de vasos sanguíneos nuevos, por la vía VEGFR2-Akt-eNOS y a través del óxido nítrico. En laboratorio también aumentó colágeno, activó fibroblastos, bajó señales inflamatorias y aumentó el receptor de hormona de crecimiento en células de tendón. En animales tiene una vida media menor de 30 minutos.","mp":["Estimula formación de vasos nuevos (VEGFR2 / óxido nítrico).","Más colágeno y actividad de fibroblastos en laboratorio.","En roedores: cicatrización más rápida de tendón, músculo, hueso e intestino.","Nada de esto se ha confirmado en humanos con estudios controlados."],"f":"No aprobado por la FDA para ningún uso. Prohibido en el deporte. Su estatus en la revisión de compounding de la FDA sigue sin resolverse.","e":[["Revisión sistemática 2025","36 estudios","35 preclínicos, 1 humano"],["Modelo de tendón de Aquiles","Ratas","Mejor fuerza, elasticidad y función del tendón al día 14"],["Serie retrospectiva","12 pacientes con dolor crónico de rodilla, sin control","7 (58%) reportaron alivio por más de 6 meses tras una inyección"]],"en":"Evidencia baja: datos animales amplios y consistentes, pero sin ensayos controlados en humanos ni datos de seguridad a largo plazo.","s":["No hay datos de seguridad humanos publicados de calidad."],"sg":["Teórico: promover vasos nuevos podría ser indeseable en presencia de tumores.","Producto del mercado gris: pureza, esterilidad y dosis inciertas."]}},{"id":16,"n":"Bremelanotide","al":"","ar":"cerebro","ca":"fda","cl":"MC4R agonist","ev":"fda","u":"Agonista de melanocortina utilizado para un trastorno específico de deseo sexual hipoactivo en mujeres premenopáusicas; no es un potenciador sexual universal.","c":"Activa receptores melanocortina (MC4R) en el cerebro.","m":"Vyleesi · autoinyector SC a demanda","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/bremelanotide","ci":["https://www.sciencedirect.com/topics/medicine-and-dentistry/bremelanotide","https://palatin.com/press_releases/fda-approves-new-drug-application-for-vyleesi-bremelanotide-injection-2/","https://www.accessdata.fda.gov/drugsatfda_docs/label/2019/210557s000lbl.pdf","https://doi.org/10.1097/AOG.0000000000003500","https://doi.org/10.1080/00224499.2023.2175192"],"x":{"r":"Bremelanotide (Vyleesi) es un péptido de siete aminoácidos que actúa en el cerebro para aumentar el deseo sexual. A diferencia del sildenafil, no trabaja sobre el flujo de sangre. Está aprobado para mujeres premenopáusicas con trastorno de deseo sexual hipoactivo (HSDD) adquirido y generalizado, con un beneficio modesto pero significativo en los ensayos RECONNECT.","q":"Un agonista de receptores de melanocortina (MC4R) que se autoinyecta a demanda.","m":"El deseo sexual depende del balance entre señales que excitan y señales que inhiben en el cerebro. Bremelanotide activa receptores de melanocortina, sobre todo MC4R, en zonas del sistema nervioso central que regulan el deseo, y empuja ese balance hacia la excitación. Trata el deseo en sí, no la respuesta física.","mp":["Activa MC4R en el cerebro.","Inclina el balance de señales hacia la excitación.","Se usa solo antes de la actividad sexual, no a diario."],"f":"Aprobado por la FDA en 2019 como Vyleesi. Lo que se vende en internet como 'PT-141' no es el producto aprobado.","e":[["RECONNECT (2 ensayos fase 3)","1,267 mujeres premenopáusicas con HSDD, 24 semanas","Deseo +0.35 puntos y angustia −0.33 puntos más que placebo (p<.001)"],["Reanálisis independiente","Datos de RECONNECT","Beneficio estadísticamente modesto"]],"en":"Aprobado con ensayos aleatorizados; el tamaño del efecto es pequeño.","s":["Náusea (muy frecuente, a veces requiere antiemético)","Rubor","Dolor de cabeza","Vómito","Reacción en el sitio de inyección"],"sg":["Sube la presión y baja la frecuencia cardíaca de forma transitoria tras cada dosis: evitar en riesgo cardiovascular o hipertensión no controlada.","Hiperpigmentación focal (cara, encías) con uso frecuente.","Reduce la absorción de naltrexona oral."]}},{"id":17,"n":"Brilacidin","al":"","ar":"digestivo","ca":"ensayos","cl":"Defensin-mimetic host-defense peptide","ev":"baja","u":"Molécula que imita péptidos de defensa, investigada por actividad antimicrobiana e inflamatoria; no debe asumirse eficacia por resultados de laboratorio.","c":"Imita a los péptidos de defensa del cuerpo (defensinas).","m":"IV / enjuague (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/brilacidin","ci":["https://doi.org/10.3390/v13020271","https://doi.org/10.1002/jmv.27616"],"x":{"r":"Brilacidin es una molécula experimental que imita los péptidos de defensa propios del cuerpo (defensinas). Innovation Pharmaceuticals la estudia para mucositis oral y como antibacteriano y antiviral. Sus resultados en humanos solo se han anunciado en comunicados de prensa, no en estudios publicados.","q":"Un mimético de defensinas (molécula pequeña), en investigación.","m":"Las defensinas son péptidos del sistema inmune que rompen las membranas de los microbios. Brilacidin copia su patrón de cargas eléctricas para hacer lo mismo con bacterias y hongos. En laboratorio también alteró al virus SARS-CoV-2 y su entrada a las células, y se le atribuye un efecto antiinflamatorio en mucositis.","mp":["Se une a la membrana del microbio por su carga.","Desestabiliza la membrana → muerte bacteriana o fúngica.","En cultivo celular inhibió coronavirus."],"f":"No aprobado para ningún uso.","e":[["Fase 2 mucositis oral","Humanos","Positivo según comunicado de la compañía (no revisado por pares)"],["Fase 2 COVID-19","Humanos","Positivo según comunicado (no revisado por pares)"],["Estudios de laboratorio","Cultivo celular","Inhibe SARS-CoV-2 y otros coronavirus (publicado)"]],"en":"Evidencia baja: sin datos clínicos controlados publicados.","s":["Sin perfil publicado de calidad."],"sg":[]}},{"id":18,"n":"Cagrilintide","al":"","ar":"digestivo","ca":"ensayos","cl":"Long-acting amylin analog","ev":"moderada","u":"Análogo de amilina investigado para control de peso, solo y en combinación; no debe confundirse con un medicamento aprobado por tener resultados clínicos prometedores.","c":"Análogo de amilina de larga acción: aumenta saciedad.","m":"Novo Nordisk · SC semanal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/cagrilintide","ci":["https://doi.org/10.1016/S0140-6736(21)01751-7","https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1056/NEJMoa2502081","https://clinicaltrials.gov/study/NCT07220642","https://www.fda.gov/drugs/drug-alerts-and-statements/fdas-concerns-unapproved-glp-1-drugs-used-weight-loss","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4aea30ff-eb0d-45c1-b114-3127966328ff","https://pubmed.ncbi.nlm.nih.gov/34798060/","https://pubmed.ncbi.nlm.nih.gov/40544433/"],"x":{"r":"Cagrilintide es un análogo de amilina de acción prolongada que Novo Nordisk desarrolla como inyección semanal para control de peso. Un ensayo de fase 2 de 26 semanas mostró pérdida de peso. La mayor parte de su desarrollo avanzado es como componente de CagriSema.","q":"Un análogo de amilina semanal, en investigación.","m":"La amilina es una hormona que el páncreas libera junto a la insulina. Cagrilintide la imita y activa los receptores de amilina y calcitonina. Eso aumenta la saciedad, enlentece el vaciado del estómago y baja el glucagón después de comer. Como es una vía distinta a GLP-1, se estudia combinado con semaglutide.","mp":["Activa receptores de amilina/calcitonina.","Más saciedad y menos ingesta.","Vaciado gástrico más lento.","Menos glucagón después de las comidas."],"f":"No aprobado por la FDA ni otro regulador. Hay un ensayo de fase 3 en curso como monoterapia.","e":[["Fase 2 de búsqueda de dosis","706 adultos con sobrepeso/obesidad sin diabetes, 26 semanas","Pérdida de peso en todas las dosis vs placebo"],["Estudio QT 2024","105 voluntarios sanos","Sin prolongación QTc relevante con 4.5 mg"]],"en":"Evidencia moderada: un solo ensayo de fase 2 positivo.","s":["Efectos gastrointestinales en 41–63% según dosis vs 32% placebo, sobre todo náusea"],"sg":["Datos de seguridad más allá de 26 semanas son limitados."]}},{"id":19,"n":"CagriSema","al":"","ar":"digestivo","ca":"ensayos","cl":"Amylin + GLP-1 combination","ev":"alta","u":"Combinación de cagrilintide y semaglutide estudiada para obesidad y diabetes; la evidencia de cada componente no valida mezclas preparadas distintas.","c":"Combina cagrilintide (amilina) + semaglutide (GLP-1).","m":"Novo Nordisk · SC semanal","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/cagrisema","ci":["https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1016/S0140-6736(21)01751-7","https://www.sec.gov/Archives/edgar/data/353278/000035327826000006/caq42025.htm","https://doi.org/10.1056/NEJMoa2502081","https://doi.org/10.1056/NEJMoa2502082","https://www.fda.gov/drugs/drug-alerts-and-statements/fdas-concerns-unapproved-glp-1-drugs-used-weight-loss","https://pubmed.ncbi.nlm.nih.gov/35658024/","https://www.sec.gov/Archives/edgar/data/353278/000117184326000996/f6k_022326.htm"],"x":{"r":"CagriSema combina cagrilintide (amilina) y semaglutide (GLP-1) en una inyección semanal. En dos ensayos grandes de fase 3 produjo cerca de 20% de pérdida de peso en obesidad. Sin embargo, quedó por debajo de lo esperado y en un estudio cara a cara no igualó a tirzepatide. Está en revisión por la FDA.","q":"Combinación de dos péptidos de saciedad en una sola inyección, en investigación.","m":"Suma dos vías del apetito. Semaglutide activa el receptor GLP-1: libera insulina cuando la glucosa está alta, retrasa el vaciado gástrico y reduce el hambre. Cagrilintide imita a la amilina: agrega otra señal de llenura y baja el glucagón. La idea es que las dos señales se complementen.","mp":["GLP-1 (semaglutide): menos apetito y mejor glucosa.","Amilina (cagrilintide): más saciedad.","Juntas: mayor reducción de ingesta."],"f":"No aprobado aún; bajo revisión de la FDA en 2026.","e":[["REDEFINE 1","Obesidad sin diabetes, 68 semanas","≈ −20% de peso vs ≈ −3% placebo"],["REDEFINE 2","Obesidad + diabetes tipo 2","≈ −14% de peso; mayoría alcanzó meta de glucosa"],["REDEFINE 4 (comunicado 2026)","Cara a cara vs tirzepatide 15 mg, 84 semanas","No demostró no-inferioridad frente a tirzepatide"]],"en":"Evidencia alta frente a placebo, con la salvedad de que no superó a tirzepatide.","s":["Efectos gastrointestinales en 72–80%: náusea, vómito, diarrea, estreñimiento (mayormente leves y pasajeros)"],"sg":["Advertencia de tumores tiroideos de células C (componente semaglutide); evitar con historial de carcinoma medular de tiroides o MEN2.","Pancreatitis.","Enfermedad de vesícula y cálculos biliares."]}},{"id":20,"n":"Calcitonin-salmon","al":"Miacalcin (injection); nasal spray sold as a generic","ar":"huesos","ca":"fda","cl":"Calcitonin receptor agonist","ev":"fda","u":"Hormona que reduce la resorción ósea; sus usos dependen de la formulación e incluyen ciertas alteraciones del calcio y del hueso.","c":"Hormona que frena la resorción (destrucción) de hueso.","m":"Miacalcin · inyección / spray nasal","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/calcitonin-salmon","ci":["https://www.drugs.com/monograph/calcitonin-salmon.html","https://go.drugbank.com/drugs/DB00017","https://doi.org/10.1016/s0002-9343(00)00490-3","https://www.ema.europa.eu/en/medicines/human/referrals/calcitonin","http://Drugs.com"],"x":{"r":"La calcitonina de salmón es la versión sintética de una hormona que frena la destrucción del hueso. Está aprobada para osteoporosis posmenopáusica, enfermedad de Paget y calcio alto en sangre. Hoy es de segunda línea por su efecto modesto en fracturas y una pequeña señal de cáncer con uso prolongado.","q":"Hormona calcitonina (de salmón, más potente que la humana) en inyección o spray nasal.","m":"El hueso se remodela constantemente: los osteoclastos lo disuelven y otras células lo reconstruyen. La calcitonina se une a receptores de los osteoclastos y los frena, de modo que sale menos calcio del hueso a la sangre. Además hace que el riñón elimine más calcio por la orina.","mp":["Se une al receptor de calcitonina en osteoclastos.","Disminuye la resorción ósea.","Aumenta la eliminación renal de calcio.","Baja el calcio en sangre y protege el hueso modestamente."],"f":"Aprobada por la FDA (Miacalcin inyectable; spray nasal genérico).","e":[["PROOF","1,255 mujeres posmenopáusicas, 5 años, spray nasal","200 UI diarias redujeron fracturas vertebrales nuevas ~33% vs placebo"],["Reevaluación regulatoria 2013","Datos combinados","Pequeño aumento de cáncer con uso prolongado"]],"en":"Aprobada; beneficio en fracturas modesto y dosis-respuesta poco consistente.","s":["Spray: irritación, sequedad o sangrado nasal","Inyección: náusea y rubor"],"sg":["Pequeño aumento de riesgo de cáncer con uso prolongado: usar el menor tiempo posible.","Reacciones alérgicas graves.","Hipocalcemia."]}},{"id":21,"n":"Carnosine","al":"","ar":"piel","ca":"cosmetico","cl":"Antioxidant dipeptide","ev":"baja","u":"Dipéptido estudiado por propiedades antioxidantes y antiglicación; los reclamos de rejuvenecimiento exceden la evidencia clínica disponible.","c":"Dipéptido natural (β-alanina + histidina) que protege contra oxidación y glicación.","m":"Tópico (también suplemento oral)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/carnosine","ci":["https://doi.org/10.1111/php.13850"],"x":{"r":"La carnosina es un dipéptido natural (β-alanina + histidina) que se usa en cosméticos como antioxidante. En laboratorio neutraliza radicales libres y frena la glicación que endurece la piel. Faltan estudios humanos sólidos de la carnosina sola.","q":"Ingrediente cosmético antioxidante; también se vende como suplemento oral.","m":"Tiene dos acciones propuestas. Como antioxidante, neutraliza las especies reactivas de oxígeno que generan la luz UV y la contaminación. Como antiglicante, impide que el azúcar se pegue al colágeno y forme productos de glicación avanzada (AGEs), que lo vuelven rígido.","mp":["Neutraliza radicales libres generados por UV.","Bloquea la formación de AGEs en el colágeno.","Ayuda a mantener la piel flexible (en laboratorio)."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Estudio ex vivo en piel humana","Piel donada en laboratorio","Menos radicales libres y marcadores de glicación tras UV"]],"en":"Evidencia baja: no hay ensayos humanos controlados con carnosina sola; suele venir dentro de fórmulas con muchos ingredientes.","s":["Bien tolerada; baja irritación"],"sg":[]}},{"id":22,"n":"Cerebrolysin","al":"","ar":"cerebro","ca":"wellness","cl":"Neuropeptide preparation (porcine brain)","ev":"baja","u":"Mezcla de péptidos de origen porcino estudiada en enfermedades neurológicas; el uso en otros países no equivale a aprobación de FDA.","c":"Mezcla de péptidos de cerebro porcino con efecto neurotrófico.","m":"IV / IM (no aprobado en EE.UU.)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/cerebrolysin","ci":["https://doi.org/10.1016/j.kjms.2014.02.009","https://doi.org/10.1007/s00401-006-0166-5","https://doi.org/10.1007/978-3-7091-6781-6_29","https://doi.org/10.1007/s10072-021-05089-2","https://doi.org/10.1002/14651858.CD007026.pub7","https://doi.org/10.1002/14651858.CD008900.pub3","https://doi.org/10.1016/j.cccb.2021.100012","https://pubmed.ncbi.nlm.nih.gov/33515100/"],"x":{"r":"Cerebrolysin es una mezcla de péptidos pequeños y aminoácidos extraída de cerebro de cerdo. Se usa en algunos países para derrame cerebral y demencia y se vende en otros para cognición. Tiene muchos ensayos humanos, pero las revisiones no encontraron beneficio claro tras un derrame y solo una señal débil en demencia vascular.","q":"Preparación neuropeptídica de origen porcino; no es un péptido único definido.","m":"Se propone que actúa como los factores neurotróficos del cerebro, las señales que mantienen vivas y funcionando a las neuronas. En modelos animales y de laboratorio protegió neuronas, redujo la muerte celular programada (apoptosis) y el daño por exceso de glutamato (excitotoxicidad). Como es una mezcla, sus componentes activos exactos no se conocen bien.","mp":["Efecto tipo factor neurotrófico.","Neuroprotección y antiapoptosis en animales.","Componentes activos no bien caracterizados."],"f":"No aprobado por la FDA; aprobado en algunos otros países.","e":[["Revisión Cochrane (ictus isquémico agudo)","Múltiples ensayos","Sin beneficio en mortalidad; posible aumento de eventos adversos graves no fatales"],["Revisión Cochrane (demencia vascular)","Múltiples ensayos","Señal en cognición, quizás demasiado pequeña para importar; evidencia de muy baja calidad"]],"en":"Evidencia baja: mucha investigación humana, pero los resultados combinados no muestran beneficio claro.","s":["Mareo, dolor de cabeza, sudoración, reacciones en el sitio de inyección"],"sg":["Posible aumento de eventos adversos graves no fatales (Cochrane, ictus).","Producto de origen animal; calidad variable fuera de mercados regulados."]}},{"id":23,"n":"Cetrorelix","al":"","ar":"sexual","ca":"fda","cl":"GnRH antagonist","ev":"fda","u":"Antagonista de GnRH utilizado en reproducción asistida para evitar un pico prematuro de LH.","c":"Antagonista GnRH: bloquea LH/FSH rápidamente.","m":"Cetrotide · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/cetrorelix","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2023/021197s017s022lbl.pdf","https://go.drugbank.com/drugs/DB00050","https://doi.org/10.1016/s0015-0282(99)00524-5","https://doi.org/10.1002/14651858.CD001750.pub4"],"x":{"r":"Cetrorelix (Cetrotide) es un péptido de diez aminoácidos que bloquea el receptor de GnRH en la hipófisis. Se usa en fertilización in vitro (FIV) para evitar que la mujer ovule antes de tiempo, de modo que los óvulos maduren y se recolecten según el plan.","q":"Un antagonista de GnRH inyectable de uso en clínicas de fertilidad.","m":"Durante la estimulación ovárica, los folículos crecen y el estrógeno sube. Eso puede provocar un pico prematuro de LH que hace soltar los óvulos antes de la recolección y arruina el ciclo. Cetrorelix ocupa el receptor de GnRH y frena de inmediato la liberación de LH y FSH. A diferencia de los agonistas de GnRH, no causa un 'flare' inicial y su efecto es rápido y reversible, así que se usa solo unos días.","mp":["Compite con la GnRH natural por su receptor.","Suprime LH y FSH en horas.","Evita el pico prematuro de LH.","Sin efecto 'flare' inicial."],"f":"Aprobado por la FDA como Cetrotide para prevenir el pico prematuro de LH en estimulación ovárica controlada.","e":[["Ensayo multicéntrico aleatorizado","Mujeres en FIV","Una dosis de 3 mg evitó el pico de LH en todas; menos días de estimulación"],["Revisión Cochrane","Protocolos antagonista vs agonista largo","Menos síndrome de hiperestimulación ovárica, sin diferencia en nacidos vivos"]],"en":"Aprobado y respaldado por ensayos y metanálisis.","s":["Enrojecimiento, picor o hinchazón en el sitio de inyección","Náusea","Dolor de cabeza"],"sg":["Síndrome de hiperestimulación ovárica (riesgo del ciclo de FIV).","Reacciones de hipersensibilidad, raramente graves."]}},{"id":24,"n":"CJC-1295","al":"","ar":"huesos","ca":"wellness","cl":"GHRH analog (secretagogue)","ev":"baja","u":"Análogo de GHRH investigado para estimular GH e IGF-1; no tiene eficacia establecida como tratamiento de rejuvenecimiento o recuperación deportiva.","c":"Análogo de GHRH de larga acción que eleva GH e IGF-1.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/cjc-1295","ci":["https://pubmed.ncbi.nlm.nih.gov/16352683/","https://pubmed.ncbi.nlm.nih.gov/17018654/","https://doi.org/10.1210/jc.2005-1536","https://doi.org/10.1530/eje.1.01965","https://pubmed.ncbi.nlm.nih.gov/15817669/","https://pubmed.ncbi.nlm.nih.gov/42395176/","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://pubmed.ncbi.nlm.nih.gov/7962295/"],"x":{"r":"CJC-1295 es un análogo sintético de la hormona liberadora de hormona de crecimiento (GHRH). Una sola inyección subió la hormona de crecimiento de 2 a 10 veces por 6 días o más en adultos sanos. Sin embargo, ningún ensayo controlado demuestra beneficio en músculo, grasa, recuperación o antienvejecimiento.","q":"Un secretagogo de GH. Se venden dos versiones: con DAC (larga acción) y sin DAC (Mod GRF 1-29, corta).","m":"El hipotálamo envía GHRH a la hipófisis para que libere hormona de crecimiento en pulsos. CJC-1295 activa ese mismo receptor y amplifica los pulsos, lo que sube la GH y después el IGF-1. Los beneficios que se mercadean son una inferencia a partir de esa subida hormonal, no resultados demostrados.","mp":["Activa el receptor de GHRH en la hipófisis.","Aumenta la liberación de GH.","El hígado produce más IGF-1.","Los efectos en composición corporal no se han probado."],"f":"No aprobado por la FDA. No es elegible para compounding de rutina. Prohibido en el deporte.","e":[["Teichman 2006 (2 ensayos)","Adultos sanos de 21 a 61 años, vs placebo","GH media ×2–10 por ≥6 días; IGF-1 ×1.5–3 tras una dosis"],["Estudio de GHRH de larga acción","Adultos mayores","Subida hormonal con algo de intolerancia a la glucosa"]],"en":"Evidencia baja: solo estudios cortos de niveles hormonales. La combinación con ipamorelin no tiene ningún ensayo publicado.","s":["Reacciones leves locales y sistémicas en estudios cortos (rubor, dolor de cabeza)"],"sg":["La FDA identificó eventos serios: aumento de frecuencia cardíaca y reacción vasodilatadora sistémica.","Puede empeorar la tolerancia a la glucosa.","Sin datos de seguridad a largo plazo."]}},{"id":25,"n":"Gonadorelin","al":"","ar":"sexual","ca":"wellness","cl":"GnRH (native)","ev":"baja","u":"Análogo de GnRH relacionado con pruebas y tratamientos del eje reproductivo. Las preparaciones compuestas requieren evaluación específica del producto y del uso.","c":"GnRH sintético: estimula LH y FSH de la hipófisis.","m":"Inyectable SC (compounding)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/compounded-gonadorelin","ci":["https://pubmed.ncbi.nlm.nih.gov/32777865/","https://doi.org/10.1159/000057944"],"x":{"r":"La gonadorelina es una forma sintética de la GnRH natural. En clínicas de salud masculina se usa como complemento de la terapia de testosterona para conservar la fertilidad y el tamaño testicular. Su mecanismo está bien establecido, pero hay muy poca evidencia directa para ese uso y no existe producto aprobado por la FDA para eso.","q":"GnRH sintética idéntica a la natural (decapéptido).","m":"Cuando se administra en pulsos, la GnRH hace que la hipófisis libere LH y FSH, que a su vez estimulan al testículo a fabricar testosterona y espermatozoides. El detalle clave es que la exposición continua tiene el efecto opuesto y apaga el sistema. Por eso el uso depende de dosis intermitentes y de su vida media muy corta.","mp":["Pulsos de GnRH → hipófisis libera LH y FSH.","LH → testosterona intratesticular; FSH → producción de esperma.","Exposición continua → desensibiliza y apaga el eje."],"f":"No hay producto aprobado por la FDA para el uso como complemento de TRT. Verificar el estatus de compounding vigente.","e":[["Metanálisis 2021","420 hombres con hipogonadismo hipogonadotrópico congénito, 7 estudios","GnRH pulsátil inició producción de esperma 5.3 meses antes que gonadotropinas (p=0.004); sin diferencia en embarazos"],["Uso como complemento de TRT","Práctica clínica","Sin ensayos controlados dedicados"]],"en":"Evidencia baja para el uso que se mercadea; la buena evidencia es de otra población.","s":["Dolor o reacción en el sitio de inyección","Dolor de cabeza"],"sg":["Reacciones de hipersensibilidad.","El uso continuo puede suprimir el eje en vez de estimularlo."]}},{"id":26,"n":"Tesamorelin (uso wellness)","al":"","ar":"hormonas","ca":"wellness","cl":"GHRH analog","ev":"moderada","u":"Grasa abdominal (uso wellness fuera de indicación).","c":"Análogo de GHRH que eleva la hormona de crecimiento.","m":"Egrifta (aprobado solo para lipodistrofia por VIH)","a":"Uso wellness es off-label. Vigilar glucosa.","src":"https://superpower.com/guides/peptides/compounded-tesamorelin","ci":["https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=3d783378-b02d-4f19-99dd-0fc91a042224","https://doi.org/10.1097/QAI.0b013e3181cbdaff","https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=839334d3-8c1d-4c26-9036-2ab524a6ea75","https://doi.org/10.1097/QAD.0b013e32830a5058"],"x":{"r":"Tesamorelin (Egrifta) es un análogo de GHRH aprobado solo para la grasa abdominal excesiva en lipodistrofia asociada a VIH. Su uso wellness en personas sin VIH, para composición corporal o antienvejecimiento, no tiene ensayos dedicados. Además, la grasa regresa al suspenderlo.","q":"El uso 'off-label' de un GHRH aprobado.","m":"Se une al receptor de GHRH en la hipófisis y aumenta la liberación de la propia hormona de crecimiento, lo que sube el IGF-1. La GH tiene efecto anabólico y lipolítico (degrada grasa), y la grasa visceral es la que más responde.","mp":["Activa receptor de GHRH.","Aumenta GH e IGF-1.","Reduce grasa visceral en la población aprobada.","Efecto desaparece al suspender."],"f":"Aprobado solo para lipodistrofia por VIH. El uso en otras poblaciones es off-label. Prohibido en el deporte.","e":[["Falutz 2010","404 personas con VIH, vs placebo, 6 meses","Grasa visceral −10.9% vs −0.6%"],["Extensión de 52 semanas","Misma población","≈ −18% a 12 meses; la grasa regresó al detenerlo"],["Uso en personas sin VIH","—","Sin ensayos controlados dedicados"]],"en":"Evidencia moderada para el uso wellness: sólida en VIH, extrapolada para todo lo demás.","s":["Dolor articular","Reacción en sitio de inyección","Hinchazón de extremidades","Dolor muscular"],"sg":["Subida de IGF-1 y posible intolerancia a la glucosa.","Contraindicado en embarazo."]}},{"id":27,"n":"Copper tripeptide-1","al":"GHK-Cu","ar":"piel","ca":"cosmetico","cl":"Carrier/copper peptide","ev":"moderada","u":"Nombre cosmético de un complejo de cobre con GHK. La evidencia de aplicación tópica no establece seguridad ni beneficio de la vía inyectable.","c":"Tripéptido GHK unido a cobre; señales de reparación y colágeno.","m":"GHK-Cu · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/copper-tripeptide-1","ci":["https://doi.org/10.1155/2015/648108","https://doi.org/10.3390/brainsci7020020","https://doi.org/10.1163/156856208784909435","https://doi.org/10.1001/archfaci.8.4.252","https://doi.org/10.1002/jor.22831","https://doi.org/10.18632/oncotarget.11168"],"x":{"r":"El tripéptido de cobre-1, conocido como GHK-Cu, es un péptido de tres aminoácidos (glicina-histidina-lisina) unido a cobre que se usa en cremas para renovar la piel. En laboratorio estimula colágeno, pero el único ensayo humano independiente, tras láser CO2, no mostró diferencia objetiva.","q":"Ingrediente cosmético tópico (distinto al GHK-Cu inyectable del mercado wellness).","m":"En células y animales funciona como una señal de reparación: estimula a los fibroblastos a producir colágeno, elastina y glicosaminoglicanos, regula las enzimas que degradan la matriz, aporta cobre para la cicatrización y tiene efecto antioxidante.","mp":["Activa fibroblastos → más colágeno y elastina.","Equilibra las enzimas que degradan la matriz.","Aporta cobre para la reparación.","Efecto antioxidante."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Ensayo aleatorizado tras láser CO2","13 pacientes","Sin diferencia en enrojecimiento ni calidad de piel por evaluadores ciegos; pacientes la calificaron mejor (p=0.04)"],["Revisiones de laboratorio","Células y animales","Más síntesis de matriz y mejor cicatrización"]],"en":"Evidencia moderada: mecanismo muy estudiado, pero poca prueba humana independiente.","s":["Bien tolerado","Irritación con concentraciones altas de cobre"],"sg":["Se desestabiliza con ácidos fuertes (vitamina C alta, exfoliantes): no aplicar al mismo tiempo."]}},{"id":28,"n":"Corticotropin","al":"ACTH","ar":"hormonas","ca":"fda","cl":"Melanocortin / ACTH","ev":"fda","u":"ACTH utilizada en indicaciones seleccionadas, incluidas algunas enfermedades inflamatorias y espasmos infantiles según producto; no es un suplemento hormonal.","c":"ACTH: estimula a las suprarrenales a producir cortisol.","m":"Acthar Gel / Cortrophin Gel · IM/SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/corticotropin","ci":["https://pubmed.ncbi.nlm.nih.gov/8604274/","https://www.acthar.com/Static/pdf/Acthar-PI.pdf"],"x":{"r":"La corticotropina (ACTH; Acthar Gel, Purified Cortrophin Gel) es una hormona que hace que las suprarrenales fabriquen sus propios esteroides y que también actúa directamente sobre células inmunes. Aprobada desde 1952, hoy se usa para espasmos infantiles, brotes de esclerosis múltiple y otras condiciones inflamatorias.","q":"ACTH de 39 aminoácidos en gel de liberación prolongada.","m":"Actúa de dos formas. Su acción clásica es unirse al receptor MC2 de la corteza suprarrenal y estimular la producción de cortisol, de modo que gran parte de su efecto antiinflamatorio es indirecto. Además se une a otros receptores de melanocortina en células inmunes y tiene efectos antiinflamatorios independientes de los esteroides.","mp":["Receptor MC2 suprarrenal → cortisol endógeno.","Receptores de melanocortina en células inmunes → efecto directo.","Efectos secundarios parecidos a los de los corticosteroides."],"f":"Aprobada por la FDA desde 1952; la indicación de espasmos infantiles se formalizó en 2010.","e":[["Estudio controlado en espasmos infantiles","Lactantes","ACTH en dosis alta fue más eficaz que prednisona para detener los espasmos"]],"en":"Aprobada; evidencia controlada en espasmos infantiles y uso clínico prolongado en el resto.","s":["Reacción en el sitio de inyección","Fatiga","Retención de líquido","Insomnio y dolor de cabeza","Glucosa alta"],"sg":["Más riesgo de infecciones.","Supresión suprarrenal al suspender: no parar de golpe.","En niños: retraso del crecimiento; sangrado gastrointestinal.","En lactantes: hipertensión, convulsiones, irritabilidad."]}},{"id":29,"n":"Cosyntropin","al":"","ar":"hormonas","ca":"fda","cl":"ACTH(1-24) analog","ev":"fda","u":"Análogo de ACTH utilizado en pruebas de estimulación suprarrenal; sirve para evaluación diagnóstica, no para fortalecer las glándulas.","c":"Fragmento sintético de ACTH; se mide el cortisol después.","m":"Cortrosyn · IV/IM","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/cosyntropin","ci":["https://doi.org/10.1210/jc.2008-0710","https://www.accessdata.fda.gov/drugsatfda_docs/label/2023/016750s033lbl.pdf"],"x":{"r":"Cosyntropin (Cortrosyn) es un fragmento sintético de ACTH (1-24) que se usa como prueba diagnóstica. Se inyecta una dosis y se mide cuánto sube el cortisol para saber si las suprarrenales funcionan bien.","q":"Agente diagnóstico para insuficiencia suprarrenal.","m":"Se une al mismo receptor que la ACTH natural (MC2) en la corteza suprarrenal y provoca la liberación de cortisol. Se mide el cortisol antes y después de la inyección. Una suprarrenal sana responde con una subida clara; una respuesta pobre indica insuficiencia suprarrenal.","mp":["Cortisol basal.","Inyección de cosyntropin.","Cortisol a los 30 y/o 60 minutos.","Subida baja = sospecha de insuficiencia."],"f":"Aprobado por la FDA como agente diagnóstico.","e":[["Metanálisis de protocolos","Pacientes con sospecha de insuficiencia","La prueba de dosis baja detectó mejor la insuficiencia central que la dosis estándar"]],"en":"Aprobado y de uso establecido.","s":["Bradicardia o taquicardia","Hipertensión","Edema","Erupción"],"sg":["Reacciones alérgicas, incluida anafilaxia."]}},{"id":30,"n":"Cyclosporine","al":"","ar":"inmune","ca":"fda","cl":"Cyclic peptide immunosuppressant","ev":"fda","u":"Inmunosupresor inhibidor de calcineurina con usos sistémicos y oftálmicos. Las formulaciones y vías no son intercambiables automáticamente.","c":"Péptido cíclico que suprime la activación de linfocitos T.","m":"Sandimmune, Neoral (oral/IV), Restasis (gotas)","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/cyclosporine","ci":["https://doi.org/10.1056/NEJM198310063091401"],"x":{"r":"La ciclosporina (Sandimmune, Neoral, Restasis) es un péptido cíclico de un hongo que suprime el sistema inmune. Cambió los trasplantes de órganos en los años 80. Se usa en forma oral, IV y en gotas para ojo seco.","q":"Inmunosupresor inhibidor de calcineurina, péptido cíclico de 11 aminoácidos.","m":"Entra a los linfocitos T y se une a la ciclofilina. Ese complejo bloquea la calcineurina, una enzima que activa el factor NFAT, que a su vez enciende el gen de la interleucina-2. Sin IL-2, los linfocitos T no se multiplican ni atacan. Así se frena el rechazo de un trasplante o la inflamación autoinmune.","mp":["Se une a ciclofilina dentro del linfocito T.","Bloquea calcineurina → no se activa NFAT.","No se produce IL-2.","Linfocitos T no se activan → menos rechazo/inflamación."],"f":"Aprobada en 1983 (trasplante), Neoral en 1995 y Restasis en 2002.","e":[["Ensayo multicéntrico canadiense","Trasplante renal","Mejor supervivencia del injerto a un año que el régimen con azatioprina"]],"en":"Aprobada; ensayos clave de trasplante y estudios controlados en sus otros usos.","s":["Hipertensión","Aumento de creatinina","Temblor","Exceso de vello","Crecimiento de encías","Restasis: ardor ocular"],"sg":["Advertencia en recuadro: nefrotoxicidad.","Más riesgo de infecciones graves y cáncer (linfoma, piel).","Muchas interacciones (CYP3A4, P-gp, toronja); requiere niveles en sangre.","Sandimmune y Neoral NO son intercambiables."]}},{"id":31,"n":"Dalbavancin / Oritavancin / Telavancin","al":"","ar":"piel","ca":"fda","cl":"Lipoglycopeptide antibiotics","ev":"fda","u":"Antibióticos lipoglicopéptidos para determinadas infecciones bacterianas grampositivas; la indicación y precauciones difieren entre productos.","c":"Lipoglicopéptidos parientes de vancomicina.","m":"Dalvance, Orbactiv, Vibativ · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/dalbavancin-oritavancin-telavancin","ci":["https://doi.org/10.1056/NEJMoa1310480"],"x":{"r":"Dalbavancina, oritavancina y telavancina (Dalvance, Orbactiv, Vibativ) son lipoglicopéptidos, parientes semisintéticos de la vancomicina, contra infecciones gram-positivas incluido MRSA. Su ventaja es la dosificación: dalbavancina y oritavancina pueden tratar una infección de piel con una o dos dosis.","q":"Antibióticos IV de larga acción para infecciones de piel.","m":"Como la vancomicina, se pegan al extremo D-alanil-D-alanina de las piezas de la pared bacteriana e impiden que se entrelacen. Su cola lipídica los ancla a la membrana, lo que alarga su efecto. Oritavancina y telavancina además dañan la membrana, un segundo mecanismo bactericida.","mp":["Se unen a D-Ala-D-Ala → bloquean la pared celular.","Cola lipídica = efecto prolongado.","Oritavancina/telavancina: también rompen la membrana."],"f":"Telavancina (2009), dalbavancina (2014) y oritavancina (2014) aprobadas para infecciones bacterianas agudas de piel. Telavancina también para ciertas neumonías hospitalarias por S. aureus.","e":[["Programa pivotal de dalbavancina","Infecciones de piel","Dosis semanal no inferior a vancomicina → linezolid"]],"en":"Aprobados con ensayos aleatorizados de no inferioridad.","s":["Náusea, dolor de cabeza, diarrea","Enzimas hepáticas elevadas (dalbavancina)","Alteración del gusto y orina espumosa (telavancina)"],"sg":["Telavancina: advertencia de nefrotoxicidad y daño fetal.","Oritavancina interfiere con pruebas de coagulación; no usar heparina no fraccionada IV por varios días.","Reacciones a la infusión."]}},{"id":32,"n":"Daptomycin","al":"","ar":"piel","ca":"fda","cl":"Cyclic lipopeptide antibiotic","ev":"fda","u":"Antibiótico lipopeptídico para infecciones grampositivas seleccionadas, incluida bacteriemia por ciertos organismos; no se utiliza para neumonía.","c":"Lipopéptido que perfora la membrana bacteriana.","m":"Cubicin · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/daptomycin","ci":["https://doi.org/10.1056/NEJMoa053783","https://www.merck.com/product/usa/pi_circulars/c/cubicin/cubicin_pi.pdf"],"x":{"r":"La daptomicina (Cubicin) es un antibiótico lipopeptídico cíclico que mata bacterias gram-positivas, incluido MRSA, perforando su membrana. Se usa en infecciones graves de piel y bacteriemias por S. aureus. No sirve para neumonía porque el surfactante pulmonar la inactiva.","q":"Antibiótico IV de una vez al día para infecciones gram-positivas graves.","m":"Trabaja en la membrana de la bacteria, no en la pared. En presencia de calcio, su cola lipídica se inserta en la membrana y varias moléculas se agrupan para formar canales. Por esos canales se escapa el potasio, la membrana pierde su carga eléctrica y la bacteria deja de fabricar ADN, ARN y proteínas. Muere rápido y sin estallar.","mp":["Se une a la membrana con ayuda de calcio.","Forma canales → salida de potasio.","Colapsa el potencial de membrana.","Muerte bacteriana rápida, dependiente de concentración."],"f":"Aprobada en 2003 para infecciones complicadas de piel; después para bacteriemia por S. aureus y endocarditis derecha.","e":[["Ensayo pivotal de bacteriemia","S. aureus incl. endocarditis derecha","No inferior a la terapia estándar, con menos daño renal"]],"en":"Aprobada con ensayos aleatorizados de no inferioridad.","s":["Diarrea, dolor de cabeza, mareo","Erupción","Enzimas hepáticas y CPK elevadas","Infección urinaria","Hipotensión"],"sg":["Miopatía y, raramente, rabdomiólisis: medir CPK semanal y considerar pausar estatinas.","Neumonía eosinofílica.","Neuropatía periférica.","DRESS y otras alergias graves.","Nefritis intersticial."]}},{"id":33,"n":"Dasiglucagon","al":"","ar":"digestivo","ca":"fda","cl":"Glucagon analog","ev":"fda","u":"Análogo de glucagón utilizado para hipoglucemia grave; requiere un plan de rescate y seguimiento del episodio.","c":"Análogo estable de glucagón listo para inyectar.","m":"Zegalogue · autoinyector SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/dasiglucagon","ci":["https://doi.org/10.2337/dc20-2995","https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/214231s004lbl.pdf"],"x":{"r":"Dasiglucagon (Zegalogue) es un análogo de glucagón estable en solución, listo para inyectar en una emergencia de hipoglucemia severa. No hay que mezclar nada. Aprobado desde 2021; en 2026 la etiqueta pasó de límite por edad a límite por peso (≥20 kg).","q":"Glucagón de rescate en autoinyector o jeringa prellenada.","m":"Activa el receptor de glucagón en el hígado, que responde soltando glucosa almacenada (glucogenólisis) y fabricando glucosa nueva (gluconeogénesis). Sus cambios estructurales no alteran el efecto; lo hacen estable como líquido, lo que ahorra pasos valiosos en una emergencia.","mp":["Activa receptor de glucagón hepático.","Libera glucosa del glucógeno.","Estimula producción de glucosa nueva.","Glucosa se recupera en ~10 minutos."],"f":"Aprobado en 2021. Desde junio 2026: adultos y niños con diabetes que pesen al menos 20 kg.","e":[["Fase 3 en diabetes tipo 1","Adultos","Recuperación de glucosa en mediana de 10 min vs 40 min con placebo"],["Ensayo pediátrico","Niños","Respaldó su uso pediátrico"]],"en":"Aprobado con ensayos de fase 3.","s":["Náusea y vómito","Dolor de cabeza","Diarrea (adultos)","Dolor en sitio de inyección"],"sg":["Feocromocitoma: puede subir mucho la presión.","Insulinoma: hipoglucemia de rebote.","Alergias graves.","No funciona bien si no hay reservas de glucógeno (ayuno prolongado, alcohol)."]}},{"id":34,"n":"Davunetide","al":"","ar":"cerebro","ca":"ensayos","cl":"Neuroprotective peptide","ev":"baja","u":"Péptido neuroprotector experimental estudiado en enfermedades neurológicas; resultados preclínicos no han establecido eficacia clínica.","c":"Péptido neuroprotector derivado de una proteína cerebral.","m":"Intranasal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/davunetide","ci":["https://doi.org/10.2174/138161211795589373","https://doi.org/10.1016/S1474-4422(14)70088-2"],"x":{"r":"Davunetide es un péptido neuroprotector experimental derivado de una proteína cerebral (ADNP). Se estudió en spray nasal para parálisis supranuclear progresiva (PSP). Su ensayo grande fracasó sin diferencia frente a placebo.","q":"Péptido neuroprotector intranasal, en investigación.","m":"Se propuso que estabiliza los microtúbulos, el esqueleto interno de las neuronas, y reduce la fosforilación anormal de tau, la proteína que forma ovillos dañinos en varias enfermedades neurodegenerativas. Mostró protección en modelos de laboratorio, pero eso no se tradujo en beneficio clínico.","mp":["Estabiliza microtúbulos neuronales (laboratorio).","Reduce tau hiperfosforilada (laboratorio).","Sin beneficio clínico demostrado."],"f":"No aprobado.","e":[["Fase 2/3 en PSP","Más de 300 pacientes","Sin diferencia vs placebo en ninguno de los dos objetivos primarios"],["Deterioro cognitivo leve, esquizofrenia","Estudios exploratorios pequeños","Señales iniciales nunca confirmadas"]],"en":"Evidencia baja: el ensayo pivotal fue claramente negativo.","s":["Sin perfil relevante fuera de ensayos."],"sg":[]}},{"id":35,"n":"Degarelix","al":"","ar":"sexual","ca":"fda","cl":"GnRH antagonist","ev":"fda","u":"Antagonista de GnRH utilizado en cáncer de próstata avanzado; reduce la producción de testosterona.","c":"Antagonista GnRH: baja testosterona a nivel de castración rápido.","m":"Firmagon · SC mensual","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/degarelix","ci":["https://doi.org/10.1111/j.1464-410X.2008.08183.x","https://ferringusa.com/PI/Firmagon"],"x":{"r":"Degarelix (Firmagon) es un decapéptido que bloquea el receptor de GnRH y baja la testosterona a niveles de castración en pocos días, sin el pico inicial de los agonistas. Se usa en cáncer de próstata avanzado.","q":"Antagonista de GnRH para terapia de privación androgénica.","m":"Se une de forma reversible y competitiva al receptor de GnRH en la hipófisis y bloquea de inmediato la señal que libera LH y FSH. Sin LH, el testículo deja de fabricar testosterona, y las células del tumor que dependen de ella pierden su estímulo. Como es antagonista, no provoca el 'flare' de testosterona que causan leuprolide y similares.","mp":["Bloquea receptor de GnRH en la hipófisis.","LH y FSH caen en horas.","Testosterona a nivel de castración en ~3 días.","Sin 'flare' inicial."],"f":"Aprobado por la FDA en 2008 para cáncer de próstata avanzado.","e":[["CS21 (fase 3)","Cáncer de próstata, 12 meses vs leuprolide","No inferior para mantener castración; supresión de testosterona y PSA más rápida"]],"en":"Aprobado con ensayo de fase 3.","s":["Reacción en el sitio (dolor, enrojecimiento), sobre todo con la dosis de carga","Sofocos","Aumento de peso y fatiga","Enzimas hepáticas elevadas"],"sg":["Prolongación del QT: precaución con otros fármacos que alargan el QT.","Hipersensibilidad.","Pérdida ósea con privación androgénica prolongada."]}},{"id":36,"n":"Desirudin","al":"","ar":"corazon","ca":"fda","cl":"Direct thrombin inhibitor","ev":"fda","u":"Anticoagulante inhibidor directo de trombina utilizado para prevención de trombosis en contextos quirúrgicos seleccionados.","c":"Hirudina recombinante: inhibidor directo de trombina.","m":"Iprivask · SC (descontinuado)","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/desirudin","ci":["https://doi.org/10.2106/00004623-199703000-00002","https://www.drugs.com/mtm/iprivask.html"],"x":{"r":"Desirudin (antes Iprivask) es una hirudina recombinante, el anticoagulante natural de la sanguijuela. Se usó para prevenir trombosis venosa profunda tras reemplazo de cadera. Sigue aprobada, pero no hay producto a la venta en EE.UU.","q":"Inhibidor directo de trombina subcutáneo, descontinuado.","m":"Bloquea la trombina, la enzima final de la coagulación que forma fibrina y activa plaquetas. Se aferra a ella en dos sitios a la vez, su sitio activo y la zona con que agarra el fibrinógeno, y la deja sin función. No necesita antitrombina, a diferencia de la heparina, y también inhibe trombina dentro de coágulos.","mp":["Se une a trombina en dos sitios.","No depende de antitrombina.","Previene coágulos venosos después de cirugía."],"f":"Aprobada en 2003; Iprivask descontinuado, sin genérico.","e":[["Ensayo pivotal en reemplazo de cadera","Cirugía electiva","Menos TVP confirmada que heparina no fraccionada, sin más sangrado"]],"en":"Aprobada con ensayos aleatorizados.","s":["Sangrado","Reacción en sitio de inyección","Anemia y náusea"],"sg":["Hemorragia.","Riesgo de hematoma espinal con anestesia epidural/espinal.","Precaución renal; posibles anticuerpos contra hirudina."]}},{"id":37,"n":"Desmopressin","al":"","ar":"corazon","ca":"fda","cl":"Vasopressin V2 analog","ev":"fda","u":"Análogo de vasopresina con usos específicos en diabetes insípida y ciertas alteraciones hemorrágicas, según formulación; destaca el riesgo de hiponatremia.","c":"Análogo de vasopresina: concentra la orina (receptor V2).","m":"DDAVP, Nocdurna · oral, nasal, IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/desmopressin","ci":["https://drugs.com/cons/noctiva.html"],"x":{"r":"La desmopresina (DDAVP, Nocdurna) es una versión sintética de la hormona antidiurética vasopresina, diseñada para concentrar la orina sin subir la presión. Trata diabetes insípida central, enuresis, nocturia y algunos trastornos de sangrado.","q":"Análogo selectivo del receptor V2 de vasopresina.","m":"Activa el receptor V2 de los túbulos colectores del riñón, lo que aumenta los canales de agua (acuaporina-2) que devuelven agua al cuerpo. El resultado es menos orina y más concentrada. No activa el receptor V1 de los vasos, así que no causa vasoconstricción. Aparte, libera factor VIII y factor de von Willebrand de sus depósitos en los vasos.","mp":["Receptor V2 renal → más acuaporina-2.","Más reabsorción de agua → menos orina.","Liberación de factor VIII y von Willebrand.","Sin efecto vasoconstrictor (no activa V1)."],"f":"Aprobada desde 1978. Nocdurna (sublingual, 2018) tiene advertencia en recuadro por hiponatremia. Noctiva y Stimate fueron descontinuados.","e":[["Décadas de uso y ensayos de registro","Diabetes insípida, enuresis, nocturia, hemofilia A leve, von Willebrand tipo 1","Eficacia establecida en cada indicación"]],"en":"Aprobada y de uso establecido.","s":["Dolor de cabeza","Náusea","Molestia nasal (spray)","Rubor"],"sg":["Hiponatremia: puede causar convulsiones. Limitar líquidos desde 1 hora antes hasta 8 horas después.","Mayor riesgo en ancianos, insuficiencia cardíaca o renal."]}},{"id":38,"n":"Difelikefalin","al":"","ar":"piel","ca":"fda","cl":"Kappa-opioid agonist peptide","ev":"fda","u":"Agonista opioide kappa periférico utilizado para prurito moderado a intenso asociado a enfermedad renal crónica en adultos en hemodiálisis.","c":"Agonista kappa-opioide periférico.","m":"Korsuva · IV en diálisis","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/difelikefalin","ci":["https://doi.org/10.1056/NEJMoa1912770","https://www.drugs.com/pro/korsuva.html"],"x":{"r":"Difelikefalin (Korsuva) es un péptido que activa receptores kappa-opioides periféricos para aliviar el picor intenso de pacientes en hemodiálisis. Casi no entra al cerebro, por lo que no causa euforia ni depresión respiratoria.","q":"Agonista kappa-opioide de acción periférica, IV en diálisis.","m":"Los receptores kappa están en los nervios sensoriales periféricos que transmiten el picor y en células inmunes. Al activarlos se apaga la señal de picor y posiblemente baja la liberación de mediadores inflamatorios. Como su estructura casi no cruza al cerebro, evita los efectos de los opioides clásicos, que actúan en receptores mu.","mp":["Activa receptores kappa en nervios periféricos → menos señal de picor.","Actúa en células inmunes → menos mediadores pruriginosos.","Mínima entrada al cerebro."],"f":"Aprobado en 2021 para prurito moderado a severo por enfermedad renal crónica en adultos en hemodiálisis.","e":[["KALM-1","Pacientes en hemodiálisis, 12 semanas","Más pacientes con mejoría significativa del picor y mejor calidad de vida vs placebo"],["KALM-2","Población similar","Resultados consistentes"]],"en":"Aprobado con ensayos aleatorizados.","s":["Diarrea","Mareo y náusea","Potasio alto","Dolor de cabeza"],"sg":["Mareo, somnolencia y alteraciones de la marcha: riesgo de caídas.","Precaución con otros depresores del sistema nervioso."]}},{"id":39,"n":"Dihexa","al":"","ar":"cerebro","ca":"wellness","cl":"Angiotensin IV-derived peptide","ev":"baja","u":"Compuesto experimental estudiado en vías de señalización neuronal; no hay beneficio ni seguridad clínica establecidos para mejorar memoria.","c":"Derivado de angiotensina IV; activa vía HGF/c-Met.","m":"Oral / inyectable (químico de investigación)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/dihexa","ci":["https://doi.org/10.1124/jpet.112.199497","https://doi.org/10.1124/jpet.114.218735","https://doi.org/10.5435/JAAOSGlobal-D-25-00236","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://pmc.ncbi.nlm.nih.gov/articles/PMC3533412/","https://pubmed.ncbi.nlm.nih.gov/40312092/","https://pubmed.ncbi.nlm.nih.gov/40312093/","https://pubmed.ncbi.nlm.nih.gov/23055539/"],"x":{"r":"Dihexa es un péptido experimental derivado de la angiotensina IV que se vende como 'research peptide' para la cognición. No hay ningún estudio en humanos y el artículo clave sobre su mecanismo fue retractado.","q":"Péptido derivado de angiotensina IV, solo estudiado en animales.","m":"Se propuso que favorece nuevas conexiones entre neuronas (sinaptogénesis) potenciando la vía del factor de crecimiento de hepatocitos (HGF) y su receptor c-Met. El artículo principal que describía este mecanismo fue retractado, lo que debilita incluso la base de laboratorio. Lo que queda son experimentos en células y roedores.","mp":["Potenciaría la vía HGF/c-Met (propuesto).","Nuevas sinapsis en roedores (reportado).","Base científica debilitada por retractación."],"f":"No aprobado por la FDA ni en ningún país.","e":[["Pruebas de laberinto","Roedores","Mejoras de memoria reportadas"],["Artículo de mecanismo","—","Retractado"]],"en":"Evidencia baja: solo preclínica y parcialmente comprometida.","s":["No existen datos de seguridad en humanos."],"sg":["La vía c-Met está ligada a crecimiento, invasión y metástasis de tumores: preocupación oncológica teórica importante.","Sin estudios de farmacocinética ni de dosis en humanos."]}},{"id":40,"n":"Dipeptide diaminobutyroyl benzylamide diacetate","al":"","ar":"piel","ca":"cosmetico","cl":"Neuromuscular-relaxing peptide","ev":"baja","u":"Ingrediente cosmético tópico investigado para líneas de expresión; no equivale a toxina botulínica ni demuestra utilidad inyectable.","c":"Imita un componente del veneno y relaja músculos de expresión.","m":"SYN-AKE · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/dipeptide-diaminobutyroyl-benzylamide-diacetate","ci":["https://www.happi.com/contents/view_suppliers-corner/2005-12-09/pentapharm-introduces-anti-wrinkle-active/","https://cosmeticsdesign-europe.com/Article/2007/12/14/snake-venom-based-anti-ageing-cream-launched-in-uk","https://doi.org/10.1111/ics.70087"],"x":{"r":"El diacetato de dipéptido diaminobutiroil bencilamida, vendido como SYN-AKE, imita un componente del veneno de la víbora del templo. Se mercadea como alternativa 'sin agujas' para líneas de expresión. Su evidencia humana viene de fórmulas con varios ingredientes, no del péptido solo.","q":"Péptido cosmético inspirado en veneno de serpiente.","m":"Para contraerse, el músculo recibe acetilcolina en sus receptores nicotínicos. El péptido del veneno bloquea ese receptor de forma reversible, y la versión sintética haría lo mismo, de modo que los músculos pequeños de la expresión se contraen menos. En crema no llega al músculo como una inyección; el efecto que se describe es solo de apariencia.","mp":["Bloquearía el receptor nicotínico de acetilcolina (laboratorio).","Menor contracción de músculos de expresión.","Efecto tópico superficial, sin parálisis."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Estudio ex vivo y clínico 2026","Suero con SYN-AKE + Argireline + niacinamida y otros","Mejor apariencia de arrugas, pero no atribuible solo a SYN-AKE"]],"en":"Evidencia baja: sin ensayo del péptido aislado.","s":["Bien tolerado; baja irritación"],"sg":[]}},{"id":41,"n":"DSIP","al":"","ar":"cerebro","ca":"wellness","cl":"Neuromodulatory nonapeptide","ev":"baja","u":"Péptido asociado a investigación del sueño. La evidencia disponible no establece un tratamiento eficaz y seguro para insomnio.","c":"Neuropéptido natural relacionado con sueño profundo.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/dsip","ci":["https://pubmed.ncbi.nlm.nih.gov/862769/","https://doi.org/10.1007/BF01971753","https://doi.org/10.1159/000115716","https://doi.org/10.1159/000115715","https://doi.org/10.5435/JAAOSGlobal-D-25-00236"],"x":{"r":"DSIP (péptido inductor del sueño delta) es un nonapéptido natural que se vende en el mercado de 'research peptides' para sueño y estrés. La evidencia humana son unos pocos estudios pequeños y viejos con resultados inconsistentes.","q":"Neuropéptido de nueve aminoácidos.","m":"Se le han atribuido funciones en la regulación del sueño, en la respuesta al estrés (eje hipotálamo-hipófisis-suprarrenal) y como antioxidante. No se le conoce un receptor validado ni un mecanismo definido. Su nombre viene de trabajos tempranos en animales que nunca se aclararon.","mp":["Sin receptor conocido.","Asociación con sueño solo en animales.","Posible modulación del estrés (no confirmada)."],"f":"No aprobado por la FDA ni como medicamento en ningún país.","e":[["Estudios de los años 80 y 90","Insomnio, dolor crónico, abstinencia; pequeños y sin control","Resultados inconsistentes"]],"en":"Evidencia baja: no hay ensayos modernos.","s":["Sin datos de seguridad modernos."],"sg":["Producto del mercado gris."]}},{"id":42,"n":"Dulaglutide","al":"","ar":"hormonas","ca":"fda","cl":"GLP-1 receptor agonist","ev":"fda","u":"Agonista GLP-1 utilizado en diabetes tipo 2, con beneficios cardiovasculares en poblaciones definidas según etiqueta.","c":"Agonista GLP-1 semanal unido a fragmento de anticuerpo.","m":"Trulicity · pluma SC semanal","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/dulaglutide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/125469s065lbl.pdf","https://diabetesjournals.org/care/article/37/8/2159/29765/Efficacy-and-Safety-of-Dulaglutide-Added-Onto","https://doi.org/10.1016/S0140-6736(19)31149-3"],"x":{"r":"Dulaglutide (Trulicity) es un GLP-1 semanal formado por dos cadenas de GLP-1 unidas a un fragmento de anticuerpo, lo que extiende su acción a unos cinco días. Está aprobado para diabetes tipo 2 desde 2014 y para reducir riesgo cardiovascular desde 2020 (ensayo REWIND, −12% eventos).","q":"Agonista del receptor GLP-1 en pluma semanal.","m":"Imita la hormona GLP-1 que el intestino libera al comer. Hace que el páncreas libere insulina solo cuando la glucosa está alta (por eso solo tiene poco riesgo de hipoglucemia), baja el glucagón, retrasa el vaciado gástrico y reduce el apetito. El fragmento de anticuerpo lo mantiene en sangre unos cinco días.","mp":["Insulina dependiente de glucosa.","Menos glucagón.","Vaciado gástrico más lento.","Menos apetito.","Vida media ~5 días → dosis semanal."],"f":"Aprobado para diabetes tipo 2 (2014) y para reducción de riesgo cardiovascular (2020).","e":[["Programa AWARD","Diabetes tipo 2","A1c −1.5% aprox."],["REWIND","Diabetes tipo 2 con o sin enfermedad CV","≈ −12% eventos cardiovasculares mayores"]],"en":"Aprobado con programas de ensayos grandes.","s":["Náusea","Diarrea","Vómito","Dolor abdominal","Menos apetito","Fatiga"],"sg":["Advertencia de tumores tiroideos de células C; contraindicado con historial de carcinoma medular o MEN2.","Pancreatitis.","Vesícula y cálculos.","Daño renal por deshidratación.","Hipoglucemia con insulina o sulfonilureas.","Empeoramiento de retinopatía diabética.","Riesgo de aspiración en anestesia."]}},{"id":43,"n":"Ecallantide","al":"","ar":"piel","ca":"fda","cl":"Plasma kallikrein inhibitor","ev":"fda","u":"Inhibidor de calicreína utilizado en ataques agudos de angioedema hereditario; puede producir anafilaxia.","c":"Bloquea la calicreína plasmática y la bradicinina.","m":"Kalbitor · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/ecallantide","ci":["https://doi.org/10.1056/NEJMoa0905079","https://www.drugs.com/pro/kalbitor.html"],"x":{"r":"Ecallantide (Kalbitor) es una proteína que bloquea la calicreína plasmática y se usa para ataques agudos de angioedema hereditario (AEH). Tiene advertencia en recuadro por anafilaxia y lo debe administrar un profesional.","q":"Inhibidor de calicreína plasmática (proteína recombinante tipo Kunitz).","m":"La calicreína corta una proteína llamada cininógeno y libera bradicinina, el mediador que hace que los vasos goteen y los tejidos se hinchen en el AEH. Ecallantide bloquea la calicreína antes de ese paso, así que se forma menos bradicinina. Es diferente a icatibant, que bloquea el receptor de bradicinina.","mp":["Bloquea la calicreína plasmática.","Menos liberación de bradicinina.","Menos fuga vascular → menos hinchazón."],"f":"Aprobado en 2009 (≥16 años); desde 2014 para ≥12 años.","e":[["EDEMA3","Ataques agudos de AEH","Mejores puntajes de síntomas y resultados vs placebo"]],"en":"Aprobado con ensayos aleatorizados.","s":["Dolor de cabeza","Náusea y diarrea","Fiebre","Reacción en sitio de inyección","Nasofaringitis"],"sg":["Advertencia en recuadro de anafilaxia: solo en un lugar preparado para tratarla.","Las reacciones alérgicas pueden confundirse con un ataque de AEH."]}},{"id":44,"n":"Echinocandins","al":"","ar":"corazon","ca":"fda","cl":"Lipopeptide antifungals","ev":"fda","u":"Familia de antifúngicos que inhibe la síntesis de pared de hongos; se utiliza para infecciones invasivas seleccionadas.","c":"Lipopéptidos que dañan la pared celular del hongo.","m":"Cancidas, Mycamine, Eraxis, Rezzayo · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/echinocandins","ci":["https://doi.org/10.1056/NEJMoa021585","https://doi.org/10.1056/NEJMoa066906"],"x":{"r":"Las equinocandinas (caspofungina, micafungina, anidulafungina y rezafungina) son antifúngicos lipopeptídicos que atacan la pared del hongo, una estructura que las células humanas no tienen. Son opción preferida para infecciones invasivas por Candida y suelen tolerarse bien.","q":"Antifúngicos IV de amplio uso hospitalario.","m":"Bloquean la enzima 1,3-β-D-glucano sintasa, que fabrica el polímero que da firmeza a la pared del hongo. Sin él, la pared se debilita y la célula revienta por su propia presión. Matan a la mayoría de Candida y frenan a Aspergillus. Como las células humanas no tienen pared ni esa enzima, causan poca toxicidad directa.","mp":["Bloquean 1,3-β-D-glucano sintasa.","Pared fúngica débil → ruptura.","Fungicidas contra Candida; fungistáticas contra Aspergillus."],"f":"Caspofungina (2001), micafungina (2005), anidulafungina (2006), rezafungina (2023, semanal).","e":[["Ensayo pivotal de caspofungina","Candidiasis invasiva vs anfotericina B","Igual de eficaz con menos efectos adversos"],["Ensayo de anidulafungina","Vs fluconazol","Superior en el objetivo primario"]],"en":"Aprobadas con ensayos aleatorizados.","s":["Fiebre","Reacciones a la infusión (rubor, picor)","Náusea y dolor de cabeza","Potasio bajo y enzimas hepáticas altas"],"sg":["Disfunción hepática (rara).","Alergias graves raras.","Caspofungina: ajustar en daño hepático; interacciones con ciclosporina, rifampicina."]}},{"id":45,"n":"Efpeglenatide","al":"","ar":"hormonas","ca":"ensayos","cl":"Long-acting GLP-1 agonist","ev":"alta","u":"Agonista GLP-1 estudiado en diabetes tipo 2 y resultados cardiovasculares; revisar el estado regulatorio y disponibilidad por jurisdicción.","c":"Agonista GLP-1 de larga acción.","m":"SC semanal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/efpeglenatide","ci":["https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1056/NEJMoa2108269","https://doi.org/10.1161/CIRCULATIONAHA.121.057934"],"x":{"r":"Efpeglenatide es un GLP-1 de acción prolongada desarrollado originalmente por Hanmi. En el ensayo de fase 3 AMPLITUDE-O redujo eventos cardiovasculares mayores en diabetes tipo 2, pero no ha llegado a aprobarse en los mercados principales.","q":"Agonista GLP-1 semanal, en investigación.","m":"Activa el receptor GLP-1 igual que semaglutide o dulaglutide: aumenta la insulina dependiente de glucosa, baja el glucagón, retrasa el vaciado gástrico y reduce el apetito.","mp":["Insulina dependiente de glucosa.","Menos glucagón.","Vaciado gástrico más lento.","Menos apetito."],"f":"No aprobado por la FDA ni la EMA.","e":[["AMPLITUDE-O (fase 3)","Más de 4,000 adultos con diabetes tipo 2 y enfermedad CV o renal","Menos eventos CV mayores (HR 0.73) y menos eventos renales"],["Análisis preespecificado","Mismo ensayo","Beneficio igual con o sin inhibidor SGLT2"]],"en":"Evidencia alta en ensayos, aunque sin aprobación comercial.","s":["Efectos GI típicos de GLP-1"],"sg":["Advertencias de clase GLP-1."]}},{"id":46,"n":"Elamipretide","al":"","ar":"hormonas","ca":"fda","cl":"Mitochondria-targeting tetrapeptide","ev":"fda","u":"Péptido dirigido a mitocondrias con aprobación acelerada para mejorar fuerza muscular en pacientes seleccionados con síndrome de Barth; otros usos siguen en investigación.","c":"Se une a cardiolipina y mejora la función de la mitocondria.","m":"Forzinity · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/elamipretide","ci":["https://doi.org/10.1016/j.gim.2024.101138","https://www.drugs.com/pro/forzinity.html","https://doi.org/10.1186/s13023-025-03693-5"],"x":{"r":"Elamipretide (Forzinity) es un tetrapéptido que se dirige a la mitocondria y se une a la cardiolipina. Recibió aprobación acelerada en 2025 para síndrome de Barth, el primer tratamiento para esa enfermedad genética rara. La aprobación se basa en una medida sustituta de fuerza muscular y requiere un ensayo confirmatorio.","q":"Péptido mitocondrial aprobado (aceleradamente) para un solo uso.","m":"La cardiolipina es una molécula de la membrana interna de la mitocondria que mantiene sus pliegues (crestas), donde se fabrica la energía. Elamipretide se une a ella y estabiliza esa estructura para que la cadena respiratoria produzca ATP de forma más eficiente y con menos radicales libres. En el síndrome de Barth, mutaciones del gen TAFAZZIN dañan la cardiolipina.","mp":["Se une a cardiolipina en la membrana mitocondrial interna.","Estabiliza las crestas mitocondriales.","Mejor producción de ATP; menos radicales libres."],"f":"Aprobación acelerada el 19 de septiembre de 2025 para síndrome de Barth (≥30 kg). Otros usos siguen en investigación.","e":[["Ensayo aleatorizado en Barth","Pacientes con síndrome de Barth","No cumplió sus objetivos primarios"],["Datos abiertos de extensión","Pequeño grupo","Mejoría de fuerza muscular (base de la aprobación)"]],"en":"Aprobado, pero con evidencia limitada y confirmación pendiente.","s":["Reacciones en el sitio de inyección: enrojecimiento, dolor, endurecimiento, picor, moretones, ronchas"],"sg":["Alergias graves.","Contiene alcohol bencílico: no aprobado en recién nacidos."]}},{"id":47,"n":"Enfuvirtide","al":"","ar":"inmune","ca":"fda","cl":"HIV fusion inhibitor peptide","ev":"fda","u":"Inhibidor de fusión del VIH utilizado como parte de tratamientos antirretrovirales seleccionados; no se usa como monoterapia.","c":"Inhibidor de fusión: evita que el virus entre a la célula CD4.","m":"Fuzeon · SC 2 veces/día","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/enfuvirtide","ci":["https://doi.org/10.1056/NEJMoa035026","https://gene.com/media/statements/ps_081924"],"x":{"r":"Enfuvirtide (Fuzeon) es un péptido de 36 aminoácidos que impide que el VIH entre a las células CD4. Fue el primer inhibidor de fusión y se usó en pacientes con virus resistente a otros antirretrovirales. Fuzeon se descontinuó en EE.UU. en febrero de 2025.","q":"Inhibidor de fusión del VIH-1, inyectable dos veces al día.","m":"Para entrar a la célula, la proteína gp41 del virus tiene que doblarse sobre sí misma en forma de horquilla y acercar las dos membranas. Enfuvirtide imita un segmento de gp41 y se pega justo donde la proteína necesita agarrarse, impidiendo ese doblez. Como actúa fuera de la célula, sirve contra virus resistentes a los antirretrovirales que actúan adentro.","mp":["Se une a gp41 del virus.","Impide el doblez en horquilla.","Bloquea la fusión de membranas → el virus no entra."],"f":"Aprobado en 2003; descontinuado en EE.UU. el 28 de febrero de 2025.","e":[["TORO 1 y 2","Pacientes con VIH multitratado","Mayor reducción de carga viral que el régimen de fondo solo"]],"en":"Aprobado con ensayos aleatorizados.","s":["Reacciones en sitio de inyección en casi todos los pacientes (dolor, nódulos, quistes)","Diarrea y náusea","Fatiga"],"sg":["Más neumonía bacteriana.","Hipersensibilidad que puede repetirse al reiniciar."]}},{"id":48,"n":"Enlicitide","al":"","ar":"digestivo","ca":"fda","cl":"Oral macrocyclic PCSK9 inhibitor peptide","ev":"fda","u":"Inhibidor oral de PCSK9 para reducir colesterol LDL; se distingue de las terapias inyectables que actúan sobre la misma diana.","c":"Inhibidor oral de PCSK9 (péptido macrocíclico).","m":"Tableta diaria","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/enlicitide","ci":["https://doi.org/10.1056/NEJMoa2511002","https://www.merck.com/product/usa/pi_circulars/l/lipfendra/lipfendra_pi.pdf","https://www.merck.com/news/mercks-lipfendra-enlicitide-is-the-first-and-only-once-daily-oral-pcsk9-inhibitor-approved-by-the-u-s-fda-to-reduce-ldl-c-in-adults-with-hypercholesterolemia/","https://doi.org/10.1016/j.jacc.2026.03.036"],"x":{"r":"Enlicitide (Lipfendra) es el primer inhibidor de PCSK9 en tableta, desarrollado por Merck para bajar el colesterol LDL. En fase 3 bajó el LDL cerca de 60%, igual que los anticuerpos inyectables de su clase. La FDA lo aprobó en 2026.","q":"Péptido macrocíclico oral que bloquea PCSK9.","m":"El hígado retira el LDL de la sangre con unos receptores en su superficie. PCSK9 es una proteína que marca esos receptores para que se destruyan. Enlicitide atrapa a PCSK9 y no la deja unirse al receptor, así que los receptores se reciclan y vuelven a la superficie. Con más receptores, el hígado saca más LDL de la sangre. Lo novedoso es lograrlo con un péptido que resiste la digestión.","mp":["Se une a PCSK9 circulante.","PCSK9 ya no destruye receptores de LDL.","Más receptores en la superficie del hígado.","LDL en sangre baja ~60%."],"f":"Aprobado por la FDA en 2026 como Lipfendra.","e":[["CORALreef Lipids (fase 3)","Adultos con LDL elevado","LDL ≈ −60%; efectos adversos similares a placebo"],["Ensayo en hipercolesterolemia familiar heterocigota","Adultos con HeFH","Reducción robusta de LDL"]],"en":"Aprobado con varios ensayos de fase 3 grandes.","s":["Mareo (9% vs 4% placebo en HeFH)","Diarrea (7% vs 2%)"],"sg":["Suspender al confirmar embarazo, salvo que el beneficio supere el riesgo."]}},{"id":49,"n":"Epitalon","al":"","ar":"cerebro","ca":"wellness","cl":"Pineal tetrapeptide (Ala-Glu-Asp-Gly)","ev":"baja","u":"Péptido experimental promovido para longevidad y sueño. No hay demostración clínica sólida de que prolongue la vida humana.","c":"Tetrapéptido sintético basado en extracto de glándula pineal.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/epitalon","ci":["https://pubmed.ncbi.nlm.nih.gov/12374906/","https://doi.org/10.1023/a:1025493705728","https://doi.org/10.1023/a:1021104819170","https://www.ajmc.com/view/fda-panel-backs-6-peptides-for-compounding","https://pubmed.ncbi.nlm.nih.gov/40908429/","https://www.fda.gov/media/193345/download","https://pubmed.ncbi.nlm.nih.gov/14523363/","https://www.deadiversion.usdoj.gov/schedules/orangebook/c_cs_alpha.pdf"],"x":{"r":"Epitalon es un tetrapéptido sintético (Ala-Glu-Asp-Gly) basado en un extracto de la glándula pineal, vendido para antienvejecimiento y sueño. Toda su evidencia humana viene de un solo grupo ruso, con estudios viejos y sin replicar. En 2026 un comité asesor de la FDA votó a favor, de forma no vinculante, de permitir su compounding.","q":"Péptido pineal mercadeado para longevidad.","m":"Se le atribuyen tres efectos: restaurar el ritmo de melatonina, actuar como antioxidante y modificar la expresión de genes, incluida la activación de la telomerasa, una enzima ligada al envejecimiento celular. Todo esto viene de cultivos celulares y animales.","mp":["Ritmo de melatonina (propuesto).","Antioxidante (laboratorio).","Activaría telomerasa (laboratorio)."],"f":"No aprobado por la FDA. Comité asesor 2026: voto favorable no vinculante para compounding; verificar decisión final de la FDA.","e":[["Estudios observacionales rusos","Personas mayores; pequeños y sin cegamiento","Cambios en ritmo de melatonina y condiciones de la edad"],["Estudios de telomerasa","Células y animales","Activación de telomerasa"]],"en":"Evidencia baja: fuente única, antigua y sin replicación independiente.","s":["No hay estudios clínicos de seguridad en humanos."],"sg":["Activar la telomerasa podría tener implicaciones en proliferación celular y cáncer; no estudiado."]}},{"id":50,"n":"Eptifibatide","al":"","ar":"corazon","ca":"fda","cl":"GPIIb/IIIa inhibitor","ev":"fda","u":"Antiagregante plaquetario inhibidor de GP IIb/IIIa utilizado en contextos coronarios seleccionados; el sangrado es un riesgo central.","c":"Bloquea GPIIb/IIIa: evita la agregación de plaquetas.","m":"Integrilin · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/eptifibatide","ci":["https://pubmed.ncbi.nlm.nih.gov/2033037/","https://doi.org/10.1056/NEJM199808133390704","https://www.merck.com/product/usa/pi_circulars/i/integrilin/integrilin_pi.pdf"],"x":{"r":"Eptifibatide (Integrilin) es un heptapéptido cíclico inspirado en el veneno de la serpiente de cascabel. Bloquea el paso final de la agregación de plaquetas para evitar coágulos durante un infarto o la colocación de un stent.","q":"Antiplaquetario IV (inhibidor de GPIIb/IIIa).","m":"Cuando las plaquetas se activan, su receptor GPIIb/IIIa se une al fibrinógeno y las amarra entre sí. Eptifibatide ocupa ese receptor y, aunque las plaquetas estén activadas, no pueden unirse. Es potente pero reversible: el efecto desaparece poco después de detener la infusión. Se elimina por el riñón.","mp":["Bloquea receptor GPIIb/IIIa.","El fibrinógeno no puede unir plaquetas.","Efecto reversible al parar la infusión."],"f":"Aprobado en 1998 para síndrome coronario agudo y angioplastia.","e":[["PURSUIT","Síndrome coronario agudo","Menos muerte o infarto a 30 días, con más sangrado"]],"en":"Aprobado con ensayos aleatorizados grandes.","s":["Sangrado, sobre todo en el sitio de acceso vascular","Hipotensión"],"sg":["Hemorragia mayor.","Trombocitopenia.","Contraindicado en sangrado activo, hipertensión severa no controlada o diálisis."]}},{"id":51,"n":"Etelcalcetide","al":"","ar":"huesos","ca":"fda","cl":"Calcimimetic peptide","ev":"fda","u":"Calcimimético utilizado en hiperparatiroidismo secundario en adultos con enfermedad renal crónica en hemodiálisis.","c":"Calcimimético: activa el receptor de calcio y baja PTH.","m":"Parsabiv · IV en diálisis","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/etelcalcetide","ci":["https://doi.org/10.1001/jama.2016.19468","https://www.pi.amgen.com/united_states/parsabiv/parsabiv_pi.pdf"],"x":{"r":"Etelcalcetide (Parsabiv) es un péptido calcimimético que activa el receptor sensor de calcio para bajar la hormona paratiroidea (PTH). Se usa en hiperparatiroidismo secundario en pacientes en diálisis y se administra IV al final de cada sesión.","q":"Calcimimético IV para pacientes en hemodiálisis.","m":"Se une al receptor sensor de calcio de las glándulas paratiroides y lo vuelve más sensible. La glándula interpreta que hay suficiente calcio y produce menos PTH. Eso reduce el recambio alto de calcio y fósforo que daña huesos y vasos en diálisis. Es lo opuesto a dar PTH: aquí se baja la hormona.","mp":["Activa el receptor sensor de calcio.","Paratiroides 'cree' que hay calcio suficiente.","Menos secreción de PTH."],"f":"Aprobado en 2017 para hiperparatiroidismo secundario en adultos en hemodiálisis.","e":[["Comparación cara a cara","Vs cinacalcet oral","Bajó PTH al menos igual; más pacientes con reducciones grandes"]],"en":"Aprobado con ensayos aleatorizados.","s":["Calcio bajo","Espasmos musculares","Náusea, vómito, diarrea","Dolor de cabeza"],"sg":["Hipocalcemia grave: convulsiones o arritmias; vigilar calcio.","Empeoramiento de insuficiencia cardíaca.","Sangrado gastrointestinal alto."]}},{"id":52,"n":"Exenatide","al":"","ar":"hormonas","ca":"fda","cl":"GLP-1 receptor agonist","ev":"fda","u":"Agonista GLP-1 utilizado en diabetes tipo 2; la pauta y precauciones dependen de la formulación.","c":"Primer agonista GLP-1 (de veneno del monstruo de Gila).","m":"Byetta (2/día), Bydureon (semanal) · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/exenatide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/209210s024lbl.pdf","https://pubmed.ncbi.nlm.nih.gov/21194543/","https://www.uhcprovider.com/en/resource-library/news/2024/discontinuation-bydureon-bcise-byetta.html","https://doi.org/10.1056/NEJMoa1411892","https://doi.org/10.1056/NEJMoa2032183","https://doi.org/10.1056/NEJMoa2206038","https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/215866s031lbl.pdf"],"x":{"r":"Exenatide fue el primer agonista GLP-1 aprobado (2005). Es una copia sintética de la exendina-4 del monstruo de Gila. Se usaba dos veces al día (Byetta) o semanal (Bydureon). AstraZeneca descontinuó ambas marcas en 2024; desde 2025 hay genérico de la forma de dos veces al día.","q":"El GLP-1 original, hoy superado por los más nuevos.","m":"Activa el receptor GLP-1: libera insulina dependiente de glucosa, baja el glucagón, retrasa el vaciado del estómago y reduce el apetito. Como viene del péptido de lagarto y no del GLP-1 humano, resiste la enzima DPP-4 que destruye el GLP-1 natural en minutos. Bydureon encerraba el péptido en microesferas de liberación lenta.","mp":["Insulina dependiente de glucosa.","Menos glucagón.","Vaciado gástrico más lento.","Resiste DPP-4 por su origen en exendina-4."],"f":"Aprobado; marcas descontinuadas en 2024; genérico de liberación inmediata desde 2025.","e":[["Programa de ensayos","Diabetes tipo 2","Reducción moderada de A1c y algo de pérdida de peso"]],"en":"Aprobado; menos potente que semaglutide o tirzepatide.","s":["Náusea (muy común)","Vómito","Diarrea","Nerviosismo","Mareo","Dolor de cabeza"],"sg":["Pancreatitis.","Hipoglucemia con sulfonilureas.","Daño renal; evitar si CrCl <30.","Vesícula.","Bydureon: nódulos en el sitio y advertencia tiroidea (Byetta no la tiene)."]}},{"id":53,"n":"Follistatin-344","al":"","ar":"huesos","ca":"wellness","cl":"Myostatin-inhibiting peptide","ev":"baja","u":"Proteína que interviene en señalización de activina y miostatina, investigada en crecimiento muscular; no tiene beneficio clínico establecido como producto de rendimiento.","c":"Bloquea miostatina, el 'freno' del crecimiento muscular.","m":"Inyectable (químico de investigación)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/follistatin-344","ci":["https://doi.org/10.1038/387083a0","https://doi.org/10.1038/mt.2014.200","https://doi.org/10.3233/jnd-150083","https://pubmed.ncbi.nlm.nih.gov/25322757/","https://pubmed.ncbi.nlm.nih.gov/28279643/"],"x":{"r":"Follistatin-344 es una forma de la proteína follistatina que bloquea la miostatina, el 'freno' natural del crecimiento muscular. Se vende como químico de investigación para ganar músculo. La única evidencia humana viene de terapia génica en enfermedades musculares, no del péptido inyectable.","q":"Proteína que neutraliza la miostatina, mercadeada para rendimiento.","m":"La miostatina limita cuánto músculo construye el cuerpo. La follistatina se une a ella y la neutraliza, liberando ese freno. En animales, bloquear la miostatina produce un crecimiento muscular marcado.","mp":["Se une a la miostatina y la neutraliza.","Se quita el freno al crecimiento muscular (animales)."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Fase 1/2a de terapia génica","6 pacientes con distrofia de Becker, sin placebo","4 de 6 caminaron 29–125 m más en 6 minutos; menos fibrosis"],["Terapia génica 2017","6 pacientes con miositis por cuerpos de inclusión vs 8 controles no aleatorizados","+56 m/año vs −25.8 m en controles (p=0.01)"]],"en":"Evidencia baja: no hay ensayos del péptido inyectable; los datos humanos son de terapia génica en enfermos.","s":["Sin datos de seguridad del péptido inyectable."],"sg":["Producto del mercado gris de pureza y actividad desconocidas."]}},{"id":54,"n":"Fragment 176-191","al":"","ar":"digestivo","ca":"wellness","cl":"GH C-terminal fragment","ev":"baja","u":"Fragmento de hormona de crecimiento promovido para pérdida de grasa; no debe equipararse a una terapia eficaz y validada para obesidad.","c":"Fragmento del extremo de la hormona de crecimiento.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/fragment-176-191","ci":["https://pubmed.ncbi.nlm.nih.gov/8358331/","https://pubmed.ncbi.nlm.nih.gov/11146367/","https://pubmed.ncbi.nlm.nih.gov/11673763/","https://pubmed.ncbi.nlm.nih.gov/23092275/","https://doi.org/10.1159/000053183"],"x":{"r":"El Fragmento 176-191 es la cola sin modificar de la hormona de crecimiento, vendida como péptido quemagrasa. Toda su evidencia es animal y de laboratorio. Su primo optimizado, AOD-9604, fracasó en ensayos de obesidad en humanos.","q":"Fragmento C-terminal de la hormona de crecimiento.","m":"La teoría es que el efecto de la hormona de crecimiento sobre la grasa se concentra en esa cola, así que el fragmento solo podría reducir el almacenamiento de grasa sin los efectos de crecimiento o glucosa. En ratas, un fragmento cercano (177-191) igualó el efecto antilipogénico de la hormona completa, pero no aumentó la degradación de grasa.","mp":["Reduciría la formación de grasa nueva (ratas).","Sin efecto lipolítico claro.","Sin datos humanos del fragmento."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Wu y Ng 1993","Tejido graso de rata","hGH 177-191 igualó el efecto antilipogénico, sin lipólisis"],["AOD-9604 (12 semanas)","Humanos","−2.6 kg vs −0.8 kg placebo"],["AOD-9604 (24 semanas, 536 personas)","Humanos","Sin pérdida significativa; programa cancelado"]],"en":"Evidencia baja: el pariente más estudiado falló en humanos.","s":["Sin datos humanos."],"sg":["Producto del mercado gris."]}},{"id":55,"n":"Ga-68 dotatate","al":"","ar":"digestivo","ca":"fda","cl":"SSTR imaging radiopeptide","ev":"fda","u":"Radiofármaco diagnóstico utilizado en PET para localizar tumores con receptores de somatostatina; no es un tratamiento de bienestar.","c":"Análogo de somatostatina con galio-68 radioactivo.","m":"NETSPOT · IV diagnóstico","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/ga-68-dotatate","ci":["https://doi.org/10.2967/jnumed.115.163865","https://www.novartis.com/us-en/sites/novartis_us/files/netspot.pdf"],"x":{"r":"Galio Ga-68 dotatate (NETSPOT) es un agente de imagen radioactivo. Une un trazador a un análogo de somatostatina para iluminar en PET los tumores neuroendocrinos que tienen receptores de somatostatina.","q":"Radiofármaco diagnóstico para PET/CT.","m":"La parte 'dotatate' se une con gran afinidad al receptor de somatostatina tipo 2, que abunda en tumores neuroendocrinos bien diferenciados. El trazador se concentra donde están esos receptores y el galio-68 emite positrones que el PET detecta. Así se obtiene un mapa de los tumores en todo el cuerpo, incluidas lesiones pequeñas.","mp":["Dotatate se une al receptor SSTR2 del tumor.","Galio-68 emite positrones.","El PET muestra dónde está el tumor.","Mismo blanco que la terapia Lutathera."],"f":"Aprobado en 2016 para localizar tumores neuroendocrinos SSTR-positivos en adultos y niños.","e":[["Estudio prospectivo","Pacientes con tumores neuroendocrinos","Igual o mejor que indio-111; cambió el manejo en ~1/3 de pacientes"]],"en":"Aprobado y respaldado por estudios de detección.","s":["Dolor o ardor en el sitio de inyección","Náusea y vómito"],"sg":["Exposición a radiación (mínima posible).","Hipersensibilidad (erupción, picor; raramente reacciones graves)."]}},{"id":56,"n":"Ganirelix","al":"","ar":"sexual","ca":"fda","cl":"GnRH antagonist","ev":"fda","u":"Antagonista de GnRH utilizado durante estimulación ovárica para evitar ovulación prematura.","c":"Antagonista GnRH.","m":"Ganirelix · SC diario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/ganirelix","ci":["https://www.drugs.com/pro/fyremadel.html","https://doi.org/10.1016/s0015-0282(00)01638-1","https://organonpro.com/en-us/product/ganirelix-acetate-injection/","https://www.organon.com/product/usa/pi_circulars/g/ganirelix/ganirelix_pi.pdf"],"x":{"r":"Ganirelix es un decapéptido que bloquea el receptor de GnRH. Se usa en estimulación ovárica para FIV y evita la ovulación prematura. Se inyecta una vez al día durante la estimulación.","q":"Antagonista de GnRH en jeringa prellenada (genérico y Fyremadel).","m":"Bloquea los receptores de GnRH en la hipófisis y suprime rápido la LH y la FSH. En FIV, si la LH sube antes de tiempo, la paciente puede ovular y perder el ciclo. Ganirelix frena ese pico para que los óvulos se recolecten a tiempo. Su efecto es inmediato y reversible, con protocolos más cortos que los de agonistas.","mp":["Bloquea el receptor de GnRH.","Suprime LH y FSH rápidamente.","Evita el pico prematuro de LH."],"f":"Aprobado en 1999 (originalmente Antagon).","e":[["Fase 3 norteamericana","Vs protocolo largo de leuprolide","Embarazos comparables, menos inyecciones y menos reacciones locales"]],"en":"Aprobado con ensayos de fase 3.","s":["Reacción en sitio de inyección","Dolor de cabeza","Náusea","Molestia abdominal o pélvica"],"sg":["Síndrome de hiperestimulación ovárica (riesgo del ciclo).","Hipersensibilidad.","Contraindicado en embarazo."]}},{"id":57,"n":"GHK-Cu","al":"","ar":"piel","ca":"wellness","cl":"Copper-binding tripeptide","ev":"baja","u":"Complejo de GHK y cobre estudiado en piel y reparación tisular. Los datos cosméticos tópicos no establecen eficacia ni seguridad de inyecciones para rejuvenecer.","c":"Tripéptido unido a cobre con señales de reparación.","m":"Inyectable (no aprobado sistémico)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/ghk-cu","ci":["https://doi.org/10.3390/brainsci7020020","https://doi.org/10.1002/jor.22831","https://doi.org/10.18632/oncotarget.11168","https://pmc.ncbi.nlm.nih.gov/articles/PMC6073405/","https://pubmed.ncbi.nlm.nih.gov/26236730/","https://pubmed.ncbi.nlm.nih.gov/3169264/","https://pubmed.ncbi.nlm.nih.gov/8227353/","https://pmc.ncbi.nlm.nih.gov/articles/PMC4508379/"],"x":{"r":"El GHK-Cu inyectable es el mismo tripéptido de cobre de las cremas, pero vendido en el mercado wellness para piel, cabello y reparación de tejidos. Para el uso sistémico, toda la evidencia es animal o de laboratorio. No hay ensayos humanos.","q":"Tripéptido unido a cobre, uso inyectable no aprobado.","m":"En laboratorio y animales actúa como señal de remodelación de tejidos: influye en la matriz extracelular, aporta cobre, tiene efecto antioxidante y antiinflamatorio, favorece nuevos vasos sanguíneos y activa genes de reparación.","mp":["Remodela matriz extracelular.","Aporta cobre.","Antioxidante y antiinflamatorio.","Activa programas genéticos de reparación."],"f":"Uso sistémico/inyectable no aprobado por la FDA.","e":[["Injerto de ligamento","Ratas","Mejoría transitoria de cicatrización"],["Lesión pulmonar aguda","Ratones","Menos daño pulmonar"],["Humanos","—","Solo datos tópicos y de heridas; nada inyectable"]],"en":"Evidencia baja para uso inyectable.","s":["Sin datos humanos de uso inyectable."],"sg":["Dolor en el sitio; posible exceso de cobre con uso repetido (teórico).","Producto del mercado gris."]}},{"id":58,"n":"GHRP-2","al":"Pralmorelin","ar":"huesos","ca":"wellness","cl":"GHRP / ghrelin agonist","ev":"baja","u":"Secretagogo de GH estudiado en el eje de crecimiento; la estimulación hormonal no demuestra eficacia para antienvejecimiento.","c":"Imita ghrelina y estimula liberación de GH.","m":"Pralmorelin · inyectable","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/ghrp-2","ci":["https://doi.org/10.1210/jc.2004-1719","https://doi.org/10.1016/j.ghir.2023.101545"],"x":{"r":"GHRP-2 (pralmorelin) es un péptido sintético que imita a la ghrelina y hace que la hipófisis libere hormona de crecimiento. Su único uso validado es como prueba diagnóstica de reserva de GH, aprobado en Japón. No hay ensayos que respalden sus usos wellness.","q":"Agonista del receptor de ghrelina (secretagogo de GH).","m":"Activa el receptor de secretagogos de GH (receptor de ghrelina) en la hipófisis. Eso provoca un pulso de GH que luego sube el IGF-1. También sube un poco el cortisol y la prolactina y, como otros imitadores de ghrelina, aumenta el apetito.","mp":["Activa receptor de ghrelina.","Pulso de GH → más IGF-1.","Sube cortisol y prolactina.","Más apetito."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Pruebas diagnósticas","Personas con sospecha de déficit de GH","Mide la reserva de GH de la hipófisis"],["Usos wellness","—","Sin ensayos controlados"]],"en":"Evidencia baja para músculo, recuperación o antienvejecimiento.","s":["Hambre","Retención de líquido","Hormigueo"],"sg":["Sube cortisol y prolactina.","Producto del mercado gris."]}},{"id":59,"n":"GHRP-6","al":"","ar":"huesos","ca":"wellness","cl":"GHRP / ghrelin agonist","ev":"baja","u":"Secretagogo de GH estudiado por sus efectos hormonales y sobre apetito; faltan resultados clínicos adecuados para usos de bienestar.","c":"Secretagogo original tipo ghrelina.","m":"Inyectable","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/ghrp-6","ci":["https://doi.org/10.1161/01.res.0000016164.02525.b4","https://doi.org/10.1210/jcem.77.6.7903313","https://doi.org/10.1016/j.tem.2005.11.004"],"x":{"r":"GHRP-6 es uno de los primeros péptidos sintéticos que imitan a la ghrelina. Se vende para subir la hormona de crecimiento y el apetito. Los datos humanos son estudios cortos de niveles hormonales, sin ensayos de beneficio.","q":"Secretagogo de GH con fuerte efecto sobre el apetito.","m":"Activa el receptor de ghrelina para liberar GH y parece frenar a la somatostatina, el freno natural de la GH. Es menos selectivo que los péptidos nuevos: aumenta mucho el apetito y sube algo el cortisol y la prolactina. En laboratorio hay receptores en corazón y vasos, de ahí el interés en otros efectos.","mp":["Activa receptor de ghrelina.","Libera GH y frena somatostatina.","Apetito marcado.","Sube cortisol y prolactina."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Estudio de infusión","Hombres sanos","Subió GH e IGF-1"],["Efectos cardiovasculares","Preclínicos","Protección celular en modelos"]],"en":"Evidencia baja.","s":["Hambre intensa","Retención de líquido"],"sg":["Sube cortisol y prolactina.","Producto del mercado gris."]}},{"id":60,"n":"Glepaglutide","al":"","ar":"digestivo","ca":"ensayos","cl":"GLP-2 analog","ev":"moderada","u":"Análogo de GLP-2 investigado para mejorar absorción en síndrome de intestino corto y reducir necesidad de soporte parenteral.","c":"Análogo de GLP-2 de larga acción.","m":"SC (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/glepaglutide","ci":["https://doi.org/10.1053/j.gastro.2024.11.023","https://doi.org/10.1016/j.clnesp.2025.08.006"],"x":{"r":"Glepaglutide es un análogo de GLP-2 de larga acción de Zealand Pharma para síndrome de intestino corto. En fase 3 la dosis dos veces por semana redujo la nutrición IV, pero la semanal no. La FDA emitió una carta de respuesta completa en 2024 pidiendo más evidencia.","q":"Análogo de GLP-2 subcutáneo, en investigación.","m":"Activa el receptor GLP-2 del intestino, que estimula el crecimiento y adaptación de la mucosa y aumenta la absorción de nutrientes y líquidos. La meta es depender menos de la nutrición por vena.","mp":["Activa receptor GLP-2.","Mucosa intestinal crece y se adapta.","Más absorción de líquidos y nutrientes."],"f":"No aprobado; Carta de Respuesta Completa de la FDA en 2024.","e":[["EASE (fase 3)","Dos veces por semana, semanal o placebo","Dos veces por semana cumplió el objetivo; semanal no fue significativo"],["Fase 3b","Seguimiento a un año","Más absorción de energía y menos soporte parenteral"]],"en":"Evidencia moderada: un ensayo pivotal con resultado mixto.","s":["Reacciones en sitio de inyección","Efectos GI"],"sg":["Clase GLP-2: vigilar pólipos intestinales."]}},{"id":61,"n":"Glucagon","al":"","ar":"digestivo","ca":"fda","cl":"Glucagon receptor agonist","ev":"fda","u":"Hormona utilizada para rescate de hipoglucemia grave y determinados procedimientos diagnósticos según producto.","c":"Hormona pancreática que sube la glucosa rápido.","m":"Gvoke, Baqsimi (nasal), kits · SC/IM/nasal","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/glucagon","ci":["https://www.novomedlink.com/diabetes/products/treatments/glucagen-hypokit.html","https://doi.org/10.2337/dc15-1498","https://www.accessdata.fda.gov/drugsatfda_docs/label/2019/212097s000lbl.pdf","https://www.accessdata.fda.gov/drugsatfda_docs/label/2019/210134s000lbl.pdf"],"x":{"r":"El glucagón es una hormona del páncreas que sube el azúcar rápido. Se usa como rescate en hipoglucemia severa y como ayuda diagnóstica en estudios de imagen gastrointestinales. Hoy existen inyectores listos para usar (Gvoke) y un polvo nasal sin aguja (Baqsimi).","q":"Hormona contrarreguladora de la insulina.","m":"Se une a receptores del hígado y activa la degradación del glucógeno almacenado y la producción de glucosa nueva, así que la glucosa sube en minutos. Funciona menos si el hígado no tiene reservas (ayuno prolongado, alcohol). También relaja el músculo liso del tubo digestivo, la base de su uso en radiología.","mp":["Receptor de glucagón hepático.","Glucogenólisis + gluconeogénesis.","Glucosa sube en minutos.","Relaja músculo liso GI (uso diagnóstico)."],"f":"Inyección aprobada hace décadas; Gvoke y Baqsimi aprobados en 2019.","e":[["Ensayo de polvo nasal","Adultos con diabetes tipo 1","Subió la glucosa igual que el glucagón inyectado"]],"en":"Aprobado y de uso establecido.","s":["Náusea y vómito","Dolor de cabeza","Reacción en sitio o síntomas nasales/oculares con Baqsimi"],"sg":["Feocromocitoma: subida peligrosa de presión.","Insulinoma: hipoglucemia de rebote.","Alergias raras."]}},{"id":62,"n":"Glutathione","al":"","ar":"piel","ca":"wellness","cl":"Antioxidant tripeptide","ev":"moderada","u":"Tripéptido antioxidante endógeno. Los reclamos de desintoxicación, aclaramiento de piel o bienestar por inyección requieren evidencia específica y no prueban beneficio general.","c":"Tripéptido antioxidante principal dentro de las células.","m":"Oral, IV, inyectable, inhalado","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/glutathione","ci":["https://www.fda.gov/media/94155/download","https://doi.org/10.3109/09546631003801619","https://doi.org/10.1111/jocd.14137","https://doi.org/10.1111/jocd.12910","https://doi.org/10.1002/mds.22401","https://doi.org/10.3892/etm.2020.9557","https://pubmed.ncbi.nlm.nih.gov/24791752/","https://pubmed.ncbi.nlm.nih.gov/23631796/"],"x":{"r":"El glutatión es el principal antioxidante dentro de las células. Se vende como suplemento y en clínicas wellness en IV, inyectable o inhalado para aclarar la piel y como 'detox'. Los ensayos humanos son pequeños y mixtos, y la FDA ha advertido sobre el glutatión inyectable compuesto.","q":"Tripéptido antioxidante (glutamato-cisteína-glicina).","m":"Su papel bioquímico está bien establecido: neutraliza moléculas reactivas y participa en la detoxificación mediante sistemas enzimáticos. Para aclarar la piel, se propone que inhibe la tirosinasa y desvía la producción de pigmento hacia melanina más clara.","mp":["Neutraliza radicales libres.","Participa en detoxificación hepática.","Inhibiría tirosinasa → pigmento más claro (propuesto)."],"f":"No aprobado como medicamento. Oral = suplemento; formas IV o inhaladas = compounding. La FDA ha emitido advertencias sobre el inyectable compuesto.","e":[["Oral, 4 semanas","Piel","Pequeña reducción de pigmento vs placebo"],["Revisión sistemática","Aclarado de piel","No concluyente por calidad y biodisponibilidad"],["IV piloto","Parkinson","Sin beneficio vs placebo"],["Oral, 6 meses, 54 adultos","Niveles","Glutatión en sangre +30–35% a dosis alta; vuelve a basal al suspender"],["Inhalado, 6 meses, 153 personas","Fibrosis quística","Sin mejoría de FEV1 (p=0.18)"]],"en":"Evidencia moderada: estudios reales pero pequeños, cortos e inconsistentes.","s":["Oral: bien tolerado","Inhalado: tos, broncoespasmo en asmáticos"],"sg":["Advertencias FDA sobre calidad del inyectable compuesto (endotoxinas, contaminación).","No hay evidencia de seguridad del uso IV crónico para aclarar piel."]}},{"id":63,"n":"Goserelin","al":"","ar":"sexual","ca":"fda","cl":"GnRH agonist","ev":"fda","u":"Agonista de GnRH utilizado en enfermedades sensibles a hormonas, incluidos cánceres y afecciones ginecológicas seleccionadas según producto.","c":"Agonista GnRH en implante: suprime hormonas sexuales.","m":"Zoladex · implante SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/goserelin","ci":["https://doi.org/10.1016/s0959-8049(03)00392-7","https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/019726s076lbl020515s013lbl.pdf"],"x":{"r":"Goserelin (Zoladex) es un decapéptido agonista de GnRH en un pequeño implante que suprime la testosterona y el estrógeno. Se usa en cáncer de próstata, cáncer de mama y endometriosis. En el ensayo ZEBRA igualó a la quimioterapia CMF en supervivencia en ciertas mujeres premenopáusicas.","q":"Agonista de GnRH (LHRH) en implante subcutáneo mensual o trimestral.","m":"La primera exposición estimula la hipófisis y causa una subida temporal de LH y hormonas sexuales (el 'flare'). Como el implante libera el fármaco de forma continua y no en pulsos, los receptores se desensibilizan y en pocas semanas la LH y la FSH caen. La testosterona o el estrógeno bajan a niveles de castración o posmenopausia.","mp":["Estímulo inicial → 'flare' de hormonas.","Exposición continua → desensibilización.","LH/FSH caen en 2–4 semanas.","Testosterona o estrógeno bajan."],"f":"Aprobado en 1989; implantes de 3.6 mg (mensual) y 10.8 mg (trimestral).","e":[["ZEBRA","Mujeres premenopáusicas con cáncer de mama ER+","Equivalente a CMF en supervivencia libre de enfermedad y global"]],"en":"Aprobado con ensayos aleatorizados grandes.","s":["Sofocos y sudoración","Disfunción sexual y sequedad vaginal","Dolor de cabeza","Reacción en sitio","Pérdida ósea a largo plazo"],"sg":["'Flare' inicial en cáncer de próstata (a veces se cubre con antiandrógeno).","Más riesgo de hiperglucemia y eventos cardiovasculares con privación androgénica.","Apoplejía hipofisaria (rara)."]}},{"id":64,"n":"Hexapeptide-9","al":"","ar":"piel","ca":"cosmetico","cl":"Signal peptide","ev":"baja","u":"Ingrediente cosmético estudiado para apariencia y reparación de la piel; los datos son limitados y dependen de la formulación.","c":"Péptido señal que imita un motivo de colágeno.","m":"Tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/hexapeptide-9","ci":["https://ashland.com/industries/personal-and-home-care/skin-and-sun-care/collaxyl-ng-biofunctional","https://www.specialchem.com/cosmetics/inci-ingredients/hexapeptide-9","https://doi.org/10.1111/jocd.70290","https://doi.org/10.1016/j.mtbio.2025.101527"],"x":{"r":"El hexapéptido-9 es un péptido 'señal' de seis aminoácidos cuya secuencia imita un motivo del colágeno humano. En laboratorio indica a las células de la piel que fabriquen más matriz de soporte. El único ensayo humano controlado usó una versión química modificada, no el ingrediente estándar.","q":"Ingrediente cosmético inspirado en el colágeno (matriquina).","m":"Las matriquinas son fragmentos de proteínas que funcionan como mensajes para las células. El hexapéptido-9 le indicaría a los fibroblastos de la dermis y a los queratinocitos de la superficie que produzcan más colágeno y otros componentes de la matriz, y que refuercen la unión entre las capas de la piel.","mp":["Imita un fragmento del colágeno.","Estimula fibroblastos y queratinocitos.","Refuerza la unión dermo-epidérmica (laboratorio)."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Ensayo aleatorizado controlado","Versión ciclada del péptido, patrocinado por la industria","Mejoría de arrugas (no aplica directamente al ingrediente estándar)"]],"en":"Evidencia baja: no hay ensayo independiente del hexapéptido-9 estándar.","s":["Bien tolerado; baja irritación"],"sg":[]}},{"id":65,"n":"Hexarelin","al":"","ar":"huesos","ca":"wellness","cl":"GHRP / ghrelin agonist","ev":"baja","u":"Secretagogo experimental de GH; no hay beneficio clínico establecido para recuperación muscular o rejuvenecimiento.","c":"Secretagogo potente de GH tipo ghrelina.","m":"Inyectable","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/hexarelin","ci":["https://doi.org/10.1161/01.res.0000016164.02525.b4","https://doi.org/10.1159/000126827","https://doi.org/10.1016/j.tem.2005.11.004"],"x":{"r":"Hexarelin (examorelin) es un imitador potente de la ghrelina que libera hormona de crecimiento. Se vende para recuperación y composición corporal. Solo hay estudios cortos de niveles hormonales y su efecto se debilita con el uso repetido.","q":"Secretagogo de GH muy potente, no aprobado.","m":"Activa el receptor de ghrelina en la hipófisis y provoca pulsos de GH. También se une al receptor CD36 en tejido cardiovascular, lo que explica el interés preclínico en efectos sobre el corazón. Con exposición repetida el receptor se desensibiliza y la respuesta de GH disminuye.","mp":["Receptor de ghrelina → pulsos de GH.","Receptor CD36 cardíaco (preclínico).","Desensibilización con uso repetido."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Estudio en hombres sanos","Voluntarios","Mayor subida de GH que la GHRH y efecto sinérgico con ella"]],"en":"Evidencia baja.","s":["Hambre","Retención de líquido"],"sg":["Sube cortisol y prolactina.","Producto del mercado gris."]}},{"id":66,"n":"Histrelin","al":"","ar":"sexual","ca":"fda","cl":"GnRH agonist","ev":"fda","u":"Agonista de GnRH en implantes utilizados para pubertad precoz central o cáncer de próstata según producto.","c":"Agonista GnRH en implante anual.","m":"Supprelin LA · implante SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/histrelin","ci":["https://doi.org/10.1210/jc.2006-2479","https://www.endodocuments.com/supprelin-la/pi","https://mdedge.com/content/hormone-blocker-sticker-shock-again-patients-lose-cheaper-drug-option"],"x":{"r":"Histrelin (Supprelin LA) es un nonapéptido agonista de GnRH en un implante que libera el fármaco durante unos 12 meses. Se usa en pubertad precoz central en niños. El implante para cáncer de próstata (Vantas) se descontinuó en 2021.","q":"Agonista de GnRH en implante subdérmico anual.","m":"Igual que otros agonistas de GnRH: al principio estimula la hipófisis y hay una subida breve de hormonas sexuales (flare). Como el implante libera el fármaco continuamente, los receptores se desensibilizan y la LH y la FSH caen. En pubertad precoz, eso detiene la maduración ósea y el desarrollo puberal hasta una edad apropiada.","mp":["Estímulo inicial (flare la primera semana).","Desensibilización por exposición continua.","Hormonas sexuales bajan a nivel prepuberal.","Se pausa la pubertad y la maduración ósea."],"f":"Supprelin LA aprobado en 2007 para pubertad precoz central; Vantas (2004) descontinuado en 2021.","e":[["Estudio pediátrico pivotal","Niños con pubertad precoz central","LH pico de ~28 a <1 mIU/mL; supresión mantenida un año"]],"en":"Aprobado y respaldado por estudios del implante.","s":["Reacción en el sitio del implante (~50% de niños): dolor, moretón, hinchazón"],"sg":["Implante roto o difícil de remover.","Subida de hormonas la primera semana.","Cambios de ánimo: irritabilidad, llanto, agresividad.","Convulsiones.","Pseudotumor cerebri (dolor de cabeza, cambios de visión).","Reacciones graves de piel."]}},{"id":67,"n":"Human chorionic gonadotropin","al":"","ar":"sexual","ca":"fda","cl":"Glycoprotein gonadotropin","ev":"fda","u":"Gonadotropina utilizada en indicaciones reproductivas y endocrinas específicas; no es un tratamiento validado para pérdida de peso.","c":"Actúa como LH y estimula ovario/testículo.","m":"Pregnyl, Novarel · IM/SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/human-chorionic-gonadotropin","ci":["https://doi.org/10.1002/14651858.CD003719.pub4","https://www.fda.gov/drugs/medication-health-fraud/questions-and-answers-hcg-products-weight-loss","https://www.organon.com/product/usa/pi_circulars/p/pregnyl/pregnyl_pi.pdf","https://pubmed.ncbi.nlm.nih.gov/33933392/","https://pubmed.ncbi.nlm.nih.gov/29772111/"],"x":{"r":"La gonadotropina coriónica humana (hCG; Pregnyl, Novarel) es una hormona de la placenta que actúa como la LH. Provoca la ovulación en tratamientos de fertilidad y estimula la testosterona en hombres. NO está aprobada para bajar de peso: la FDA dice que no funciona para eso.","q":"Gonadotropina que imita a la LH.","m":"Se une al mismo receptor que la LH. En mujeres en tratamiento de fertilidad, una dosis imita el pico de LH de mitad de ciclo y hace que el óvulo termine de madurar y se libere. En hombres estimula a las células de Leydig del testículo a fabricar testosterona y apoya la producción de esperma. En niños con testículo no descendido, la testosterona puede ayudar al descenso.","mp":["Se une al receptor LH/CG.","Mujeres: maduración final y ovulación.","Hombres: testosterona intratesticular y espermatogénesis.","Niños: puede ayudar al descenso testicular."],"f":"Aprobada hace décadas para inducción de ovulación, hipogonadismo masculino y criptorquidia. No aprobada para pérdida de peso; los productos 'homeopáticos' de hCG son ilegales.","e":[["Revisión Cochrane","7 ensayos, 1,136 mujeres","hCG recombinante y urinaria con tasas similares de embarazo o nacido vivo (OR 1.15)"]],"en":"Aprobada y de uso establecido.","s":["Dolor en sitio de inyección","Dolor de cabeza","Retención de líquido","Sensibilidad mamaria o ginecomastia","Irritabilidad, inquietud, depresión"],"sg":["Síndrome de hiperestimulación ovárica y embarazo múltiple.","Pubertad precoz en niños tratados por criptorquidia.","Tromboembolismo arterial (raro)."]}},{"id":68,"n":"Humanin","al":"","ar":"hormonas","ca":"wellness","cl":"Mitochondrial-derived peptide","ev":"baja","u":"Péptido mitocondrial estudiado por funciones de protección celular y metabolismo; los resultados preclínicos no establecen utilidad terapéutica humana.","c":"Péptido codificado en la mitocondria con efecto protector.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/humanin","ci":["https://doi.org/10.1371/journal.pone.0006334","https://doi.org/10.3389/fnagi.2019.00123","https://doi.org/10.18632/aging.103534","https://www.deadiversion.usdoj.gov/schedules/orangebook/c_cs_alpha.pdf","https://pubmed.ncbi.nlm.nih.gov/35499074/","https://pubmed.ncbi.nlm.nih.gov/29955888/","https://pubmed.ncbi.nlm.nih.gov/33131010/","https://pubmed.ncbi.nlm.nih.gov/30242290/"],"x":{"r":"Humanin es un péptido pequeño codificado en el ADN de la mitocondria, estudiado para longevidad y protección cerebral. Se vende como 'research peptide'. Su evidencia es preclínica y observacional; nunca se ha probado como tratamiento en humanos.","q":"Péptido derivado de la mitocondria.","m":"Se propone que protege las células, ayuda a la supervivencia de las neuronas, reduce la muerte celular programada y mejora la sensibilidad a la insulina. En gusanos y ratones se asoció con más años de vida y de salud. En humanos se puede medir en sangre, pero los estudios no coinciden en si baja o sube con la edad.","mp":["Protección celular y neuronal (laboratorio).","Menos apoptosis.","Mejor sensibilidad a insulina (animales).","Más vida en gusanos y ratones."],"f":"No aprobado por la FDA.","e":[["Laboratorio","Células cerebrales","Previene pérdida de conexiones entre neuronas"],["Animales","Gusanos y ratones","Efectos en esperanza de vida y salud"],["Observacionales humanos","Medición en sangre","Resultados contradictorios con la edad"]],"en":"Evidencia baja: ningún ensayo de intervención en humanos.","s":["Sin datos de seguridad en humanos."],"sg":["Producto del mercado gris."]}},{"id":69,"n":"Icatibant","al":"","ar":"piel","ca":"fda","cl":"Bradykinin B2 antagonist","ev":"fda","u":"Antagonista de receptores de bradicinina utilizado para ataques agudos de angioedema hereditario en adultos.","c":"Bloquea el receptor B2 de bradicinina.","m":"Firazyr (y genéricos) · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/icatibant","ci":["https://doi.org/10.1016/j.anai.2011.08.015","https://ndclist.com/ndc/54092-702/label"],"x":{"r":"Icatibant (Firazyr y genéricos) es un péptido que bloquea el receptor B2 de bradicinina. Trata ataques agudos de angioedema hereditario (AEH) y el paciente se lo puede autoinyectar al primer síntoma.","q":"Antagonista del receptor B2 de bradicinina, autoinyectable.","m":"En el AEH falta o falla el inhibidor C1, y el cuerpo produce demasiada bradicinina. La bradicinina se une a receptores B2 de los vasos, que se dilatan y dejan escapar líquido a los tejidos: hinchazón y dolor. Icatibant bloquea ese receptor de forma selectiva y el ataque cede.","mp":["Déficit de C1-INH → exceso de bradicinina.","Bradicinina activa receptor B2 → fuga vascular.","Icatibant bloquea B2 → el ataque cede."],"f":"Aprobado en 2011 para ataques agudos de AEH en adultos; hay genéricos.","e":[["FAST-3","Ataques agudos de AEH","Alivio significativo en mediana de ~2 h vs ~20 h con placebo"]],"en":"Aprobado con ensayos aleatorizados.","s":["Reacción en el sitio casi universal: enrojecimiento, hinchazón, dolor, picor","Fiebre","Mareo"],"sg":["En ataques de laringe: ir a emergencias después de inyectarse; los síntomas de vía aérea pueden tardar.","Urticaria (postmercadeo)."]}},{"id":70,"n":"IGF-1 DES","al":"","ar":"huesos","ca":"wellness","cl":"IGF-1 analog","ev":"baja","u":"Variante experimental de IGF-1 estudiada en crecimiento y señalización celular; no es equivalente al medicamento mecasermin.","c":"Análogo corto y potente de IGF-1.","m":"Inyectable (químico de investigación)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/igf-1-des","ci":["https://doi.org/10.1042/bj2580267","https://doi.org/10.1152/ajprenal.1991.261.4.F626","https://doi.org/10.3389/fendo.2026.1822475"],"x":{"r":"IGF-1 DES es un análogo recortado y más potente del factor de crecimiento similar a la insulina tipo 1 (IGF-1). Se vende como químico de investigación para crecimiento muscular. No hay ningún estudio en humanos y está prohibido en el deporte.","q":"Análogo truncado de IGF-1, uso de rendimiento.","m":"Actúa en el receptor de IGF-1, la vía que impulsa la síntesis de proteína muscular. Al unirse menos a las proteínas transportadoras, tendría más actividad local que el IGF-1 natural. En roedores mejoró el balance de nitrógeno y redujo la degradación muscular.","mp":["Activa el receptor de IGF-1.","Menos unión a proteínas transportadoras → más potencia local.","Más síntesis proteica (animales y células)."],"f":"No aprobado por la FDA. Prohibido en el deporte. No confundir con mecasermin (Increlex), que sí está aprobado.","e":[["Estudio animal","Roedores","Mejor balance de nitrógeno, menos degradación de proteína"]],"en":"Evidencia baja: solo animal y celular.","s":["Sin datos humanos."],"sg":["Hipoglucemia (actividad tipo insulina).","Señalización de IGF-1 ligada a crecimiento tumoral.","Producto del mercado gris."]}},{"id":71,"n":"IGF-1 LR3","al":"","ar":"huesos","ca":"wellness","cl":"IGF-1 analog","ev":"baja","u":"Análogo experimental de IGF-1 de acción modificada; no tiene uso clínico establecido para aumentar masa muscular.","c":"Análogo de IGF-1 de larga acción.","m":"Inyectable (químico de investigación)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/igf-1-lr3","ci":["https://pubmed.ncbi.nlm.nih.gov/29535161/","https://doi.org/10.1038/s41598-019-46178-9","https://doi.org/10.3389/fendo.2026.1822475"],"x":{"r":"IGF-1 LR3 es un análogo de IGF-1 de larga acción vendido como químico de investigación para músculo. No hay estudios humanos y, en ratones con cáncer, frenó la pérdida muscular pero aceleró el crecimiento del tumor.","q":"Análogo modificado de IGF-1, uso de rendimiento.","m":"Activa el receptor de IGF-1 y la señal de crecimiento que promueve la síntesis de proteína muscular. Sus modificaciones prolongan su actividad en el cuerpo. El problema es que la misma señal de crecimiento estimula la división de otras células, incluidas las tumorales.","mp":["Activa receptor de IGF-1.","Acción prolongada.","Estimula crecimiento muscular… y de tumores (ratones)."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Caquexia por cáncer","Ratones","Menos pérdida muscular, pero crecimiento tumoral acelerado"],["Ensayos celulares","Células musculares","Más diferenciación muscular"]],"en":"Evidencia baja, con una señal de seguridad preclínica específica.","s":["Sin datos humanos."],"sg":["Señal de crecimiento tumoral en animales.","Hipoglucemia.","Producto del mercado gris."]}},{"id":72,"n":"Insulin analogs","al":"","ar":"hormonas","ca":"fda","cl":"Insulin receptor agonist","ev":"fda","u":"Familia de insulinas utilizadas para controlar glucosa en diabetes; las diferencias de acción y concentración son críticas para evitar errores.","c":"Insulinas modificadas para acción rápida o prolongada.","m":"Lispro, aspart, glargine, detemir, degludec · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/insulin-analogs-multiple","ci":["https://www.novocare.com/levemir.html","https://doi.org/10.2337/diacare.26.11.3080","https://uspl.lilly.com/humalog/humalog.html"],"x":{"r":"Los análogos de insulina son versiones modificadas en laboratorio de la insulina, diseñadas para actuar más rápido o durar más. Se usan en diabetes tipo 1 y en tipo 2 cuando otros tratamientos no bastan. Los rápidos cubren las comidas y los basales dan cobertura de fondo.","q":"Insulinas de acción rápida (lispro, aspart, glulisina) y basal (glargina, detemir, degludec).","m":"Se unen al receptor de insulina en músculo, grasa e hígado, igual que la insulina natural. Las células toman glucosa (transportador GLUT4), se almacena energía y el hígado deja de fabricar glucosa. Los cambios de aminoácidos no alteran esa acción; cambian la rapidez con que se absorbe y cuánto dura. Las rápidas se separan y absorben en minutos; las basales precipitan o se unen a albúmina para liberarse lento y parejo.","mp":["Receptor de insulina → GLUT4 → la célula toma glucosa.","El hígado produce menos glucosa.","Rápidas: absorción en minutos para las comidas.","Basales: liberación lenta y estable todo el día."],"f":"Aprobados desde 1996 (lispro), glargina en 2000 y luego aspart, glulisina, detemir y degludec.","e":[["Treat-to-Target","Diabetes tipo 2 con orales","Más pacientes llegaron a su meta de A1c con menos hipoglucemia nocturna que con NPH"]],"en":"Aprobados con evidencia aleatorizada extensa.","s":["Hipoglucemia","Aumento de peso","Reacciones o bultos de grasa en el sitio (lipodistrofia)","Potasio bajo"],"sg":["Hipoglucemia severa: convulsiones o pérdida de conciencia.","Retención de líquido e insuficiencia cardíaca con tiazolidinedionas.","Nunca compartir plumas, aunque se cambie la aguja."]}},{"id":73,"n":"Ipamorelin","al":"","ar":"huesos","ca":"wellness","cl":"GHRP / ghrelin receptor agonist","ev":"baja","u":"Agonista del receptor de grelina estudiado como secretagogo de GH; faltan datos para validar usos de composición corporal y antienvejecimiento.","c":"Secretagogo selectivo tipo ghrelina.","m":"Inyectable SC","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/ipamorelin","ci":["https://my.clevelandclinic.org/health/body/22804-ghrelin","https://pubmed.ncbi.nlm.nih.gov/9849822/","https://doi.org/10.1023/a:1018955126402","https://pubmed.ncbi.nlm.nih.gov/10496658/","https://doi.org/10.1054/ghir.2001.0239","https://doi.org/10.1124/jpet.108.149211","https://pubmed.ncbi.nlm.nih.gov/25331030/","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks"],"x":{"r":"Ipamorelin es un péptido sintético que imita a la ghrelina para liberar más hormona de crecimiento propia. Es de los más vendidos en wellness, a menudo junto a CJC-1295. Su único ensayo de eficacia (íleo posoperatorio) no cumplió su objetivo. No es elegible para compounding de rutina y está prohibido en el deporte.","q":"Secretagogo selectivo de GH (agonista del receptor de ghrelina).","m":"Activa el receptor de ghrelina y la hipófisis libera GH en pulsos. Se le llama 'selectivo' porque en cerdos liberó GH sin subir ACTH ni cortisol, a diferencia de GHRP-6 y GHRP-2. Se combina con análogos de GHRH porque ambas vías se potencian, pero esa combinación no tiene ensayos publicados.","mp":["Activa receptor de ghrelina.","Pulsos de GH.","Poco efecto en cortisol y prolactina (animales).","Vida media ~2 horas en humanos."],"f":"No aprobado por la FDA; no elegible para compounding de rutina; prohibido en el deporte.","e":[["Estudio de dosis","Hombres sanos","Liberó GH; vida media de 2 h"],["Beck 2014 (fase 2)","114 pacientes tras resección intestinal","Primera comida tolerada a 25.3 h vs 32.6 h; no significativo (p=0.15)"],["Modelos animales","Ratas","Datos de hueso y tránsito intestinal"]],"en":"Evidencia baja: el único ensayo de eficacia fue negativo.","s":["Rubor","Dolor de cabeza","Reacciones en el sitio"],"sg":["Producto del mercado gris.","Sin datos de seguridad a largo plazo."]}},{"id":74,"n":"Kisspeptin-10","al":"","ar":"sexual","ca":"wellness","cl":"Reproductive peptide","ev":"moderada","u":"Péptido regulador del eje reproductivo investigado en fertilidad y respuestas hormonales; no equivale a un tratamiento aprobado de libido.","c":"Fragmento de kisspeptina que estimula GnRH.","m":"Inyectable (investigación)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/kisspeptin-10","ci":["https://wada-ama.org/en/prohibited-list","https://doi.org/10.1172/JCI89519","https://doi.org/10.1172/jci.insight.121958","https://doi.org/10.1001/jamanetworkopen.2022.36131","https://doi.org/10.1210/endrev/bnad023","https://pubmed.ncbi.nlm.nih.gov/23153270/"],"x":{"r":"Kisspeptin-10 es un fragmento de una hormona reproductiva natural, vendido como 'research peptide'. Hay investigación humana real y revisada por pares, pero en estudios pequeños y casi siempre con la forma larga (kisspeptin-54). Sigue en investigación.","q":"Fragmento de kisspeptina que activa el eje reproductivo.","m":"La kisspeptina activa receptores en las neuronas de GnRH del cerebro. Esas neuronas liberan GnRH, que a su vez hace que la hipófisis suelte LH y FSH, las hormonas que regulan ovarios y testículos. Este papel está bien establecido. Sus efectos en zonas del cerebro del deseo y las emociones son un área emergente.","mp":["Activa receptor de kisspeptina en neuronas GnRH.","Liberación de GnRH.","Hipófisis libera LH y FSH.","Gónadas producen hormonas sexuales."],"f":"No aprobado por la FDA; sigue en investigación.","e":[["George 2013","5 hombres con diabetes tipo 2 y testosterona baja, sin placebo","LH de 3.9 a 20.7 IU/L (p=0.03); testosterona de 8.5 a 11.4 nmol/L (p=0.002)"],["Ensayo cruzado con kisspeptin-54","32 mujeres con deseo sexual bajo","Cambios en resonancia cerebral (no resultado clínico)"]],"en":"Evidencia moderada: estudios humanos reales pero pequeños y con marcadores sustitutos.","s":["Bien tolerado en estudios cortos"],"sg":["Producto del mercado gris fuera de investigación."]}},{"id":75,"n":"KPV","al":"","ar":"digestivo","ca":"wellness","cl":"Anti-inflammatory tripeptide","ev":"baja","u":"Fragmento peptídico investigado por efectos antiinflamatorios principalmente preclínicos; no hay eficacia clínica establecida para enfermedad intestinal o cutánea.","c":"Tripéptido antiinflamatorio del extremo de α-MSH.","m":"Oral / tópico / inyectable","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/kpv","ci":["https://doi.org/10.1002/ibd.20334","https://doi.org/10.1016/j.ymthe.2016.11.020","https://doi.org/10.1136/ard.2007.079780"],"x":{"r":"KPV es un tripéptido antiinflamatorio (lisina-prolina-valina) derivado de la cola de la hormona α-MSH. Se vende para inflamación intestinal y de piel. No hay ensayos en humanos; en 2026 un comité asesor de la FDA votó de forma no vinculante a favor de permitir su compounding.","q":"Fragmento de α-MSH con actividad antiinflamatoria.","m":"Conserva gran parte del efecto antiinflamatorio de la α-MSH. En laboratorio entra a células del intestino y del sistema inmune y frena la vía inflamatoria NF-κB y mensajeros como el TNF-α. Parte de ese efecto no depende del receptor MC1R.","mp":["Entra a células intestinales e inmunes.","Frena la vía NF-κB.","Menos TNF-α y otras citoquinas."],"f":"No aprobado por la FDA. Voto favorable no vinculante de comité asesor (2026) para compounding; verificar decisión final.","e":[["Modelos de colitis","Ratones","Menos inflamación, parcialmente independiente de MC1R"],["KPV en nanopartículas","Ratones con colitis","Curación de mucosa y menos TNF-α"]],"en":"Evidencia baja: solo preclínica.","s":["Sin datos humanos."],"sg":["Producto del mercado gris."]}},{"id":76,"n":"Lanreotide","al":"","ar":"digestivo","ca":"fda","cl":"Somatostatin analog","ev":"fda","u":"Análogo de somatostatina utilizado en acromegalia y ciertos tumores neuroendocrinos; las indicaciones son específicas del producto.","c":"Análogo de somatostatina de larga acción.","m":"Somatuline Depot · SC profunda mensual","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/lanreotide","ci":["https://doi.org/10.1056/NEJMoa1316158","https://www.ipsen.com/websites/Ipsen_Online/wp-content/uploads/2023/03/23125252/Somatuline-Depot_USPI_Feb_2023.pdf"],"x":{"r":"Lanreotide (Somatuline Depot) es un análogo de somatostatina de larga acción. Suprime la hormona de crecimiento y las hormonas intestinales, y frena el crecimiento de ciertos tumores neuroendocrinos. En el ensayo CLARINET retrasó significativamente la progresión tumoral.","q":"Análogo de somatostatina en inyección mensual.","m":"Se une a los receptores de somatostatina 2 y 5 en células que secretan hormonas y en células tumorales. Así baja la GH, el IGF-1 y las hormonas intestinales. Además tiene un efecto antiproliferativo sobre tumores neuroendocrinos bien diferenciados.","mp":["Receptores de somatostatina 2 y 5.","Baja GH e IGF-1 (acromegalia).","Baja hormonas intestinales (síntomas carcinoides).","Frena el crecimiento tumoral."],"f":"Aprobado en 2007 (acromegalia), 2014 (tumores neuroendocrinos GEP) y luego síndrome carcinoide.","e":[["CLARINET","Tumores neuroendocrinos enteropancreáticos metastásicos","Supervivencia libre de progresión no alcanzada vs 18 meses con placebo"]],"en":"Aprobado con ensayo aleatorizado.","s":["Diarrea y dolor abdominal","Náusea","Cálculos biliares","Reacción en el sitio","Bradicardia"],"sg":["Enfermedad de vesícula con uso prolongado.","Cambios en glucosa y tiroides.","Efectos en la conducción cardíaca."]}},{"id":77,"n":"Larazotide acetate","al":"","ar":"digestivo","ca":"ensayos","cl":"Zonulin antagonist (tight-junction regulator)","ev":"baja","u":"Compuesto investigado para modular la barrera intestinal en enfermedad celíaca; no sustituye una dieta sin gluten ni demuestra tratar cualquier permeabilidad intestinal.","c":"Ayuda a cerrar uniones del intestino (antagonista de zonulina).","m":"Oral (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/larazotide-acetate","ci":["https://doi.org/10.1152/ajpgi.00386.2020","https://www.beyondceliac.org/research-news/phase-3-study-discontinued/","https://doi.org/10.1016/j.clinre.2021.101782"],"x":{"r":"El acetato de larazotide es un péptido oral experimental que se estudió como complemento de la dieta sin gluten en celiaquía, para 'cerrar' las uniones entre células intestinales. Su fase 3 se detuvo por futilidad y su programa principal se canceló.","q":"Regulador de uniones estrechas (antagonista de zonulina), en investigación.","m":"El revestimiento intestinal tiene uniones entre células que controlan lo que pasa. En la celiaquía esas uniones se aflojan y fragmentos de gluten cruzan y causan inflamación. Larazotide contrarrestaría la zonulina para cerrar esas uniones.","mp":["Bloquearía la zonulina.","Cerraría uniones estrechas.","Menos paso de gluten (propuesto)."],"f":"No aprobado; programa principal detenido.","e":[["CeDLara (fase 3)","Celiaquía, análisis interino 2022","Detenido por futilidad"],["Metanálisis de 4 ensayos","Celiaquía","Sin efecto en la prueba de permeabilidad lactulosa/manitol"]],"en":"Evidencia baja: los datos humanos son negativos.","s":["Sin perfil relevante."],"sg":[]}},{"id":78,"n":"Leuprolide","al":"","ar":"sexual","ca":"fda","cl":"GnRH agonist","ev":"fda","u":"Agonista de GnRH utilizado para supresión hormonal en cáncer de próstata, endometriosis y otras indicaciones según formulación.","c":"Agonista GnRH: con uso continuo apaga hormonas sexuales.","m":"Lupron, Eligard, Fensolvi · IM/SC depot","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/leuprolide","ci":["https://doi.org/10.1210/jc.2011-2704","https://www.rxabbvie.com/pdf/lupronuro_pi.pdf","https://www.rxabbvie.com/pdf/lupronpediatric.pdf"],"x":{"r":"Leuprolide (Lupron, Eligard, Fensolvi, Camcevi) es un nonapéptido agonista de GnRH. Dado de forma continua apaga la producción de testosterona y estrógeno. Se usa en cáncer de próstata, endometriosis, miomas y pubertad precoz.","q":"Agonista de GnRH en depósitos de 1 a 6 meses.","m":"La primera dosis estimula la hipófisis y sube brevemente la LH, la FSH y la testosterona (flare). Como luego ocupa el receptor de forma continua y no en pulsos, la hipófisis se desensibiliza. En 2–4 semanas la testosterona o el estrógeno caen a niveles de castración o posmenopausia.","mp":["Flare inicial.","Exposición continua → desensibilización.","LH y FSH caen.","Testosterona/estrógeno a nivel de castración en 2–4 semanas."],"f":"Aprobado en 1985 (diario), Lupron Depot en 1989 y luego Eligard, Fensolvi y Camcevi.","e":[["Décadas de ensayos controlados","Próstata, endometriosis, miomas, pubertad precoz","Supresión hormonal efectiva en cada indicación"]],"en":"Aprobado y de uso establecido.","s":["Sofocos y sudoración","Dolor en el sitio","Menos libido y disfunción eréctil","Fatiga y cambios de ánimo","Pérdida ósea a largo plazo"],"sg":["Flare tumoral las primeras semanas en cáncer de próstata.","Hiperglucemia, diabetes y eventos CV con privación prolongada.","Convulsiones (raras).","Niños: cambios de conducta y pseudotumor cerebri."]}},{"id":79,"n":"Linaclotide","al":"","ar":"digestivo","ca":"fda","cl":"Guanylate cyclase-C agonist","ev":"fda","u":"Agonista de guanilato ciclasa C utilizado para estreñimiento y determinados síndromes de intestino irritable; edad e indicación dependen de la etiqueta.","c":"Activa guanilato ciclasa-C: más líquido en el intestino.","m":"Linzess · cápsula oral","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/linaclotide","ci":["https://doi.org/10.1038/ajg.2012.254","https://www.rxabbvie.com/pdf/linzess_pi.pdf"],"x":{"r":"Linaclotide (Linzess) es un péptido que casi no se absorbe y actúa dentro del intestino. Atrae líquido y alivia el dolor abdominal en el síndrome de intestino irritable con estreñimiento (IBS-C) y en el estreñimiento crónico. Se toma en cápsula diaria.","q":"Agonista de guanilato ciclasa-C de acción local.","m":"Activa la guanilato ciclasa-C de las células del intestino. Eso sube el GMP cíclico, que abre canales de cloruro y bicarbonato y saca líquido hacia el intestino. Las heces se ablandan y avanzan más rápido. El GMP cíclico fuera de las células también calmaría los nervios del dolor en la pared intestinal.","mp":["Activa guanilato ciclasa-C.","Sube GMPc → secreción de cloruro y agua.","Heces más blandas y tránsito más rápido.","Menos sensibilidad al dolor intestinal."],"f":"Aprobado en 2012 para IBS-C y estreñimiento crónico en adultos; luego en niños. Advertencia en recuadro: contraindicado en menores de 2 años.","e":[["Programa de fase 3 en IBS-C","Adultos","~1/3 respondió según criterio combinado FDA vs ~14% placebo"]],"en":"Aprobado con ensayos de fase 3 grandes.","s":["Diarrea (principal causa de abandono)","Dolor abdominal","Gases e hinchazón"],"sg":["Diarrea severa con deshidratación.","Contraindicado en menores de 2 años y en obstrucción intestinal."]}},{"id":80,"n":"Liraglutide","al":"","ar":"digestivo","ca":"fda","cl":"GLP-1 receptor agonist","ev":"fda","u":"Agonista GLP-1 utilizado en diabetes tipo 2 o manejo de peso según marca, dosis e indicación aprobada.","c":"Agonista GLP-1 diario con cadena de ácido graso.","m":"Victoza, Saxenda · pluma SC diaria","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/liraglutide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/022341s044lbl.pdf","https://www.drugs.com/liraglutide.html","https://www.sciencedirect.com/science/article/pii/S1043661825004700","https://doi.org/10.1056/NEJMoa1603827","https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/206321s022lbl.pdf","https://doi.org/10.1056/NEJMoa1411892"],"x":{"r":"Liraglutide (Victoza para diabetes, Saxenda para peso) es un GLP-1 diario hecho a partir del GLP-1 humano con una cadena de ácido graso que se une a la albúmina. Produjo ~8% de pérdida de peso en SCALE y fue el primer GLP-1 en demostrar reducción de eventos cardiovasculares (LEADER).","q":"Agonista GLP-1 de una vez al día en pluma.","m":"Activa el receptor GLP-1: libera insulina solo cuando la glucosa está alta, baja el glucagón y retrasa el vaciado del estómago. En el cerebro aumenta la sensación de llenura y reduce el hambre, la base de su efecto en el peso. El GLP-1 natural dura minutos; la cadena de ácido graso de liraglutide se une a la albúmina y alarga su acción a un día.","mp":["Insulina dependiente de glucosa.","Menos glucagón.","Vaciado gástrico más lento.","Centros del apetito: más saciedad.","Unión a albúmina → dosis diaria."],"f":"Victoza aprobado en 2010 (diabetes tipo 2 y luego riesgo CV); Saxenda en 2014 (peso). Ambos aprobados también en adolescentes.","e":[["SCALE","Adultos con obesidad, 56 semanas, 3.0 mg","≈ −8% de peso vs ≈ −2.6% placebo"],["LEADER","Diabetes tipo 2 con alto riesgo CV","Menos eventos cardiovasculares mayores"],["Programa LEAD","Diabetes tipo 2","Mejoría de A1c"]],"en":"Aprobado con programas de ensayos grandes.","s":["Náusea","Diarrea","Vómito","Estreñimiento","Menos apetito","Dolor de cabeza","Fatiga"],"sg":["Advertencia de tumores tiroideos C.","Pancreatitis.","Vesícula.","Daño renal por deshidratación.","Hipoglucemia con insulina/sulfonilureas.","Aumento de frecuencia cardíaca."]}},{"id":81,"n":"Lixisenatide","al":"","ar":"hormonas","ca":"fda","cl":"GLP-1 receptor agonist","ev":"fda","u":"Agonista GLP-1 utilizado para diabetes tipo 2; no deben trasladarse automáticamente indicaciones de otros miembros de la familia.","c":"Agonista GLP-1 de acción corta.","m":"Adlyxin (descontinuado) / Soliqua con glargine","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/lixisenatide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/208471s009lbl.pdf","https://doi.org/10.1056/NEJMoa1509225","https://www.rxless.com/resources/adlyxin-lixisenatide-will-no-longer-be-available-in-the-us"],"x":{"r":"Lixisenatide es un GLP-1 de acción corta derivado de la exendina-4 del lagarto. Se toma antes de una comida para frenar el pico de azúcar posprandial en diabetes tipo 2. Adlyxin se descontinuó en 2023, pero sigue disponible combinado con glargina en Soliqua.","q":"GLP-1 prandial; hoy solo en combinación (Soliqua).","m":"Activa el receptor GLP-1: libera insulina dependiente de glucosa, baja el glucagón y retrasa mucho el vaciado del estómago. Como dura poco, su efecto más fuerte es aplanar el pico de glucosa después de la comida, no dar cobertura de 24 horas.","mp":["Insulina dependiente de glucosa.","Menos glucagón.","Vaciado gástrico muy lento → menos pico posprandial."],"f":"Aprobado en 2016; Adlyxin descontinuado en 2023; disponible en Soliqua.","e":[["ELIXA","Diabetes tipo 2 con síndrome coronario agudo reciente","Seguro a nivel cardiovascular (sin aumento de eventos)"],["Programa GetGoal","Diabetes tipo 2","Mejoría de glucosa posprandial y A1c"]],"en":"Aprobado.","s":["Náusea","Vómito","Diarrea","Dolor de cabeza","Mareo"],"sg":["Pancreatitis.","Anafilaxia.","Daño renal por deshidratación.","Hipoglucemia con insulina/sulfonilureas."]}},{"id":82,"n":"LL-37","al":"","ar":"inmune","ca":"wellness","cl":"Host-defense antimicrobial peptide","ev":"baja","u":"Péptido de defensa innata investigado en infección, inflamación y cicatrización; no es un antibiótico clínico validado para uso general.","c":"Péptido antimicrobiano natural del sistema inmune.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/ll-37","ci":["https://doi.org/10.1016/j.bbrc.2020.03.162","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://www.fda.gov/media/94155/download","https://www.fda.gov/advisory-committees/pharmacy-compounding-advisory-committee/meeting-pharmacy-compounding-advisory-committee","https://pubmed.ncbi.nlm.nih.gov/11015447/","https://pubmed.ncbi.nlm.nih.gov/11389039/","https://pubmed.ncbi.nlm.nih.gov/12603850/","https://pubmed.ncbi.nlm.nih.gov/23766266/"],"x":{"r":"LL-37 es el péptido antimicrobiano natural del cuerpo humano (la única catelicidina humana). Se vende como 'research peptide' para apoyo inmune. Su biología está muy estudiada, pero no hay evidencia de eficacia para uso inyectable y su efecto puede ser proinflamatorio según el contexto.","q":"Catelicidina humana; péptido de defensa del huésped.","m":"Tiene dos acciones. Su estructura con carga positiva rompe directamente las membranas de los microbios. Además regula el sistema inmune: atrae células inmunes, modula la inflamación y participa en la cicatrización. Ese efecto inmune depende del contexto: puede ser antiinflamatorio o proinflamatorio, y se ha implicado en enfermedades inflamatorias de la piel como la rosácea y la psoriasis.","mp":["Rompe membranas microbianas.","Recluta células inmunes.","Modula la inflamación (en ambas direcciones).","Participa en cicatrización."],"f":"No aprobado por la FDA.","e":[["Biología humana y de laboratorio","Inmunidad innata, heridas, piel","Funciones bien documentadas"],["Uso inyectable wellness","—","Sin ensayos controlados"]],"en":"Evidencia baja para el uso que se vende.","s":["Sin datos humanos del uso inyectable."],"sg":["Puede ser proinflamatorio; ligado a rosácea y psoriasis.","Producto del mercado gris."]}},{"id":83,"n":"LTX-315","al":"","ar":"piel","ca":"ensayos","cl":"Oncolytic peptide","ev":"moderada","u":"Péptido oncolítico investigado en inmunoterapia de tumores; su contexto de estudio es oncológico y especializado.","c":"Péptido oncolítico inyectado en el tumor.","m":"Intratumoral (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/ltx-315","ci":["https://doi.org/10.1158/1078-0432.CCR-20-3435","https://verrica.com/press_release/verrica-pharmaceuticals-announces-fda-acceptance-of-its-ind-application-for-ltx-315-a-potential-first-in-class-oncolytic-peptide-based-immunotherapy-for-the-treatment-of-basal-cell-carcinoma/"],"x":{"r":"LTX-315 es un péptido oncolítico experimental que se inyecta directamente en el tumor para romper sus células y provocar una respuesta inmune. En fase 1 redujo tumores inyectados en algunos pacientes. No hay ensayos controlados de eficacia.","q":"Péptido oncolítico intratumoral (Lytix Biopharma).","m":"Se inserta en la membrana de las células tumorales y las rompe. Al morir así liberan antígenos del tumor y 'señales de peligro' que alertan al sistema inmune. Llegan linfocitos T y podría haber respuesta incluso en tumores no inyectados (efecto abscopal). Por eso se combina con inhibidores de puntos de control inmune.","mp":["Rompe la membrana de la célula tumoral.","Libera antígenos y señales de peligro.","Atrae linfocitos T al tumor.","Posible respuesta en tumores no inyectados."],"f":"No aprobado.","e":[["Fase 1","Tumores sólidos avanzados","Necrosis, infiltración de linfocitos T, ≥30% de reducción de tumores inyectados en algunos"],["Fase 2 y combinaciones","Mayormente comunicados de la compañía","Datos preliminares"]],"en":"Evidencia moderada: datos humanos tempranos sin grupo control.","s":["Dolor en sitio de inyección","Reacciones locales"],"sg":["Hipotensión transitoria y reacciones alérgicas reportadas en fase 1."]}},{"id":84,"n":"Lutetium Lu-177 dotatate","al":"","ar":"digestivo","ca":"fda","cl":"SSTR-targeted radiopeptide","ev":"fda","u":"Radiofármaco terapéutico para tumores neuroendocrinos seleccionados que expresan receptores de somatostatina.","c":"Radiación dirigida a células con receptor de somatostatina.","m":"Lutathera · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/lutetium-lu-177-dotatate","ci":["https://doi.org/10.1056/NEJMoa1607427","https://www.novartis.com/us-en/sites/novartis_us/files/lutathera.pdf"],"x":{"r":"Lutecio Lu-177 dotatate (Lutathera) es radioterapia dirigida: une un isótopo radioactivo a un análogo de somatostatina para llevar la radiación directo a tumores neuroendocrinos. Fue la primera terapia con radionúclidos dirigida a receptores de péptidos (PRRT) aprobada en EE.UU.","q":"Radiofármaco terapéutico (PRRT).","m":"El péptido dotatate se une al receptor de somatostatina tipo 2 de las células tumorales y entra en ellas. El lutecio-177 emite partículas beta de corto alcance que dañan el ADN de la célula tumoral y sus vecinas, respetando la mayor parte del tejido sano. Es la pareja 'teranóstica' del Ga-68 dotatate: el escáner confirma el blanco antes de tratar.","mp":["Dotatate se une a SSTR2 del tumor.","El complejo entra a la célula.","Lu-177 emite radiación beta.","Daño al ADN del tumor."],"f":"Aprobado en 2018 para tumores neuroendocrinos gastroenteropancreáticos SSTR-positivos en adultos; después en adolescentes.","e":[["NETTER-1","Tumores neuroendocrinos de intestino medio avanzados","Mejoró mucho la supervivencia libre de progresión vs octreotide en dosis alta"]],"en":"Aprobado con ensayo aleatorizado.","s":["Náusea y vómito (en parte por la infusión de aminoácidos)","Fatiga","Conteos sanguíneos bajos"],"sg":["Supresión de médula ósea; riesgo de síndrome mielodisplásico o leucemia.","Toxicidad renal y hepática.","Crisis hormonal neuroendocrina.","Angioedema.","Radiación y efectos en fertilidad."]}},{"id":85,"n":"Lutetium Lu-177 vipivotide tetraxetan","al":"","ar":"sexual","ca":"fda","cl":"PSMA-targeted radioligand","ev":"fda","u":"Radiofármaco dirigido a PSMA utilizado en pacientes seleccionados con cáncer de próstata avanzado.","c":"Radioligando que lleva radiación a células con PSMA.","m":"Pluvicto · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/lutetium-lu-177-vipivotide-tetraxetan","ci":["https://doi.org/10.1056/NEJMoa2107322","https://www.novartis.com/us-en/sites/novartis_us/files/pluvicto.pdf","https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/215833s037lbl.pdf"],"x":{"r":"Lutecio Lu-177 vipivotide tetraxetán (Pluvicto) es radioterapia dirigida a PSMA, una proteína de las células de cáncer de próstata. Se usa en cáncer de próstata metastásico PSMA-positivo y su indicación se ha ampliado desde 2022.","q":"Radioligando dirigido a PSMA.","m":"Las células de cáncer de próstata tienen mucha PSMA en su superficie. La parte dirigida del fármaco se une a PSMA y el lutecio-177 emite radiación beta de corto alcance. Así concentra la radiación en el cáncer y causa daño letal al ADN, limitando la exposición del tejido sano. Antes se confirma el blanco con un PET de PSMA.","mp":["PET de PSMA confirma el blanco.","El ligando se une a PSMA.","Lu-177 irradia la célula tumoral.","Daño letal al ADN."],"f":"Aprobado en 2022 (tras hormonoterapia y taxano); ampliado en 2025 (antes de quimioterapia) y 2026 (junto a hormonoterapia).","e":[["VISION","Cáncer de próstata metastásico resistente a castración, tras hormonas y quimio","Mejoró supervivencia libre de progresión por imagen y supervivencia global"]],"en":"Aprobado con ensayo aleatorizado.","s":["Fatiga","Boca seca","Náusea y menos apetito","Anemia","Estreñimiento"],"sg":["Supresión de médula ósea.","Toxicidad renal.","Precauciones de radiación para proteger a otros.","Efectos en fertilidad."]}},{"id":86,"n":"Mazdutide","al":"","ar":"digestivo","ca":"ensayos","cl":"GLP-1 / glucagon dual agonist","ev":"alta","u":"Agonista dual de GLP-1 y glucagón estudiado para obesidad y diabetes; una aprobación fuera de EE. UU. no equivale a aprobación de FDA.","c":"Agonista dual GLP-1 / glucagón.","m":"SC semanal","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/mazdutide","ci":["https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1001/jama.2026.8142","https://doi.org/10.1007/s40265-025-02249-y","https://doi.org/10.1056/NEJMoa2411528","https://doi.org/10.1111/dom.71058","https://clinicaltrials.gov/study/NCT06124807","https://doi.org/10.3390/ijms232314631","https://doi.org/10.1111/dom.15693"],"x":{"r":"Mazdutide es un agonista dual de GLP-1 y glucagón, desarrollado por Innovent bajo licencia de Eli Lilly, de inyección semanal para peso y diabetes. En fase 3 produjo cerca de 17% de pérdida de peso. Está aprobado en China (2025) pero no en EE.UU.","q":"Agonista dual GLP-1/glucagón semanal.","m":"Combina dos acciones. El brazo GLP-1 libera insulina dependiente de glucosa, retrasa el vaciado gástrico y reduce el apetito. El brazo de glucagón busca aumentar el gasto de energía y la quema de grasa en el hígado. La idea es lograr más pérdida de peso y menos hígado graso que con GLP-1 solo.","mp":["GLP-1: menos apetito, mejor glucosa.","Glucagón: más gasto energético.","Glucagón: menos grasa hepática."],"f":"Aprobado en China en 2025; no aprobado por la FDA.","e":[["GLORY-1","Adultos chinos con obesidad/sobrepeso, 48 semanas, 4 o 6 mg","Reducción significativa de peso vs placebo"],["GLORY-2","Obesidad moderada a severa, 60 semanas","≈ −17% vs ≈ −2% placebo"]],"en":"Evidencia alta en población china; sin aprobación en EE.UU.","s":["Vómito","Náusea","Diarrea (mayormente leves a moderados)"],"sg":["Advertencias de clase GLP-1.","Datos de seguridad en EE.UU. solo de fases 1 y 2."]}},{"id":87,"n":"Mecasermin","al":"","ar":"hormonas","ca":"fda","cl":"IGF-1 (recombinant)","ev":"fda","u":"IGF-1 recombinante utilizado para deficiencia primaria grave de IGF-1 en pacientes pediátricos seleccionados; no es una terapia de rendimiento.","c":"IGF-1 humano recombinante.","m":"Increlex · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/mecasermin","ci":["https://doi.org/10.1210/jc.2006-1610","https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/021839s033lbl.pdf"],"x":{"r":"Mecasermin (Increlex) es IGF-1 humano recombinante. Se usa en niños que no pueden fabricar IGF-1 o no responden a la hormona de crecimiento. Aporta directamente la señal de crecimiento que la GH normalmente generaría.","q":"IGF-1 recombinante idéntico al natural.","m":"Se une al receptor de IGF-1 en todo el cuerpo y entrega la señal de crecimiento que normalmente sigue a la acción de la GH. En la deficiencia primaria severa de IGF-1 hay GH, pero el cuerpo no produce IGF-1 en respuesta; reemplazarlo restaura el crecimiento. Como el IGF-1 comparte acciones con la insulina, puede bajar la glucosa.","mp":["Se une al receptor de IGF-1.","Evita el paso que falla (GH → IGF-1).","Estimula el crecimiento óseo.","Efecto tipo insulina → riesgo de hipoglucemia."],"f":"Aprobado en 2005 para falla de crecimiento por deficiencia primaria severa de IGF-1 o deleción del gen de GH con anticuerpos.","e":[["Estudio pivotal","Niños con insensibilidad a GH","Velocidad de crecimiento de 2.8 a 8.0 cm/año en el primer año"]],"en":"Aprobado.","s":["Hipoglucemia","Cambios de grasa en el sitio","Agrandamiento de amígdalas y adenoides"],"sg":["Hipertensión intracraneal.","Deslizamiento de la epífisis femoral y empeoramiento de escoliosis.","Se han reportado cánceres en niños tratados.","Contraindicado con epífisis cerradas o cáncer."]}},{"id":88,"n":"Mechano growth factor","al":"","ar":"huesos","ca":"wellness","cl":"IGF-1 splice variant","ev":"baja","u":"Variante relacionada con IGF-1 investigada en músculo y reparación tisular; no hay utilidad clínica establecida como producto de recuperación.","c":"Variante de IGF-1 producida por el músculo (MGF/PEG-MGF).","m":"Inyectable (químico de investigación)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/mechano-growth-factor","ci":["https://doi.org/10.1016/j.mad.2011.02.007","https://pubmed.ncbi.nlm.nih.gov/18837392/","https://pubmed.ncbi.nlm.nih.gov/21354439/","https://pubmed.ncbi.nlm.nih.gov/12562960/"],"x":{"r":"El factor de crecimiento mecánico (MGF) es una variante de IGF-1 que fabrica el músculo. Se vende como químico de investigación, a menudo pegilado (PEG-MGF). La evidencia humana más fuerte es observacional y no hay ensayos controlados.","q":"Variante de empalme de IGF-1; también PEG-MGF.","m":"Se propone que activa las células madre del músculo (células satélite), las ayuda a multiplicarse y retrasa su envejecimiento, lo que apoyaría la reparación y el crecimiento. Esto se atribuye a su cola única, distinta del IGF-1 clásico. La forma pegilada del mercado no se ha caracterizado como fármaco.","mp":["Activa células satélite (cultivos).","Más proliferación y fusión celular.","Retrasa senescencia en células jóvenes."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Cultivos de células musculares humanas","Laboratorio","Más activación y fusión de células satélite"],["Kandalla","Células de donantes de distintas edades","Retrasó senescencia en células jóvenes, no en viejas"],["Biopsia 2003","8 hombres de 25–36 y 7 de 70–82","El ejercicio subió MGF propio en jóvenes, no en mayores (no se dio MGF)"]],"en":"Evidencia baja.","s":["Sin datos humanos."],"sg":["Producto del mercado gris sin caracterizar."]}},{"id":89,"n":"Melanotan I","al":"","ar":"piel","ca":"wellness","cl":"MC1R agonist","ev":"baja","u":"Nombre utilizado para compuestos relacionados con pigmentación; no debe confundirse un producto no aprobado con la formulación aprobada de afamelanotide.","c":"Activa receptor de pigmento MC1R (mismo concepto que afamelanotide).","m":"Inyectable no regulado","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/melanotan-i","ci":["https://pubmed.ncbi.nlm.nih.gov/16763547/","https://pubmed.ncbi.nlm.nih.gov/26132941/","https://doi.org/10.1016/j.jpba.2012.11.040"],"x":{"r":"Melanotan I es un péptido que oscurece la piel activando un receptor de pigmento. Se vende en el mercado gris como 'péptido bronceador'. La misma molécula, como afamelanotide (Scenesse), está aprobada para una enfermedad rara. Ningún ensayo respalda su uso para broncearse.","q":"Agonista MC1R; misma molécula que afamelanotide.","m":"Activa el receptor MC1R de los melanocitos y aumenta la eumelanina, el pigmento oscuro, sin necesidad de radiación UV. En un estudio controlado con 65 voluntarios de piel clara, la densidad de melanina subió en promedio 41% en piel que se quema fácil.","mp":["Activa MC1R.","Más eumelanina.","Piel más oscura sin UV."],"f":"Como bronceador: no aprobado y no regulado. Como afamelanotide (implante): aprobado solo para EPP.","e":[["Estudio controlado","65 voluntarios de piel clara","Melanina +41% en piel que se quema fácil"],["Ensayos de Scenesse","168 adultos con EPP","Más horas sin dolor al sol (uso médico, no cosmético)"]],"en":"Evidencia baja para bronceado cosmético.","s":["Náusea","Rubor","Dolor de cabeza"],"sg":["Oscurecimiento de lunares: dificulta vigilar melanoma.","Viales del mercado gris de calidad desconocida."]}},{"id":90,"n":"Melanotan II","al":"","ar":"piel","ca":"wellness","cl":"Melanocortin agonist (MC1R/MC3R/MC4R)","ev":"baja","u":"Agonista experimental de melanocortina promovido para bronceado y función sexual; presenta riesgos y no tiene indicación aprobada por FDA.","c":"Agonista melanocortina no selectivo.","m":"Inyectable no regulado","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/melanotan-ii","ci":["https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://doi.org/10.1001/archdermatol.2008.623","https://doi.org/10.1111/j.1365-2133.2009.09362.x","https://pubmed.ncbi.nlm.nih.gov/8637402/","https://pubmed.ncbi.nlm.nih.gov/24355990/"],"x":{"r":"Melanotan II es un péptido de melanocortina no selectivo que se vende en el mercado gris para broncearse y para la libido. No hay ensayos controlados. Los reportes de casos describen lunares nuevos o cambiantes, y hay un caso de melanoma en una joven que lo usó con cama de bronceado.","q":"Agonista no selectivo de MC1R/MC3R/MC4R.","m":"Activa MC1R en la piel (pigmentación) y MC4R en el cerebro (excitación sexual y apetito). Por eso tiene efectos en la piel y efectos sexuales. Bremelanotide (Vyleesi) es un derivado suyo.","mp":["MC1R → bronceado.","MC4R → excitación sexual y menos apetito.","Efectos no selectivos y difíciles de controlar."],"f":"No aprobado; producto no regulado.","e":[["Piloto 1996","3 hombres sanos","Pigmentación en 2/3; erecciones espontáneas de 1–5 horas; somnolencia y fatiga"],["Reportes de casos","Usuarios","Lunares nuevos o que cambian; un caso de melanoma"]],"en":"Evidencia baja, con señales de seguridad preocupantes.","s":["Náusea","Rubor","Erecciones espontáneas prolongadas","Somnolencia","Menos apetito"],"sg":["Cambios en lunares y posible enmascaramiento de melanoma.","Priapismo.","Productos sin control de calidad."]}},{"id":91,"n":"MK-677 (ibutamoren)","al":"Ibutamoren","ar":"huesos","ca":"wellness","cl":"Non-peptide ghrelin mimetic","ev":"moderada","u":"Secretagogo oral de GH, no peptídico, investigado en crecimiento y composición corporal; puede alterar glucosa y retención de líquidos.","c":"Mimético oral de ghrelina (no es péptido).","m":"Oral (investigación)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/mk-677-ibutamoren","ci":["https://www.fda.gov/media/94155/download","https://doi.org/10.7326/0003-4819-149-9-200811040-00003","https://doi.org/10.1212/01.wnl.0000335163.88054.e7","https://pubmed.ncbi.nlm.nih.gov/19015485/","https://pubmed.ncbi.nlm.nih.gov/18981485/"],"x":{"r":"MK-677 (ibutamoren) es un fármaco oral, no peptídico, que imita a la ghrelina para subir la hormona de crecimiento. En adultos mayores aumentó la masa magra, pero no la fuerza ni la función, y subió la glucosa. Un ensayo grande en Alzheimer fracasó. Prohibido en el deporte.","q":"Secretagogo de GH oral (molécula pequeña, no péptido).","m":"Activa el receptor de ghrelina y la hipófisis libera GH en pulsos, lo que sube el IGF-1. Su diferencia con los péptidos secretagogos es que funciona por boca.","mp":["Activa receptor de ghrelina.","Pulsos de GH → más IGF-1.","Activo por vía oral."],"f":"No aprobado por la FDA; en investigación. Prohibido en el deporte.","e":[["Nass 2008","65 adultos de 60–81 años, 2 años","Masa libre de grasa +1.1 kg vs −0.5 kg (p<0.001); sin mejoría de fuerza; glucosa +5 mg/dL"],["Sevigny 2008","563 personas con Alzheimer leve a moderado, 12 meses","Subió IGF-1 sin diferencia en ninguna escala clínica"]],"en":"Evidencia moderada: ensayos humanos reales con resultados mixtos y señales metabólicas.","s":["Más apetito","Aumento de peso","Retención leve de líquido"],"sg":["Glucosa en ayunas más alta y menor sensibilidad a la insulina.","Precaución en prediabetes o diabetes."]}},{"id":92,"n":"Motixafortide","al":"Aphexda","ar":"corazon","ca":"fda","cl":"CXCR4 antagonist peptide","ev":"fda","u":"Antagonista CXCR4 utilizado junto a otros agentes para movilización de células madre en pacientes seleccionados.","c":"Bloquea CXCR4 junto a filgrastim.","m":"Aphexda · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/motixafortide","ci":["https://doi.org/10.1038/s41591-023-02273-z","https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/217159s009lbl.pdf"],"x":{"r":"Motixafortide (Aphexda) es un péptido que bloquea el receptor CXCR4 para sacar células madre de la médula ósea a la sangre, donde se recolectan para un trasplante autólogo en mieloma múltiple. Se usa junto a filgrastim.","q":"Antagonista de CXCR4 para movilizar células madre.","m":"Las células madre de la sangre están ancladas en la médula por la unión entre su receptor CXCR4 y la señal CXCL12 (SDF-1). Motixafortide bloquea CXCR4 con alta afinidad y larga duración, las células se sueltan y salen a la sangre, donde se recogen por aféresis. Con filgrastim el efecto es sinérgico.","mp":["Bloquea CXCR4.","Rompe el anclaje CXCR4–CXCL12.","Células madre salen a la sangre.","Se recolectan por aféresis."],"f":"Aprobado en 2023 junto a filgrastim para movilizar células madre en mieloma múltiple.","e":[["GENESIS (fase 3)","Mieloma múltiple","Muchos más pacientes alcanzaron la meta de CD34+ en ≤2 aféresis vs filgrastim solo"]],"en":"Aprobado con ensayo de fase 3.","s":["Reacción en sitio (dolor, enrojecimiento, picor)","Rubor","Dolor de espalda","Náusea"],"sg":["Reacciones sistémicas o de hipersensibilidad graves: premedicar y vigilar.","Puede movilizar células tumorales: no se usa en leucemia.","Toxicidad embriofetal."]}},{"id":93,"n":"MOTS-c","al":"","ar":"hormonas","ca":"wellness","cl":"Mitochondrial-derived peptide","ev":"baja","u":"Péptido mitocondrial investigado en metabolismo y respuesta al ejercicio. No hay beneficio ni seguridad establecidos para inyecciones de energía, pérdida de peso o longevidad.","c":"Péptido mitocondrial que afecta sensibilidad a insulina.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/mots-c","ci":["https://doi.org/10.3389/fendo.2023.1120533","https://doi.org/10.1016/j.bbagen.2021.130011","https://pubmed.ncbi.nlm.nih.gov/25738459/","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://www.wada-ama.org/sites/default/files/2025-09/2026list_en_final_clean_september_2025.pdf","https://pubmed.ncbi.nlm.nih.gov/33473109/","https://pubmed.ncbi.nlm.nih.gov/35499074/"],"x":{"r":"MOTS-c es un péptido pequeño codificado en la mitocondria, estudiado como 'imitador del ejercicio' para la salud metabólica. No hay ensayos completados que lo administren a personas. En 2026 un comité asesor de la FDA votó de forma no vinculante a favor de permitir su compounding.","q":"Péptido derivado de la mitocondria.","m":"Bajo estrés metabólico entraría al núcleo de la célula e influiría en genes del metabolismo, incluida la vía AMPK que detecta la energía. Así mejoraría el manejo de glucosa del músculo y la sensibilidad a la insulina. Sus niveles bajan con la edad y suben tras ejercicio intenso. En ratones mejoró la capacidad de ejercicio.","mp":["Se traslada al núcleo bajo estrés.","Activa la vía AMPK.","Mejor captación de glucosa muscular.","Más capacidad de ejercicio (ratones)."],"f":"No aprobado. Voto favorable no vinculante de comité asesor (2026) para compounding; verificar decisión final.","e":[["Estudios celulares y en roedores","Laboratorio","Efectos metabólicos y de ejercicio"],["Estudios humanos observacionales","Personas que hacen ejercicio","MOTS-c en sangre sube tras el ejercicio"],["Ensayos de MOTS-c administrado","—","Ninguno completado"]],"en":"Evidencia baja.","s":["No hay datos de seguridad humanos revisados por pares."],"sg":["Seguridad a largo plazo desconocida."]}},{"id":94,"n":"Murepavadin","al":"","ar":"inmune","ca":"ensayos","cl":"Antimicrobial 'protegrin' peptidomimetic","ev":"baja","u":"Antibacteriano experimental dirigido a bacterias gramnegativas; los resultados y seguridad dependen de la vía y del programa de desarrollo.","c":"Ataca una proteína única de Pseudomonas aeruginosa.","m":"IV / inhalado (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/murepavadin","ci":["https://doi.org/10.1080/14787210.2018.1441024","https://doi.org/10.1128/AAC.02355-17"],"x":{"r":"Murepavadin es un peptidomimético antimicrobial experimental que ataca una proteína exclusiva de Pseudomonas aeruginosa. Su programa IV de fase 3 se detuvo por daño renal inesperado y la versión inhalada no prosperó.","q":"Antibiótico peptidomimético específico de Pseudomonas, en investigación.","m":"Ataca a LptD, una proteína de la membrana externa que Pseudomonas necesita para transportar y ensamblar lipopolisacárido. Sin LptD la bacteria no puede construir su membrana externa y muere. En laboratorio funcionó contra cepas multirresistentes, incluso resistentes a colistina.","mp":["Se une a LptD de Pseudomonas.","Bloquea el transporte de lipopolisacárido.","Membrana externa defectuosa → muerte bacteriana."],"f":"No aprobado.","e":[["Fase 1","Voluntarios sanos","Farmacocinética IV y seguridad inicial"],["PRISM (fase 3)","Pacientes con neumonía","Cerrado en 2019 por más lesión renal aguda de lo esperado"]],"en":"Evidencia baja: el programa terminó por seguridad.","s":["—"],"sg":["Lesión renal aguda (motivo del cierre)."]}},{"id":95,"n":"Nafarelin","al":"Synarel","ar":"sexual","ca":"fda","cl":"GnRH agonist","ev":"fda","u":"Agonista de GnRH utilizado en endometriosis y pubertad precoz central según etiqueta.","c":"Agonista GnRH en spray nasal.","m":"Synarel · nasal","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/nafarelin","ci":["https://doi.org/10.1056/NEJM198802253180805","https://www.pfizermedical.com/synarel","https://www.pfizermedical.com/synarel/adverse-reactions"],"x":{"r":"Nafarelin (Synarel) es un decapéptido agonista de GnRH en spray nasal. Suprime la hipófisis y las hormonas sexuales. Se usa en endometriosis y pubertad precoz central, y es de los pocos de su clase por vía nasal.","q":"Agonista de GnRH intranasal.","m":"Con dosis repetidas primero estimula la hipófisis y luego, por exposición continua, desensibiliza sus receptores. La LH y la FSH bajan y el estrógeno de los ovarios cae a un estado parecido a la menopausia, reversible. Sin estrógeno, las lesiones de endometriosis se encogen y el dolor mejora. En pubertad precoz, dosis más altas frenan la señal hormonal prematura.","mp":["Estímulo inicial de la hipófisis.","Desensibilización por exposición continua.","Estrógeno bajo (estado menopáusico reversible).","Lesiones de endometriosis se reducen."],"f":"Aprobado en 1990 para endometriosis; luego para pubertad precoz central.","e":[["Ensayo multicéntrico doble ciego","Endometriosis vs danazol","Reducción similar de lesiones, sin los efectos de danazol en lípidos"]],"en":"Aprobado con ensayos controlados.","s":["Sofocos y sudoración","Sequedad vaginal y menos libido","Dolor de cabeza","Irritación nasal","Acné y cambios de ánimo"],"sg":["Pérdida ósea: limita el tratamiento de endometriosis a ~6 meses.","Contraindicado en embarazo.","Cambios de ánimo y conducta.","Convulsiones.","Pseudotumor cerebri en niños."]}},{"id":96,"n":"Nangibotide","al":"","ar":"inmune","ca":"ensayos","cl":"TREM-1 inhibitor peptide","ev":"baja","u":"Péptido inhibidor de TREM-1 investigado para modular inflamación en sepsis y otras condiciones graves.","c":"Inhibe el receptor inflamatorio TREM-1.","m":"IV (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/nangibotide","ci":["https://doi.org/10.1016/S2213-2600(23)00158-3"],"x":{"r":"Nangibotide es un péptido experimental que inhibe el receptor inflamatorio TREM-1, desarrollado por Inotrem para choque séptico. Su fase 2b no cumplió su objetivo principal; solo hubo una señal en un subgrupo con biomarcador alto.","q":"Inhibidor de TREM-1 en infusión IV, en investigación.","m":"TREM-1 es un receptor que amplifica la respuesta inflamatoria. En el choque séptico esa amplificación se vuelve dañina. Nangibotide funciona como señuelo que impide que TREM-1 se active, para frenar la liberación excesiva de señales inflamatorias. El TREM-1 soluble en sangre identifica a los pacientes con la vía más activa.","mp":["Actúa como señuelo de TREM-1.","Menos amplificación inflamatoria.","Selección por TREM-1 soluble."],"f":"No aprobado.","e":[["ASTONISH (fase 2b)","Choque séptico","Sin mejoría significativa del puntaje de falla orgánica (global ni en el grupo preespecificado)"],["Subgrupo con biomarcador muy alto","Análisis exploratorio","Mejoría clínicamente relevante, sin confirmar"]],"en":"Evidencia baja.","s":["—"],"sg":[]}},{"id":97,"n":"Nesiritide","al":"","ar":"corazon","ca":"fda","cl":"Natriuretic peptide","ev":"fda","u":"Péptido natriurético utilizado en determinados contextos de insuficiencia cardiaca aguda; no debe asumirse beneficio en supervivencia.","c":"Copia del péptido natriurético tipo B (BNP).","m":"Natrecor · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/nesiritide","ci":["https://doi.org/10.1056/NEJMoa1100171"],"x":{"r":"Nesiritide (Natrecor) es una copia del péptido natriurético tipo B (BNP), la hormona que libera el corazón cuando está sobrecargado. Se usaba IV en insuficiencia cardíaca aguda. Baja las presiones de llenado, pero un ensayo grande no mostró beneficio en mortalidad ni rehospitalización y hoy está prácticamente fuera del mercado.","q":"BNP recombinante, vasodilatador IV.","m":"Se une al receptor de péptido natriurético A y sube el GMP cíclico en los vasos. Relaja arterias y venas, lo que baja la presión contra la que bombea el corazón y la de llenado. Además hace que el riñón elimine sodio y agua y frena el sistema renina-angiotensina-aldosterona.","mp":["Receptor NPR-A → GMPc.","Vasodilatación arterial y venosa.","Más eliminación de sodio y agua.","Menos actividad renina-angiotensina-aldosterona."],"f":"Aprobado en 2001; prácticamente retirado del mercado de EE.UU.","e":[["VMAC","Insuficiencia cardíaca aguda","Bajó presión de llenado más que nitroglicerina o placebo; mejor respiración a 3 h"],["ASCEND-HF","Ensayo grande posterior","Sin beneficio en muerte o rehospitalización a 30 días; más hipotensión"]],"en":"Aprobado, pero sin beneficio en desenlaces duros.","s":["Hipotensión","Dolor de cabeza","Náusea"],"sg":["Hipotensión significativa.","Bradicardia."]}},{"id":98,"n":"NNZ-2591","al":"","ar":"cerebro","ca":"ensayos","cl":"IGF-1-related peptide","ev":"baja","u":"Análogo experimental de un péptido relacionado con IGF-1 estudiado en trastornos del neurodesarrollo.","c":"Péptido oral relacionado a un fragmento de IGF-1.","m":"Oral (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/nnz-2591","ci":["https://doi.org/10.1212/NXG.0000000000200338","https://doi.org/10.1212/NXG.0000000000200405"],"x":{"r":"NNZ-2591 es un péptido oral experimental de Neuren, relacionado con un fragmento natural de IGF-1. Se estudia en trastornos genéticos raros del neurodesarrollo como Phelan-McDermid, Rett y Angelman. Solo hay un ensayo de fase 2 sin grupo placebo; hay una fase 3 en curso.","q":"Análogo de ciclo-glicina-prolina, en investigación.","m":"Como análogo de la ciclo-glicina-prolina, modularía el sistema de IGF-1 y ayudaría a normalizar la disponibilidad de IGF-1, que apoya la formación y función de las conexiones entre neuronas. La idea es corregir circuitos cerebrales afectados en estos trastornos.","mp":["Modula el sistema IGF-1.","Normaliza disponibilidad de IGF-1.","Apoya conexiones neuronales."],"f":"No aprobado.","e":[["Fase 2 abierta","Niños y adolescentes con Phelan-McDermid, 13 semanas","Bien tolerado; mejoría en la mayoría de medidas (sin placebo)"],["Rett, Angelman, Pitt-Hopkins","Comunicados de la compañía","Datos preliminares"]],"en":"Evidencia baja: prometedor, pero sin control.","s":["Bien tolerado en fase 2"],"sg":[]}},{"id":99,"n":"Nonapeptide-1","al":"","ar":"piel","ca":"cosmetico","cl":"Brightening peptide","ev":"baja","u":"Péptido cosmético estudiado para modular pigmentación y mejorar apariencia de manchas; no equivale a un tratamiento médico de toda hiperpigmentación.","c":"Bloquea la señal que activa la producción de melanina.","m":"Melanostatine · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/nonapeptide-1","ci":["https://doi.org/10.5114/ada.2022.115890"],"x":{"r":"El nonapéptido-1 (Melanostatine) es un péptido de nueve aminoácidos usado en cosméticos para aclarar manchas. En laboratorio bloquea la señal hormonal que ordena a los melanocitos fabricar melanina. No hay ensayos humanos publicados del ingrediente.","q":"Péptido cosmético aclarante (antagonista de MC1R).","m":"Los melanocitos fabrican más melanina cuando la hormona α-MSH se une a su receptor MC1R. El nonapéptido-1 compite con la α-MSH por ese receptor y apaga la señal que activa las enzimas productoras de pigmento. Su idea es más de prevención que de corrección: limita manchas nuevas en vez de borrar las existentes.","mp":["Compite con α-MSH por MC1R.","Menos activación de enzimas del pigmento.","Menos melanina nueva."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Estudio celular","Laboratorio","Usado como bloqueador de α-MSH de referencia; reduce melanina"]],"en":"Evidencia baja.","s":["Bien tolerado; no irritante"],"sg":[]}},{"id":100,"n":"Octreotide","al":"","ar":"digestivo","ca":"fda","cl":"Somatostatin analog","ev":"fda","u":"Análogo de somatostatina utilizado en acromegalia y control de síntomas de ciertos tumores neuroendocrinos; existen usos especializados adicionales.","c":"Análogo de somatostatina.","m":"Sandostatin (SC/IV), LAR (IM), Mycapssa (oral)","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/octreotide","ci":["https://doi.org/10.1200/JCO.2009.22.8510","https://www.novartis.com/us-en/sites/novartis_us/files/sandostatin_inj.pdf"],"x":{"r":"Octreotide (Sandostatin, Sandostatin LAR, Mycapssa) es un análogo sintético de somatostatina. Suprime la hormona de crecimiento y varias hormonas intestinales. Se usa en acromegalia y para controlar síntomas de tumores secretores de hormonas, como el síndrome carcinoide.","q":"Análogo de somatostatina en inyección corta, depósito mensual u oral.","m":"Se une sobre todo al receptor de somatostatina tipo 2. Así frena la liberación de GH e IGF-1 y de hormonas intestinales como serotonina, VIP y gastrina. Además tiene efecto antiproliferativo en algunos tumores neuroendocrinos.","mp":["Receptor SSTR2.","Baja GH/IGF-1 (acromegalia).","Baja serotonina (síndrome carcinoide: menos rubor y diarrea).","Baja VIP (VIPoma: menos diarrea secretora)."],"f":"Aprobado en 1988 (inyección), LAR una década después y Mycapssa oral en 2020.","e":[["PROMID","Tumores neuroendocrinos de intestino medio metastásicos","Mediana hasta progresión 14.3 vs 6.0 meses con placebo"]],"en":"Aprobado con ensayos aleatorizados.","s":["Diarrea, dolor abdominal, náusea, gases","Dolor en sitio de inyección","Cálculos o barro biliar","Glucosa alta o baja"],"sg":["Enfermedad de vesícula a largo plazo.","Cambios en glucosa y tiroides.","Bradicardia y efectos de conducción."]}},{"id":101,"n":"Oligopeptide-1","al":"","ar":"piel","ca":"cosmetico","cl":"Growth-factor peptide","ev":"moderada","u":"Nombre cosmético relacionado con factor de crecimiento epidérmico; los resultados dependen de la formulación y no validan inyecciones cosméticas.","c":"EGF humano: estimula crecimiento y reparación de la piel.","m":"Tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/oligopeptide-1","ci":["https://doi.org/10.1111/jocd.70927","https://doi.org/10.1111/jocd.12977"],"x":{"r":"El oligopéptido-1 es el nombre cosmético del factor de crecimiento epidérmico humano (EGF), una proteína de 53 aminoácidos. Se usa en productos de renovación de piel y recuperación tras procedimientos. Hay estudios humanos pequeños con mejoría de textura y firmeza.","q":"EGF recombinante para cosméticos.","m":"Se une al receptor de EGF en las células de la piel y activa la misma cascada que se usa al cicatrizar una herida: queratinocitos y fibroblastos se multiplican, migran y se renuevan, y se produce más colágeno y elastina. La gran duda es cuánto atraviesa la piel intacta, porque es una proteína grande.","mp":["Se une al receptor de EGF.","Activa proliferación y migración celular.","Más colágeno y elastina.","Limitación: penetración en piel intacta."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Piloto aleatorizado","Suero EGF vs otro suero EGF","Mejor textura y firmeza según investigadores; arrugas con cambio mínimo"]],"en":"Evidencia moderada: estudios reales pero pequeños y a menudo de la industria.","s":["Bien tolerado"],"sg":["Precaución en piel lesionada o con antecedentes personales de cáncer de piel (estimula crecimiento celular)."]}},{"id":102,"n":"Oxytocin","al":"","ar":"sexual","ca":"fda","cl":"Oxytocin receptor agonist","ev":"fda","u":"Hormona utilizada en obstetricia para indicaciones específicas de contracción uterina; no está validada como terapia general de vínculo o bienestar.","c":"Hormona que contrae el útero.","m":"Pitocin · IV/IM","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/oxytocin","ci":["https://doi.org/10.1002/14651858.CD009701.pub2","https://www.drugs.com/pro/pitocin.html","https://doi.org/10.1152/physrev.2001.81.2.629","https://doi.org/10.3389/fnbeh.2014.00031","https://doi.org/10.9758/cpn.2019.17.1.1","https://doi.org/10.1016/j.psyneuen.2014.07.014","https://doi.org/10.1038/npp.2016.1","https://doi.org/10.1016/j.biopsych.2016.11.012"],"x":{"r":"La oxitocina (Pitocin) es una hormona de nueve aminoácidos que contrae el útero. Se usa para iniciar o reforzar el parto y para controlar el sangrado después del parto. Fue la primera hormona peptídica sintetizada químicamente, trabajo que ganó un Premio Nobel.","q":"Uterotónico en infusión IV controlada.","m":"Se une a receptores del músculo uterino, sube el calcio dentro de la célula y aumenta la fuerza y frecuencia de las contracciones. El útero se vuelve mucho más sensible a la oxitocina al final del embarazo. También contrae las células alrededor de las glándulas mamarias para la bajada de leche.","mp":["Receptor de oxitocina uterino.","Más calcio intracelular → contracciones más fuertes.","Útero vacío se contrae → menos sangrado posparto.","Bajada de la leche."],"f":"Aprobada; advertencia en recuadro: no indicada para inducción electiva sin razón médica.","e":[["Ensayos comparativos de dosis","Inducción de parto","Dosis más altas aumentan hiperestimulación sin acortar claramente el parto"]],"en":"Aprobada y de uso establecido. Los sprays nasales 'sociales' no están aprobados.","s":["Náusea","Contracciones más rápidas o fuertes","Cambios de presión o frecuencia cardíaca"],"sg":["Hiperestimulación uterina: sufrimiento fetal o, raramente, ruptura uterina.","Intoxicación hídrica e hiponatremia con infusión prolongada a dosis alta."]}},{"id":103,"n":"Palmitoyl hexapeptide-12","al":"","ar":"piel","ca":"cosmetico","cl":"Signal peptide","ev":"baja","u":"Ingrediente cosmético estudiado para apariencia y elasticidad cutánea; la evidencia clínica es limitada.","c":"Péptido señal basado en elastina.","m":"Biopeptide CL · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/palmitoyl-hexapeptide-12","ci":["https://doi.org/10.1021/acsabm.4c01816","https://doi.org/10.1016/j.crtox.2026.100291"],"x":{"r":"El palmitoil hexapéptido-12 (Biopeptide CL) es un péptido 'señal' unido a un ácido graso, basado en un fragmento de elastina. Se usa para firmeza y elasticidad. Solo hay estudios de mecanismo y seguridad en humanos, no de resultados visibles.","q":"Matriquina derivada de elastina.","m":"En células estimula a los fibroblastos a producir elastina, glicosaminoglicanos y colágeno, y baja la interleucina-6. En piel humana de laboratorio se autoensambla, penetra las capas externas y ayuda a reparar una barrera dañada. Ojo: los fragmentos de elastina pueden ser proinflamatorios a ciertos niveles.","mp":["Más elastina y colágeno (células).","Menos IL-6.","Refuerza la barrera cutánea (ex vivo)."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Piel humana ex vivo","Mecanismo","Penetra y ayuda a reparar barrera"],["Análisis de seguridad","Bioinformático","Sin alertas de toxicidad ni alergia"]],"en":"Evidencia baja: ningún estudio de eficacia visible.","s":["Baja irritación"],"sg":[]}},{"id":104,"n":"Palmitoyl pentapeptide-4","al":"","ar":"piel","ca":"cosmetico","cl":"Signal (collagen) peptide","ev":"moderada","u":"Péptido cosmético tópico estudiado para apariencia de arrugas y matriz de la piel; el beneficio depende del producto.","c":"Fragmento de colágeno tipo I (KTTKS) con ácido graso.","m":"Matrixyl · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/palmitoyl-pentapeptide-4","ci":["https://doi.org/10.1111/j.1467-2494.2005.00261.x","https://pubmed.ncbi.nlm.nih.gov/8486721/","https://www.specialchem.com/cosmetics/inci-ingredients/palmitoyl-pentapeptide-4","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/fda-authority-over-cosmetics-how-cosmetics-are-not-fda-approved-are-fda-regulated","https://www.fda.gov/cosmetics/cosmetics-laws-regulations/it-cosmetic-drug-or-both-or-it-soap"],"x":{"r":"El palmitoil pentapéptido-4 (Matrixyl) es un fragmento de colágeno tipo I (KTTKS) unido a ácido palmítico para usarse en la piel. Un ensayo doble ciego de 2005 mostró mejoría de líneas finas en 12 semanas. Es de los péptidos cosméticos con más evidencia.","q":"Matriquina de colágeno (pal-KTTKS).","m":"KTTKS es un fragmento que se libera cuando el colágeno tipo I se procesa en la piel. Funciona como señal de retroalimentación: 'aquí se rompió colágeno, fabriquen más'. En laboratorio estimula a los fibroblastos a producir colágeno I, colágeno III y fibronectina. El ácido palmítico mejora su paso por la piel.","mp":["Imita un fragmento del colágeno roto.","Fibroblastos producen colágeno I y III y fibronectina.","Ácido graso mejora la penetración."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Ensayo doble ciego 2005","93 mujeres de 35–55 años, 12 semanas, 3 ppm","Mejoría significativa de líneas finas y arrugas vs placebo"],["Laboratorio","Fibroblastos","KTTKS estimula producción de colágeno"]],"en":"Evidencia moderada: ensayo real pero pequeño y de la industria (P&G).","s":["Bien tolerado","Enrojecimiento o irritación leve (raro)"],"sg":[]}},{"id":105,"n":"Palmitoyl tetrapeptide-7","al":"","ar":"piel","ca":"cosmetico","cl":"Signal / anti-inflammatory peptide","ev":"baja","u":"Ingrediente cosmético utilizado en formulaciones para mejorar apariencia de piel; los estudios de mezclas no aíslan siempre su efecto.","c":"Péptido señal que calma mediadores inflamatorios (IL-6).","m":"Rigin · parte de Matrixyl 3000","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/palmitoyl-tetrapeptide-7","ci":["https://doi.org/10.1111/jocd.15849","https://doi.org/10.1111/ics.12770"],"x":{"r":"El palmitoil tetrapéptido-7 (Rigin) es un péptido 'señal' que forma la segunda mitad de Matrixyl 3000. En laboratorio calma señales inflamatorias de la piel. No hay ensayo humano independiente del ingrediente solo.","q":"Péptido señal antiinflamatorio cosmético.","m":"En células baja la interleucina-6, un mensajero inflamatorio. La lógica es que la inflamación crónica de bajo grado ('inflammaging') activa las enzimas que rompen el colágeno; calmarla ayudaría a conservar la firmeza.","mp":["Baja IL-6.","Menos 'inflammaging'.","Menos degradación de colágeno (propuesto)."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Suero multipéptido","Humanos","Efecto no separable de otros ingredientes"],["Paneles del fabricante","Voluntarios","Datos de uso no independientes"]],"en":"Evidencia baja.","s":["Bien tolerado; baja irritación"],"sg":[]}},{"id":106,"n":"Palmitoyl tripeptide-1","al":"","ar":"piel","ca":"cosmetico","cl":"Signal peptide","ev":"baja","u":"Péptido cosmético investigado en señalización de matriz cutánea; no demuestra por sí solo un efecto clínico de rejuvenecimiento.","c":"Péptido señal de colágeno.","m":"Parte de Matrixyl 3000 · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/palmitoyl-tripeptide-1","ci":["https://doi.org/10.1111/jocd.15849","https://doi.org/10.1111/ics.12770"],"x":{"r":"El palmitoil tripéptido-1 es un péptido 'señal' basado en un fragmento de colágeno y es la otra mitad de Matrixyl 3000. En laboratorio estimula colágeno. No hay ensayo humano independiente del ingrediente solo.","q":"Matriquina de colágeno (pal-GHK).","m":"En células estimula a los fibroblastos de la dermis a producir colágeno I y III y fibronectina. El ácido graso unido mejora su penetración.","mp":["Señal de reconstrucción de matriz.","Más colágeno I/III y fibronectina (células)."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Suero multipéptido de ojos","Humanos","Beneficios de apariencia, no atribuibles solo a este péptido"]],"en":"Evidencia baja.","s":["Bien tolerado"],"sg":[]}},{"id":107,"n":"Palmitoyl tripeptide-38","al":"","ar":"piel","ca":"cosmetico","cl":"Signal peptide","ev":"baja","u":"Ingrediente cosmético estudiado para apariencia de líneas y textura cutánea; los datos dependen de la formulación.","c":"Estimula varios componentes de la matriz de la piel.","m":"Matrixyl synthe'6 · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/palmitoyl-tripeptide-38","ci":["https://doi.org/10.1111/jocd.13770"],"x":{"r":"El palmitoil tripéptido-38 (Matrixyl synthe'6) busca que la piel fabrique seis componentes de matriz a la vez. El único estudio humano fue abierto y combinado con vitaminas C y E, así que no aísla el efecto del péptido.","q":"Péptido señal cosmético de matriz múltiple.","m":"Según el fabricante estimula seis componentes: colágeno I, III y IV, fibronectina, ácido hialurónico y laminina. Juntos dan estructura y amortiguación a la piel. La afirmación de 'seis componentes' viene de estudios del propio fabricante.","mp":["Colágeno I, III y IV.","Fibronectina.","Ácido hialurónico.","Laminina."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Estudio abierto","Suero con péptido + vitamina C alta + vitamina E, ~2 meses","Menos aspereza y mejor tono; sin grupo control"]],"en":"Evidencia baja.","s":["Bien tolerado"],"sg":[]}},{"id":108,"n":"Palopegteriparatide","al":"Yorvipath","ar":"huesos","ca":"fda","cl":"Long-acting PTH prodrug","ev":"fda","u":"Terapia de reemplazo de PTH utilizada en adultos con hipoparatiroidismo; requiere control de calcio y seguimiento específico.","c":"Prodroga de PTH que libera hormona estable 24 h.","m":"Yorvipath · SC diario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/palopegteriparatide","ci":["https://doi.org/10.1002/jbmr.4726","https://ascendispharma.us/products/pi/yorvipath/yorvipath_pi.pdf"],"x":{"r":"Palopegteriparatide (Yorvipath) es una forma de larga acción de la hormona paratiroidea que libera la hormona de forma estable durante 24 horas. Trata el hipoparatiroidismo en adultos e imita mejor los niveles naturales que productos anteriores.","q":"Prodroga de PTH(1-34) de liberación sostenida.","m":"Se inyecta inactiva y va liberando PTH(1-34) activa de forma gradual, con niveles estables en 24 horas en lugar de un pico y una caída. La hormona se une al receptor PTH-1 y restablece el calcio a través del riñón, la activación de vitamina D y el hueso.","mp":["Prodroga inactiva → libera PTH(1-34) poco a poco.","Receptor PTH-1.","Riñón retiene calcio y activa vitamina D.","Calcio normal con menos suplementos."],"f":"Aprobado en 2024 para hipoparatiroidismo en adultos. Advertencia por riesgo potencial de osteosarcoma (ratas).","e":[["PaTHway (fase 3)","Adultos con hipoparatiroidismo, 26 semanas","Mayoría con calcio normal sin necesidad de calcio y vitamina D activa convencionales"]],"en":"Aprobado con ensayo de fase 3.","s":["Reacción en sitio","Rubor, mareo o hipotensión al pararse","Dolor de cabeza","Dolor de espalda","Diarrea","Calcio alto","Dolor de garganta"],"sg":["Riesgo potencial de osteosarcoma.","Calcio alto o bajo al ajustar dosis.","Hipersensibilidad."]}},{"id":109,"n":"Parathyroid hormone","al":"Natpara","ar":"huesos","ca":"fda","cl":"PTH (recombinant)","ev":"fda","u":"Hormona paratiroidea utilizada en productos e indicaciones endocrinas específicas; disponibilidad y formulación deben verificarse.","c":"PTH recombinante completa (1-84).","m":"Natpara · SC (descontinuado)","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/parathyroid-hormone","ci":["https://doi.org/10.1016/S2213-8587(13)70106-2"],"x":{"r":"La hormona paratiroidea completa recombinante, rhPTH(1-84) (Natpara), es un reemplazo hormonal para hipoparatiroidismo. Tiene advertencia en recuadro por osteosarcoma en ratas y su disponibilidad en EE.UU. está limitada porque el fabricante la está descontinuando.","q":"PTH humana completa (84 aminoácidos).","m":"Se une al receptor PTH-1 y sube el calcio por tres vías: el riñón reabsorbe más calcio, el riñón activa más vitamina D (que aumenta la absorción intestinal) y el hueso libera calcio. Es un control fisiológico que los suplementos solos no logran.","mp":["Riñón reabsorbe calcio.","Activa vitamina D → más absorción intestinal.","Moviliza calcio del hueso."],"f":"Aprobada en 2015; programa restringido; retiro voluntario en 2019 y descontinuación en curso.","e":[["REPLACE","Hipoparatiroidismo","Mayoría redujo ≥50% el calcio y vitamina D activa con calcio estable, vs casi nadie con placebo"]],"en":"Aprobada.","s":["Hormigueo","Calcio alto o bajo","Dolor de cabeza y náusea","Más calcio en orina"],"sg":["Advertencia de osteosarcoma (ratas).","Cambios bruscos de calcio al iniciar, cambiar o interrumpir."]}},{"id":110,"n":"Pasireotide","al":"Signifor","ar":"hormonas","ca":"fda","cl":"Somatostatin analog","ev":"fda","u":"Análogo de somatostatina utilizado en enfermedad de Cushing o acromegalia según formulación; puede producir hiperglucemia.","c":"Análogo de somatostatina de receptores amplios.","m":"Signifor (SC), Signifor LAR (IM)","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/pasireotide","ci":["https://doi.org/10.1056/NEJMoa1105743","https://www.recordatirarediseases.com/sites/www.recordatirarediseases.com/files/inline-files/SIGNIFOR_Prescribing_Information.pdf"],"x":{"r":"Pasireotide (Signifor, Signifor LAR) es un análogo de somatostatina que se une a más subtipos de receptor que los anteriores. Por eso sirve en enfermedad de Cushing además de acromegalia. Su efecto secundario más notable es la glucosa alta.","q":"Análogo de somatostatina multirreceptor.","m":"Se une a varios receptores de somatostatina, sobre todo al subtipo 5, que abunda en los tumores hipofisarios que causan Cushing. Así frena la ACTH del tumor y baja el cortisol. En acromegalia suprime la GH y el IGF-1. Como también reduce la secreción de insulina, sube la glucosa más que otros de su clase.","mp":["Receptores de somatostatina, sobre todo SSTR5.","Menos ACTH → menos cortisol (Cushing).","Menos GH/IGF-1 (acromegalia).","Menos insulina → glucosa alta."],"f":"Signifor (2012) para Cushing; Signifor LAR (2014) para acromegalia y luego Cushing.","e":[["Fase 3 de 12 meses","Enfermedad de Cushing","Redujo y en algunos normalizó el cortisol libre urinario; mayor efecto a dosis alta"]],"en":"Aprobado con ensayos de fase 3.","s":["Glucosa alta y diabetes nueva","Diarrea y náusea","Cálculos biliares","Dolor de cabeza, dolor abdominal, fatiga"],"sg":["Hiperglucemia significativa: monitorear glucosa.","Bradicardia y prolongación del QT.","Enzimas hepáticas elevadas.","Cortisol demasiado bajo."]}},{"id":111,"n":"Pegcetacoplan","al":"","ar":"corazon","ca":"fda","cl":"Complement C3 inhibitor (PEG peptide)","ev":"fda","u":"Inhibidor de complemento C3 con usos hematológicos u oftálmicos específicos según producto y vía; las formulaciones no son intercambiables.","c":"Bloquea la proteína C3 del complemento.","m":"Empaveli SC / Syfovre intravítreo","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/pegcetacoplan","ci":["https://doi.org/10.1056/NEJMoa2029073","https://pi.apellis.com/files/PI_Empaveli.pdf"],"x":{"r":"Pegcetacoplan bloquea la proteína C3 del complemento. Se vende como Empaveli para hemoglobinuria paroxística nocturna (HPN) y dos enfermedades renales raras, y como Syfovre, inyección ocular para atrofia geográfica.","q":"Péptido pegilado inhibidor de C3.","m":"C3 es el centro de la cascada del complemento. Pegcetacoplan se une a C3 y bloquea su activación y los pasos siguientes que destruyen células. En la HPN los glóbulos rojos no tienen proteínas protectoras y se destruyen dentro de los vasos y en su superficie por C3. Al actuar en C3 controla ambas vías, más que los fármacos que bloquean solo C5. En el ojo, frenar el complemento busca enlentecer la pérdida de células de la retina.","mp":["Se une a C3.","Bloquea la cascada desde su centro.","HPN: protege glóbulos rojos dentro y fuera de los vasos.","Ojo: enlentece la atrofia geográfica."],"f":"Empaveli (2021, HPN; 2025, glomerulopatía C3 e IC-MPGN) y Syfovre (2023, atrofia geográfica).","e":[["PEGASUS","HPN","Superior a eculizumab (inhibidor C5) en hemoglobina a 16 semanas"],["Programas de atrofia geográfica","Degeneración macular","Enlentecimiento del crecimiento de lesiones"]],"en":"Aprobado con ensayos aleatorizados.","s":["Empaveli: reacción en sitio, infecciones, diarrea, dolor abdominal","Syfovre: molestia ocular, moscas volantes, sangrado superficial del ojo"],"sg":["Empaveli: infecciones graves por bacterias encapsuladas (meningococo); vacunas y programa REMS; hemólisis al suspender.","Syfovre: endoftalmitis, desprendimiento de retina, vasculitis retiniana, conversión a DMAE húmeda."]}},{"id":112,"n":"Pegvisomant","al":"","ar":"hormonas","ca":"fda","cl":"GH receptor antagonist","ev":"fda","u":"Antagonista del receptor de GH utilizado para acromegalia; bloquea la acción de GH en lugar de estimularla.","c":"Bloquea el receptor de hormona de crecimiento.","m":"Somavert · SC diario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/pegvisomant","ci":["https://doi.org/10.1056/NEJM200004203421604","https://labeling.pfizer.com/ShowLabeling.aspx?id=3213"],"x":{"r":"Pegvisomant (Somavert) es una versión modificada y pegilada de la hormona de crecimiento que bloquea su receptor. Se usa en acromegalia cuando otras terapias no bastan y normaliza el IGF-1 en la gran mayoría de los pacientes.","q":"Antagonista del receptor de hormona de crecimiento.","m":"La GH funciona juntando dos subunidades de su receptor. Pegvisomant ocupa el receptor pero, por sus cambios de diseño, impide que se forme la pareja funcional, así que el hígado deja de producir IGF-1. No frena al tumor de la hipófisis: la GH medida sube aunque el IGF-1 se normalice. El PEG alarga su vida media para dosis diaria.","mp":["Ocupa el receptor de GH.","Impide su activación.","El hígado produce menos IGF-1.","La GH medida sube (no actúa sobre el tumor)."],"f":"Aprobado en 2003 para acromegalia.","e":[["Ensayo controlado","Acromegalia","IGF-1 normalizado en ~90% con 20 mg diarios"]],"en":"Aprobado con ensayos controlados.","s":["Reacciones en sitio, incluida lipohipertrofia","Síntomas de resfriado","Dolor","Náusea y diarrea","Síntomas tipo gripe","Pruebas hepáticas anormales"],"sg":["Elevación de enzimas hepáticas; daño hepático raro: vigilar pruebas.","Hipoglucemia en diabéticos: ajustar sus medicamentos.","Vigilar tamaño del tumor."]}},{"id":113,"n":"Pemvidutide","al":"","ar":"digestivo","ca":"ensayos","cl":"GLP-1 / glucagon dual agonist","ev":"moderada","u":"Agonista dual de GLP-1 y glucagón investigado en obesidad y enfermedad hepática metabólica.","c":"Agonista dual GLP-1 / glucagón.","m":"SC semanal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/pemvidutide","ci":["https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1016/S0140-6736(25)02114-2","https://doi.org/10.1016/j.jhepr.2025.101483"],"x":{"r":"Pemvidutide es un agonista dual GLP-1/glucagón experimental de Altimmune, de inyección semanal para hígado graso (MASH) y obesidad. En fase 2 redujo la grasa del hígado y el peso. Aún no hay fase 3 completada.","q":"Agonista dual GLP-1/glucagón, en investigación.","m":"El brazo GLP-1 reduce el apetito y ayuda a bajar de peso. El brazo de glucagón actúa directo en el hígado: quema grasa y reduce su producción. La combinación busca bajar peso y grasa hepática a la vez, clave en MASH.","mp":["GLP-1 → menos apetito.","Glucagón → quema de grasa hepática.","Menos producción de grasa en hígado."],"f":"No aprobado.","e":[["IMPACT (fase 2b)","MASH confirmada por biopsia","Resultados positivos en hígado a 24 semanas"],["Fase 1b/2a","Hígado graso","Gran reducción relativa de grasa hepática y pérdida de peso"],["Fase 2 obesidad","Comunicado de la compañía","Pérdida de peso significativa a dosis alta"]],"en":"Evidencia moderada.","s":["Efectos GI"],"sg":[]}},{"id":114,"n":"Pentapeptide-18","al":"","ar":"piel","ca":"cosmetico","cl":"Neurotransmitter-inhibiting peptide","ev":"baja","u":"Ingrediente cosmético estudiado para líneas de expresión, a menudo en mezclas; no equivale a toxina botulínica.","c":"Imita una encefalina y reduce contracción muscular.","m":"Leuphasyl · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/pentapeptide-18","ci":["https://www.mdpi.com/2079-9284/1/2/75","https://doi.org/10.1016/j.compbiolchem.2026.108952","https://www.specialchem.com/cosmetics/product/lubrizol-leuphasyl-peptide","https://doi.org/10.3390/life14101212"],"x":{"r":"El pentapéptido-18 (Leuphasyl) es un péptido cosmético para líneas de expresión. Imitaría a las encefalinas, un mensajero 'calmante' que reduce la liberación del neurotransmisor que contrae el músculo. Solo se ha probado en humanos dentro de fórmulas combinadas.","q":"Péptido cosmético tipo encefalina.","m":"Actúa un paso antes que Argireline. Se uniría a receptores de encefalina en la terminal nerviosa, lo que reduce la entrada de calcio. Sin calcio se libera menos acetilcolina y los músculos de expresión se contraen menos. Se mercadea en combinación con Argireline porque actúan en puntos distintos de la misma vía.","mp":["Se une a receptores de encefalina.","Menos entrada de calcio al nervio.","Menos acetilcolina liberada.","Menos contracción muscular."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Modelado computacional y laboratorio","—","Interacción con su receptor"],["Fórmulas con retinol","Humanos","Efecto no atribuible solo al péptido"]],"en":"Evidencia baja.","s":["Bien tolerado"],"sg":[]}},{"id":115,"n":"Petrelintide","al":"","ar":"digestivo","ca":"ensayos","cl":"Long-acting amylin analog","ev":"moderada","u":"Análogo de amilina de acción prolongada investigado para obesidad; su eficacia y seguridad se evalúan en ensayos.","c":"Análogo de amilina de larga acción.","m":"SC semanal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/petrelintide","ci":["https://doi.org/10.1016/S2213-8587(26)00213-5"],"x":{"r":"Petrelintide es un análogo de amilina de acción prolongada de Zealand Pharma y Roche, de inyección semanal para control de peso. En fase 2 logró ~11% de pérdida de peso a 42 semanas con tolerancia gastrointestinal parecida al placebo.","q":"Análogo de amilina semanal, en investigación.","m":"Activa los receptores de amilina e imita la señal de saciedad natural. Reduce el apetito, retrasa el vaciado del estómago y baja el glucagón. Al ser una vía distinta a GLP-1 y GIP, se estudia en combinación con ellos.","mp":["Receptor de amilina.","Menos apetito.","Vaciado gástrico más lento.","Menos glucagón."],"f":"No aprobado; fase 3 planificada.","e":[["ZUPREME-1 (fase 2)","Obesidad sin diabetes","≈ −9–10% a 28 semanas; ≈ −11% a 42 semanas; náusea leve"]],"en":"Evidencia moderada.","s":["Náusea leve"],"sg":[]}},{"id":116,"n":"Plecanatide","al":"","ar":"digestivo","ca":"fda","cl":"Guanylate cyclase-C agonist","ev":"fda","u":"Agonista de guanilato ciclasa C utilizado en adultos con estreñimiento crónico o intestino irritable con estreñimiento.","c":"Análogo de uroguanilina: agonista guanilato ciclasa-C.","m":"Trulance · tableta oral","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/plecanatide","ci":["https://doi.org/10.1038/ajg.2016.611","https://drugs.com/pro/trulance.html"],"x":{"r":"Plecanatide (Trulance) es un péptido modelado en la hormona intestinal uroguanilina. Aumenta el líquido intestinal para aliviar el estreñimiento crónico y el IBS-C. Se toma en tableta diaria.","q":"Agonista de guanilato ciclasa-C, análogo de uroguanilina.","m":"Activa la guanilato ciclasa-C del revestimiento intestinal, sube el GMP cíclico y provoca la secreción de cloruro, bicarbonato y agua. Las heces se ablandan y avanzan. Como imita a la uroguanilina, su actividad depende del pH y prefiere el ambiente algo ácido del intestino delgado superior. Casi no se absorbe.","mp":["Activa guanilato ciclasa-C.","Sube GMPc → secreción de agua.","Actividad sensible al pH.","Acción local, mínima absorción."],"f":"Aprobado en 2017 (estreñimiento crónico) y luego IBS-C. Advertencia en recuadro: contraindicado en menores de 6 años; evitar de 6 a 18.","e":[["Fase 3 en estreñimiento crónico","Adultos","Respondedores sostenidos ~21% vs ~10% placebo"]],"en":"Aprobado.","s":["Diarrea (la más frecuente)"],"sg":["Diarrea severa y deshidratación.","Contraindicado en menores de 6 años y en obstrucción intestinal."]}},{"id":117,"n":"PN-943","al":"","ar":"digestivo","ca":"ensayos","cl":"Oral α4β7 integrin antagonist peptide","ev":"baja","u":"Péptido oral antagonista de integrina investigado para colitis ulcerosa; resultados experimentales no constituyen una indicación aprobada.","c":"Bloquea integrina α4β7 por vía oral.","m":"Oral (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/pn-943","ci":["https://doi.org/10.1053/j.gastro.2021.08.045"],"x":{"r":"PN-943 es un péptido oral experimental de Protagonist que bloquea la integrina α4β7, el mismo blanco del anticuerpo vedolizumab, para colitis ulcerosa. Su ensayo controlado inicial no cumplió el objetivo y el programa está inactivo.","q":"Antagonista oral de integrina α4β7, en investigación.","m":"Bloquea la integrina α4β7 de los linfocitos para que no se una a MAdCAM-1 en los vasos del intestino. Esa unión es la forma en que ciertos linfocitos inflamatorios 'llegan' al intestino. Sin ella, habría menos inflamación. Lo novedoso era hacerlo con un péptido oral que actúe en el intestino.","mp":["Bloquea α4β7 en linfocitos.","No se unen a MAdCAM-1 intestinal.","Menos linfocitos llegan al colon."],"f":"No aprobado; programa inactivo.","e":[["Fase 2a (PTG-100)","Colitis ulcerosa, revisado por pares","No cumplió el objetivo primario"],["IDEAL (fase 2)","Comunicado de la compañía","Señal a dosis baja pero no alta (inconsistente)"]],"en":"Evidencia baja.","s":["—"],"sg":[]}},{"id":118,"n":"Polymyxin B / Colistin","al":"","ar":"inmune","ca":"fda","cl":"Polymyxin antibiotic","ev":"fda","u":"Antibióticos peptídicos para determinadas bacterias gramnegativas; productos sistémicos requieren especial atención a toxicidad renal y neurológica.","c":"Antibióticos que rompen la membrana bacteriana.","m":"Polimixina B / colistimetato · IV, inhalado","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/polymyxin-b-colistin","ci":["https://doi.org/10.1016/S1473-3099(18)30099-9","https://drugs.com/pro/polymyxin-b-injection.html"],"x":{"r":"La polimixina B y la colistina (polimixina E) son antibióticos lipopeptídicos cíclicos antiguos que volvieron a usarse como último recurso contra bacterias gram-negativas multirresistentes. Rompen la membrana externa de la bacteria, pero dañan riñones y nervios.","q":"Antibióticos de último recurso para gram-negativos.","m":"Actúan como detergente. Su anillo con carga positiva se une al lípido A del lipopolisacárido de la membrana externa y desplaza el magnesio y el calcio que la estabilizan. Las membranas externa e interna se vuelven permeables, el contenido se escapa y la bacteria muere. También neutralizan la endotoxina circulante.","mp":["Se unen al lípido A.","Desplazan Mg²⁺ y Ca²⁺.","Membranas permeables → la bacteria muere.","Neutralizan endotoxina."],"f":"Aprobados hace décadas. Polimixina B inyectable: advertencia en recuadro por nefrotoxicidad y neurotoxicidad.","e":[["AIDA","Infecciones por gram-negativos resistentes a carbapenémicos","Agregar meropenem a colistina no mejoró los resultados"]],"en":"Aprobados; uso guiado por experiencia y ensayos como AIDA.","s":["Daño renal (toxicidad limitante)","Hormigueo, entumecimiento, mareo"],"sg":["Lesión renal aguda significativa.","Bloqueo neuromuscular que puede afectar la respiración."]}},{"id":119,"n":"Pramlintide","al":"","ar":"hormonas","ca":"fda","cl":"Amylin analog","ev":"fda","u":"Análogo de amilina utilizado como complemento de insulina en pacientes seleccionados con diabetes; aumenta el riesgo de hipoglucemia si no se ajusta el tratamiento.","c":"Análogo de amilina: retrasa vaciado gástrico y baja glucagón.","m":"Symlin · SC con comidas","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/pramlintide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2014/021332s007_S016.pdf"],"x":{"r":"Pramlintide (Symlin) es un análogo sintético de la amilina, la hormona que el páncreas libera junto a la insulina. No es un GLP-1. Se inyecta antes de las comidas junto a la insulina prandial en diabetes tipo 1 o 2. Tiene advertencia en recuadro por hipoglucemia severa.","q":"Análogo de amilina complementario a la insulina.","m":"La insulina mete la glucosa a las células; la amilina controla qué tan rápido aparece la glucosa en sangre. Pramlintide retrasa el vaciado del estómago, frena el glucagón después de comer (algo que la insulina sola no controla bien) y aumenta la llenura en el cerebro. Por eso complementa a la insulina y no la reemplaza.","mp":["Vaciado gástrico más lento.","Menos glucagón después de comer.","Más saciedad.","Menos pico de glucosa posprandial."],"f":"Aprobado en 2005; sigue en el mercado como Symlin.","e":[["Programa de ensayos","Diabetes tipo 1 y 2 con insulina","Pequeña baja de A1c y pérdida de peso modesta"]],"en":"Aprobado.","s":["Náusea","Vómito","Menos apetito","Dolor de cabeza","Hipoglucemia"],"sg":["Advertencia en recuadro: hipoglucemia severa por insulina, usualmente en las 3 horas siguientes. Bajar la insulina prandial ~50% al iniciar."]}},{"id":120,"n":"PT-141","al":"","ar":"cerebro","ca":"wellness","cl":"MC4R agonist","ev":"baja","u":"Otro nombre de bremelanotide. La aprobación corresponde a un producto e indicación específicos; no valida cualquier preparación ni usos de rendimiento sexual.","c":"Agonista melanocortina en el cerebro.","m":"Vyleesi = versión aprobada","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/pt-141","ci":["https://doi.org/10.1007/s40265-019-01187-w","https://doi.org/10.1080/00224499.2023.2175192","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f1d0c1b5-2f39-4bad-a6a4-0066e3ad5dcf","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0b0be196-0c62-461c-94f4-9a35339b4501","https://doi.org/10.1097/AOG.0000000000003500","https://doi.org/10.1097/AOG.0000000000003514","https://www.accessdata.fda.gov/scripts/cder/daf/index.cfm?event=overview.process&ApplNo=210557","https://doi.org/10.1177/10600280241253273"],"x":{"r":"PT-141 es el nombre de mercado gris del bremelanotide. La versión aprobada, Vyleesi, solo está indicada para bajo deseo sexual en mujeres premenopáusicas. El 'PT-141' que se vende en internet para la libido de hombres y mujeres no es ese producto y no tiene control de calidad.","q":"Bremelanotide no regulado (mercado gris / compounding).","m":"Activa receptores de melanocortina, sobre todo MC4R, en zonas del cerebro que regulan el deseo sexual. Es un mecanismo central, distinto al de los fármacos para disfunción eréctil que actúan sobre el flujo de sangre.","mp":["Activa MC4R en el cerebro.","Aumenta el deseo/excitación.","No actúa sobre el flujo sanguíneo."],"f":"El producto de mercado gris no está aprobado. Vyleesi (aprobado en 2019) es solo para mujeres premenopáusicas con HSDD.","e":[["RECONNECT","1,267 mujeres premenopáusicas (Vyleesi 1.75 mg)","Beneficio modesto y estadísticamente significativo"],["Estudio 2004 intranasal","Hombres sanos y con disfunción eréctil","Respuesta eréctil a dosis altas (programa abandonado por la presión arterial)"],["Uso de mercado gris","—","Sin ensayos controlados"]],"en":"Evidencia baja para el producto y uso de mercado gris.","s":["Náusea","Rubor","Dolor de cabeza"],"sg":["Sube la presión arterial transitoriamente.","Hiperpigmentación con uso frecuente.","Pureza y dosis desconocidas en productos no regulados."]}},{"id":121,"n":"Retatrutide","al":"","ar":"digestivo","ca":"ensayos","cl":"Triple GLP-1 / GIP / glucagon agonist","ev":"alta","u":"Agonista triple de GIP, GLP-1 y glucagón en investigación para obesidad y condiciones metabólicas. No debe presentarse como medicamento aprobado ni como producto disponible para preparación rutinaria.","c":"Triple agonista GLP-1 / GIP / glucagón.","m":"Eli Lilly · SC semanal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/retatrutide","ci":["https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1056/NEJMoa2604169","https://doi.org/10.1056/NEJMoa2301972","https://doi.org/10.1038/s41591-024-03018-2","https://doi.org/10.1016/S0140-6736(26)01861-1","https://www.sec.gov/Archives/edgar/data/59478/000005947826000077/q226lillysalesandearningsp.htm","https://www.fda.gov/drugs/drug-alerts-and-statements/fdas-concerns-unapproved-glp-1-drugs-used-weight-loss","https://pubmed.ncbi.nlm.nih.gov/37366315/"],"x":{"r":"Retatrutide es un 'triple agonista' experimental de Eli Lilly que activa los receptores GLP-1, GIP y glucagón con una inyección semanal. En fase 3 produjo cerca de 24–25% de pérdida de peso en obesidad. No está aprobado; Lilly apunta a someterlo a la FDA en 2027.","q":"Triple agonista GLP-1/GIP/glucagón, en investigación.","m":"Une tres acciones hormonales. GLP-1 y GIP son incretinas: aumentan la insulina dependiente de glucosa y reducen el apetito. El tercer blanco, el receptor de glucagón, es lo distintivo: aumentaría el gasto de energía y sacaría grasa del hígado. La idea es superar la pérdida de peso y de grasa hepática de los fármacos solo incretínicos.","mp":["GLP-1 → menos apetito, mejor glucosa.","GIP → potencia el efecto incretina.","Glucagón → más gasto energético y menos grasa hepática."],"f":"No aprobado. Solicitud a la FDA prevista para 2027.","e":[["Fase 2 obesidad","338 adultos, 48 semanas","≈ −24% a dosis de 12 mg vs ≈ −2% placebo"],["Subestudio de hígado","MASLD, 24 semanas","Grasa hepática −81% o más"],["TRIUMPH-1 (fase 3)","Obesidad sin diabetes, 80 semanas","≈ −24–25% a dosis altas"],["TRIUMPH-2 (fase 3)","Obesidad con diabetes tipo 2","≈ −17–19% y mejor glucosa"]],"en":"Evidencia alta, sin aprobación todavía.","s":["Efectos GI dependientes de dosis (menos si se empieza en 2 mg)"],"sg":["Perfil de seguridad a largo plazo aún no establecido.","Sin producto legal: cualquier 'retatrutide' a la venta es del mercado gris."]}},{"id":122,"n":"Rusfertide","al":"","ar":"corazon","ca":"fda","cl":"Hepcidin mimetic peptide","ev":"fda","u":"Mimético de hepcidina utilizado para controlar eritrocitosis en adultos con policitemia vera; actúa sobre disponibilidad de hierro.","c":"Imita hepcidina y limita el hierro para producir glóbulos rojos.","m":"Mimrylo · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/rusfertide","ci":["https://doi.org/10.1056/NEJMoa2308809","https://www.drugs.com/pro/mimrylo.html","https://doi.org/10.1016/j.leukres.2025.108132"],"x":{"r":"Rusfertide (Mimrylo) es un péptido que imita a la hepcidina y limita el hierro disponible para fabricar glóbulos rojos. La FDA lo aprobó el 28 de agosto de 2026 para adultos con policitemia vera, el primero de su clase.","q":"Mimético de hepcidina.","m":"La hepcidina es la hormona que regula el hierro. Rusfertide la imita y se une a la ferroportina, el canal que saca hierro de las células intestinales y de los depósitos. Con menos hierro disponible, la médula fabrica menos glóbulos rojos y el hematocrito se controla con menos flebotomías.","mp":["Se une a ferroportina.","Menos salida de hierro de intestino y depósitos.","Médula recibe menos hierro.","Menos glóbulos rojos → hematocrito controlado."],"f":"Aprobado el 28 de agosto de 2026 (Mimrylo) para policitemia vera en adultos.","e":[["Fase 2 aleatorizada","Policitemia vera","Control del hematocrito y menos flebotomías"],["VERIFY (fase 3)","Policitemia vera","Control del hematocrito y menos flebotomías vs placebo"]],"en":"Aprobado con ensayos de fase 2 y 3.","s":["Reacciones en el sitio de inyección","Anemia"],"sg":["Trombocitosis nueva o que empeora.","Daño fetal."]}},{"id":123,"n":"Secretin","al":"","ar":"hormonas","ca":"fda","cl":"Secretin hormone","ev":"fda","u":"Hormona utilizada en pruebas diagnósticas de función pancreática y procedimientos seleccionados; no es una terapia general digestiva.","c":"Hormona GI que estimula secreción pancreática.","m":"ChiRhoStim · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/secretin","ci":["https://doi.org/10.1053/j.gastro.2014.05.035","https://www.drugs.com/pro/chirhostim.html"],"x":{"r":"La secretina (ChiRhoStim) es una hormona gastrointestinal usada como agente diagnóstico para estimular el páncreas y medir su secreción. Fue la primera sustancia llamada 'hormona' (1902). Hoy ayuda a evaluar la función pancreática y a detectar gastrinoma.","q":"Hormona de 27 aminoácidos para pruebas diagnósticas.","m":"Se une a receptores de las células de los conductos pancreáticos y provoca la secreción de un líquido acuoso rico en bicarbonato. Al medir o visualizar esa secreción se sabe qué tan bien responde el páncreas. En un gastrinoma, la secretina provoca una subida paradójica de gastrina que ayuda a confirmar el tumor.","mp":["Receptor de secretina pancreático.","Secreción de agua y bicarbonato.","Se mide la respuesta.","En gastrinoma: subida paradójica de gastrina."],"f":"Aprobada en 2004 para función pancreática exocrina, diagnóstico de gastrinoma y apoyo en CPRE.","e":[["Estudios de imagen con secretina","Pacientes con sospecha pancreática","Mejor sensibilidad para anomalías de conductos"]],"en":"Aprobada.","s":["Náusea","Vómito","Rubor","Malestar estomacal"],"sg":[]}},{"id":124,"n":"Selank","al":"","ar":"cerebro","ca":"wellness","cl":"Anxiolytic peptide (Russian)","ev":"baja","u":"Péptido experimental investigado por posibles efectos sobre ansiedad; la evidencia no establece un tratamiento aprobado por FDA.","c":"Péptido ansiolítico sintético.","m":"Nasal (no aprobado en EE.UU.)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/selank","ci":["https://doi.org/10.17116/jnevro20151156133-40","https://doi.org/10.1002/dta.2717","https://doi.org/10.1007/s10571-009-9432-0","https://www.statnews.com/2026/07/24/fda-peptide-compounding-panel-backs-epitalon-rejects-emideltide/","https://pubmed.ncbi.nlm.nih.gov/18454096/","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://pubmed.ncbi.nlm.nih.gov/18577961/","https://doi.org/10.3389/fphar.2016.00031"],"x":{"r":"Selank es un péptido ansiolítico sintético desarrollado en Rusia, donde está aprobado para la ansiedad. Fuera de Rusia se vende como 'research peptide' para ansiedad y concentración. Su evidencia humana son estudios pequeños, rusos y no replicados.","q":"Péptido basado en tuftsina (inmunomodulador natural).","m":"Se propone que calma modulando los sistemas de encefalinas y GABA, el metabolismo de la serotonina y los niveles de BDNF, una señal de crecimiento neuronal. Estos mecanismos vienen sobre todo de animales y laboratorio.","mp":["Modula encefalinas y GABA.","Influye en serotonina.","Cambia niveles de BDNF."],"f":"No aprobado por la FDA; aprobado en Rusia.","e":[["Estudios rusos pequeños","Ansiedad; comparación con benzodiacepina","Efecto ansiolítico reportado"],["Revisión analítica","—","No ha completado ensayos según estándares occidentales"]],"en":"Evidencia baja.","s":["Sin datos de seguridad de calidad."],"sg":["Producto del mercado gris."]}},{"id":125,"n":"Selepressin","al":"","ar":"corazon","ca":"ensayos","cl":"Selective vasopressin V1a agonist","ev":"baja","u":"Agonista de receptor V1a investigado para shock séptico; los resultados de investigación no establecen uso clínico rutinario.","c":"Agonista selectivo de vasopresina V1a.","m":"IV (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/selepressin","ci":["https://doi.org/10.1001/jama.2019.14607","https://doi.org/10.1513/AnnalsATS.201708-669SD"],"x":{"r":"Selepressin es un agonista selectivo del receptor V1a de vasopresina, desarrollado por Ferring para subir la presión en choque séptico. Su ensayo pivotal se detuvo por futilidad sin beneficio y se descontinuó.","q":"Agonista V1a selectivo IV, en investigación (descontinuado).","m":"Activa solo el receptor V1a, que contrae los vasos y sube la presión. Al evitar el receptor V2 buscaba no causar retención de líquido, y además reducir la necesidad de norepinefrina.","mp":["Activa V1a → vasoconstricción.","Evita V2 → sin retención de agua.","Menos catecolaminas (objetivo)."],"f":"No aprobado; desarrollo descontinuado.","e":[["SEPSIS-ACT (fase 2b/3)","Adultos con choque séptico","Detenido por futilidad; sin diferencia en días libres de ventilador/vasopresor ni mortalidad a 90 días"]],"en":"Evidencia baja.","s":["—"],"sg":[]}},{"id":126,"n":"Semaglutide","al":"","ar":"digestivo","ca":"fda","cl":"GLP-1 receptor agonist","ev":"fda","u":"Agonista GLP-1 utilizado en diabetes tipo 2 y manejo de peso según producto; otras indicaciones y beneficios dependen de la etiqueta y población. Una preparación compuesta no hereda aprobación del medicamento comercial.","c":"Agonista GLP-1 resistente a degradación.","m":"Ozempic, Wegovy (SC semanal), Rybelsus (oral)","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/semaglutide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2023/209637s020s021lbl.pdf","https://doi.org/10.1056/NEJMoa2032183","https://doi.org/10.1056/NEJMoa2307563","https://jamanetwork.com/journals/jama/fullarticle/2831055","https://www.ajmc.com/view/fda-approves-semaglutide-for-mash-with-fibrosis","https://doi.org/10.1056/NEJMoa2403347","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ee06186f-2aa3-4990-a760-757579d8f77b","https://pubmed.ncbi.nlm.nih.gov/33567185/"],"x":{"r":"Semaglutide (Ozempic, Wegovy, Rybelsus) es un GLP-1 semanal (también en pastilla diaria) diseñado a partir del GLP-1 humano para resistir la degradación y unirse a proteínas de la sangre. Está aprobado para diabetes tipo 2, control de peso, reducción de riesgo cardiovascular, enfermedad renal crónica en diabetes y MASH no cirrótica.","q":"Agonista GLP-1 en inyección semanal o tableta diaria.","m":"Activa el receptor GLP-1: libera insulina solo cuando la glucosa está alta (bajo riesgo de hipoglucemia por sí solo), baja el glucagón, retrasa el vaciado del estómago y actúa en los centros del apetito del cerebro para reducir el hambre. Sus cambios de diseño resisten la enzima DPP-4 y lo unen a la albúmina, lo que permite una dosis semanal.","mp":["Insulina dependiente de glucosa.","Menos glucagón.","Vaciado gástrico más lento.","Cerebro: menos hambre.","Unión a albúmina → dosis semanal."],"f":"Aprobado para diabetes tipo 2, peso, riesgo CV, ERC en diabetes y MASH. Tableta para peso aprobada en diciembre 2025; Wegovy HD (7.2 mg) con aprobación acelerada en marzo 2026.","e":[["STEP 1","Adultos con obesidad, 68 semanas","≈ −14.9% de peso vs −2.4% placebo"],["SELECT","17,604 adultos con sobrepeso/obesidad y enfermedad CV, sin diabetes","−20% eventos cardiovasculares mayores"],["FLOW","Diabetes tipo 2 con enfermedad renal crónica","Menos progresión renal"],["SUSTAIN FORTE","961 adultos con diabetes tipo 2, 40 semanas","2.0 mg bajó A1c más que 1.0 mg"]],"en":"Aprobado con programas de ensayos muy grandes.","s":["Náusea","Vómito","Diarrea","Estreñimiento","Dolor abdominal","Menos apetito","Acidez","Fatiga","Mareo"],"sg":["Advertencia de tumores tiroideos C; contraindicado con historial de carcinoma medular o MEN2.","Pancreatitis.","Vesícula y cálculos.","Daño renal por deshidratación.","Empeoramiento de retinopatía diabética.","Hipoglucemia con insulina o sulfonilureas.","Riesgo de aspiración en anestesia."]}},{"id":127,"n":"Semax","al":"","ar":"cerebro","ca":"wellness","cl":"Nootropic peptide (ACTH(4-10) analog)","ev":"baja","u":"Péptido experimental investigado en funciones neurológicas. Estudios regionales o preclínicos no demuestran eficacia para mejorar cognición en personas sanas.","c":"Análogo nootrópico de ACTH(4-10).","m":"Nasal (no aprobado en EE.UU.)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/semax","ci":["https://doi.org/10.1016/j.npep.2020.102114","https://www.statnews.com/2026/07/24/fda-peptide-compounding-panel-backs-epitalon-rejects-emideltide/","https://doi.org/10.1002/dta.2717","https://doi.org/10.1007/s10571-009-9432-0","https://www.fda.gov/media/193348/download","https://pubmed.ncbi.nlm.nih.gov/29798983/","https://pubmed.ncbi.nlm.nih.gov/15792140/","https://pubmed.ncbi.nlm.nih.gov/10741256/"],"x":{"r":"Semax es un péptido nootrópico sintético desarrollado en Rusia, donde está aprobado para derrame cerebral y trastornos cognitivos. Se vende como 'research peptide' para la cognición. En 2026 un comité asesor de la FDA votó de forma no vinculante a favor de su compounding, con oposición del personal de la FDA.","q":"Análogo de ACTH(4-10), nootrópico intranasal.","m":"Se propone que aumenta factores de crecimiento neuronal como BDNF y NGF y que modula sistemas químicos del cerebro, con efecto nootrópico y neuroprotector. Estos efectos vienen sobre todo de animales y laboratorio.","mp":["Aumenta BDNF y NGF (animales).","Modula neurotransmisores.","Neuroprotección propuesta."],"f":"No aprobado por la FDA; aprobado en Rusia. Voto asesor favorable no vinculante en 2026; verificar decisión final.","e":[["Estudio comparativo 1997","110 pacientes con ictus agudo (30 Semax vs 80 controles)","Mejoría reportada; diseño débil"],["Estudio 2018","110 pacientes post-ictus","Dos cursos de 10 días; resultados reportados por grupos rusos"]],"en":"Evidencia baja: estudios pequeños, débiles y no replicados.","s":["Datos de seguridad escasos"],"sg":["Un reporte FDA de dolor y ardor ocular con gotas compradas en línea.","Posible efecto anticoagulante teórico."]}},{"id":128,"n":"Sermorelin","al":"","ar":"huesos","ca":"wellness","cl":"GHRH analog (secretagogue)","ev":"baja","u":"Análogo de GHRH con antecedentes de productos aprobados y posteriormente descontinuados; las preparaciones compuestas actuales no están aprobadas por FDA por ese antecedente.","c":"Fragmento de GHRH (1-29).","m":"Antes Geref; hoy compounded · SC","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/sermorelin","ci":["https://doi.org/10.1530/eje.0.1510561","https://pubmed.ncbi.nlm.nih.gov/42395176/","https://pubmed.ncbi.nlm.nih.gov/18057338/","https://pubmed.ncbi.nlm.nih.gov/20554713/","https://pubmed.ncbi.nlm.nih.gov/23015655/","https://pubmed.ncbi.nlm.nih.gov/2506218/","https://pubmed.ncbi.nlm.nih.gov/28830317/","https://pubmed.ncbi.nlm.nih.gov/1361964/"],"x":{"r":"Sermorelin es un fragmento sintético de la hormona liberadora de hormona de crecimiento (GHRH 1-29). Fue un medicamento aprobado (Geref) para pruebas de GH y problemas de crecimiento en niños, pero se descontinuó. Hoy se suministra sobre todo como preparación compuesta para subir la GH propia, sin ensayos que respalden sus beneficios en adultos.","q":"Análogo de GHRH de acción corta (antes Geref).","m":"Se une al mismo receptor de la hipófisis que la GHRH natural y estimula la liberación de GH en pulsos, lo que sube el IGF-1. Es de acción más corta que CJC-1295, pero usa la misma vía. Los beneficios en adultos se basan en esa subida hormonal, no en resultados demostrados.","mp":["Activa receptor de GHRH.","Pulsos de GH.","Sube IGF-1.","Acción corta (vida media de minutos)."],"f":"No hay producto aprobado en el mercado; se obtiene por compounding. Prohibido en el deporte.","e":[["Uso histórico aprobado","Niños con déficit de GH y pruebas diagnósticas","Eficacia establecida en esos usos"],["Fisiología","Adultos mayores","La GHRH restaura la respuesta de GH nocturna"],["Uso wellness en adultos","—","Sin ensayos controlados"]],"en":"Evidencia baja para el uso adulto que se mercadea.","s":["Rubor","Dolor o reacción en sitio de inyección","Dolor de cabeza"],"sg":["Posible intolerancia a la glucosa (clase).","Precaución con cáncer activo (eje GH/IGF-1)."]}},{"id":129,"n":"Setmelanotide","al":"Imcivree","ar":"digestivo","ca":"fda","cl":"MC4R agonist","ev":"fda","u":"Agonista MC4R utilizado para formas genéticas específicas de obesidad; no se utiliza para cualquier obesidad.","c":"Agonista MC4R que reduce el hambre.","m":"Imcivree · SC diario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/setmelanotide","ci":["https://doi.org/10.1016/S2213-8587(20)30364-8","https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/213793s009lbl.pdf"],"x":{"r":"Setmelanotide (Imcivree) es un péptido que activa el receptor MC4R del cerebro para reducir el hambre y el peso en personas con ciertas obesidades genéticas raras o con obesidad hipotalámica adquirida. Restablece una señal del apetito que está rota.","q":"Agonista selectivo de MC4R, inyección diaria.","m":"Las señales de las reservas de grasa pasan por varios genes (POMC, PCSK1, LEPR) antes de llegar a MC4R, el receptor del hipotálamo que apaga el hambre. Si uno de esos genes falla, MC4R no se estimula y la persona tiene hambre intensa y obesidad temprana. Setmelanotide salta el paso roto y estimula MC4R directamente. También estimula un poco MC1R, por eso oscurece la piel.","mp":["Leptina → POMC/PCSK1 → MC4R (vía normal).","Gen roto → MC4R sin señal → hambre extrema.","Setmelanotide estimula MC4R directo.","Menos hambre y peso."],"f":"Aprobado en 2020 (deficiencia de POMC, PCSK1, LEPR), 2022 (Bardet-Biedl) y en 2026 (obesidad hipotalámica adquirida). Desde 2 años.","e":[["Ensayos pivotales","Deficiencia de POMC / LEPR","≥10% de pérdida de peso en ~80% (POMC) y ~45% (LEPR) en un año; menos hambre"]],"en":"Aprobado con ensayos de fase 3.","s":["Oscurecimiento de piel y lunares","Reacción en sitio","Náusea, vómito, diarrea, dolor abdominal","Dolor de cabeza","Depresión","Erecciones espontáneas"],"sg":["Depresión e ideas suicidas: vigilar.","Alteraciones sexuales.","Alergias graves.","Obesidad hipotalámica: insuficiencia suprarrenal aguda y alteraciones de sodio.","Alcohol bencílico: precaución en recién nacidos."]}},{"id":130,"n":"Sincalide","al":"Kinevac","ar":"digestivo","ca":"fda","cl":"Cholecystokinin analog","ev":"fda","u":"Análogo de colecistoquinina utilizado como apoyo en pruebas diagnósticas de función biliar y pancreática.","c":"Fragmento de colecistoquinina: contrae la vesícula.","m":"Kinevac · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/sincalide","ci":["https://doi.org/10.2967/jnumed.109.069393","https://www.bracco.com/sites/default/files/2023-02/us-en-2023-02-27-spc-kinevac.pdf"],"x":{"r":"Sincalide (Kinevac) es un fragmento sintético de la colecistoquinina (CCK-8) usado como agente diagnóstico. Hace que la vesícula se contraiga para medir su función (fracción de eyección), estimula la secreción pancreática y acelera el bario por el intestino delgado.","q":"Octapéptido de colecistoquinina para estudios diagnósticos.","m":"Se une a receptores de CCK y reproduce sus efectos: contrae el músculo de la vesícula para vaciarla, relaja el esfínter de Oddi, estimula enzimas pancreáticas y mueve el intestino. En una gammagrafía se calcula qué porcentaje del trazador expulsa la vesícula.","mp":["Receptor de CCK.","La vesícula se contrae y vacía.","Se mide la fracción de eyección."],"f":"Aprobado en 1976.","e":[["Estudios de estandarización","Gammagrafía hepatobiliar","Infusión lenta de ~60 min da resultados más reproducibles; límite normal ~38%"]],"en":"Aprobado.","s":["Dolor o calambre abdominal","Náusea","Urgencia de evacuar","Rubor o mareo"],"sg":["Precaución en embarazo (puede contraer el útero).","Contraindicado en obstrucción intestinal."]}},{"id":131,"n":"Somapacitan","al":"Sogroya","ar":"hormonas","ca":"fda","cl":"Long-acting GH analog","ev":"fda","u":"Análogo de GH de acción prolongada utilizado para deficiencia de hormona de crecimiento en poblaciones definidas por etiqueta.","c":"GH de larga acción, dosis semanal.","m":"Sogroya · pluma SC semanal","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/somapacitan","ci":["https://doi.org/10.1210/clinem/dgaa049","https://www.novo-pi.com/sogroya.pdf"],"x":{"r":"Somapacitan (Sogroya) es una hormona de crecimiento de larga acción para dosis semanal. Se une de forma reversible a la albúmina del cuerpo para durar más, así que una inyección semanal reemplaza las inyecciones diarias de GH estándar.","q":"Derivado de GH semanal.","m":"Activa el receptor de GH igual que la hormona natural y hace que el hígado produzca IGF-1. Sus cambios de diseño no alteran el efecto; solo la duración. Al unirse a la albúmina se libera poco a poco durante la semana. En adultos con déficit mejora la composición corporal; en niños apoya el crecimiento.","mp":["Receptor de GH → IGF-1.","Unión reversible a albúmina.","Actividad sostenida toda la semana."],"f":"Aprobado en 2020 (adultos), 2023 (niños) y en febrero de 2026 para talla baja idiopática, pequeño para edad gestacional y Noonan, entre otros.","e":[["REAL 1","Adultos con déficit de GH","Menos grasa troncal vs placebo; comparable a GH diaria"]],"en":"Aprobado con ensayos de fase 3.","s":["Adultos: dolor de espalda y articular, indigestión, problemas de sueño, edema, hipertensión","Niños: resfriados, tos, otitis, fiebre, dolor de cabeza, reacciones en sitio"],"sg":["Retención de líquido y menor sensibilidad a la insulina.","Precaución en cáncer activo.","Hipertensión intracraneal."]}},{"id":132,"n":"Somatropin (rhGH)","al":"rhGH","ar":"hormonas","ca":"fda","cl":"Growth hormone","ev":"fda","u":"Hormona de crecimiento recombinante para deficiencias y trastornos específicos; no es una indicación aprobada de rejuvenecimiento general.","c":"Hormona de crecimiento recombinante.","m":"Genotropin, Norditropin, Omnitrope… · SC","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/somatropin-rhgh","ci":["https://www.gene.com/media/statements/ps_031524","https://humatrope.lilly.com/hcp","https://www.novo-pi.com/norditropin.pdf"],"x":{"r":"La somatropina es hormona de crecimiento humana recombinante, idéntica a la natural (191 aminoácidos). Se vende como Genotropin, Norditropin, Omnitrope y otras. Reemplaza la GH en niños y adultos con déficit y trata varias condiciones de talla baja y desgaste.","q":"GH recombinante de inyección diaria.","m":"Se une a receptores de GH en todo el cuerpo y estimula al hígado y otros tejidos a producir IGF-1. Juntos impulsan el crecimiento óseo en las placas de crecimiento de los niños, la formación de proteína, la degradación de grasa y el metabolismo de carbohidratos. Se elimina rápido, por eso la inyección es diaria.","mp":["Receptor de GH → IGF-1.","Crecimiento óseo (niños).","Más proteína y menos grasa.","Efectos sobre la glucosa."],"f":"Aprobada desde 1987 (Humatrope), con muchas marcas e indicaciones.","e":[["Décadas de ensayos controlados","Déficit de GH, Turner, Prader-Willi, otros","Más velocidad de crecimiento y talla adulta; mejor composición corporal en adultos"]],"en":"Aprobada.","s":["Reacción en sitio","Dolor articular y muscular","Edema","Dolor de cabeza"],"sg":["Menor sensibilidad a la insulina.","No usar en enfermos críticos agudos (más mortalidad).","Prader-Willi con obesidad severa o problemas respiratorios: muertes súbitas reportadas.","Hipertensión intracraneal, epífisis deslizada, escoliosis.","Crecimiento de tumores, pancreatitis, alergias."]}},{"id":133,"n":"Survodutide","al":"","ar":"digestivo","ca":"ensayos","cl":"GLP-1 / glucagon dual agonist","ev":"alta","u":"Agonista dual de GLP-1 y glucagón investigado en obesidad y enfermedad hepática metabólica.","c":"Agonista dual GLP-1 / glucagón.","m":"SC semanal (estudios)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/survodutide","ci":["https://doi.org/10.1056/NEJMoa2401755","https://www.ncbi.nlm.nih.gov/books/NBK551568/","https://doi.org/10.1038/s41591-026-04479-3","https://www.boehringer-ingelheim.com/us/human-health/metabolic-diseases/results-phase-iii-synchronize-1-obesity-trial"],"x":{"r":"Survodutide es un agonista dual de GLP-1 y glucagón de Boehringer Ingelheim y Zealand, de inyección semanal para obesidad y MASH. En fases 2 y 3 mejoró la enfermedad hepática y bajó el peso; en fase 3 de obesidad se reportó ~17% de pérdida de peso.","q":"Agonista dual GLP-1/glucagón semanal, en investigación.","m":"El brazo de glucagón aumentaría el gasto de energía y la quema de grasa en el hígado; el brazo GLP-1 reduce el apetito. Se busca juntar pérdida de peso y reducción directa de grasa hepática.","mp":["Glucagón → gasto energético y grasa hepática.","GLP-1 → menos apetito."],"f":"No aprobado.","e":[["Fase 2","MASH confirmada por biopsia, 48 semanas","Mejoría histológica sin empeorar fibrosis vs placebo"],["SYNCHRONIZE-MASLD (fase 3)","Obesidad + hígado graso","Gran reducción de grasa hepática; peso ≈ −12% vs −1%"],["Fase 3 obesidad","Comunicado de la compañía","≈ −17% de peso"]],"en":"Evidencia alta, sin aprobación.","s":["Efectos GI"],"sg":[]}},{"id":134,"n":"TB-500","al":"","ar":"huesos","ca":"wellness","cl":"Synthetic Tβ4 fragment","ev":"baja","u":"Nombre utilizado para productos relacionados con fragmentos de timosina beta-4; identidad y evidencia no son intercambiables con la proteína completa. No hay eficacia clínica establecida para recuperación de lesiones.","c":"Fragmento sintético asociado a timosina β-4.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/tb-500","ci":["https://doi.org/10.1517/14712598.2012.634793","https://www.mcdermottlaw.com/insights/bulk-list-bound-pcac-backs-majority-of-peptides-in-two-day-public-meeting/","https://pubmed.ncbi.nlm.nih.gov/17495250/","https://pubmed.ncbi.nlm.nih.gov/36613994/","https://doi.org/10.1196/annals.1415.003","https://pubmed.ncbi.nlm.nih.gov/22962027/","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://pubmed.ncbi.nlm.nih.gov/23084823/"],"x":{"r":"TB-500 es un fragmento sintético que se vende como 'fragmento de timosina beta-4' para recuperación de lesiones. No existe ningún ensayo en humanos del fragmento. Está prohibido en el deporte. En 2026 un comité asesor de la FDA votó 8-6 para recomendarlo para compounding (no vinculante).","q":"Fragmento sintético asociado a timosina β4.","m":"Se asume que comparte las acciones de la timosina β4 completa: se une a la actina, favorece la migración celular, la formación de vasos y reduce la inflamación. Todo esto se extrapola de datos animales de la proteína completa; el fragmento en sí casi no se ha estudiado.","mp":["Se uniría a la actina.","Migración celular.","Nuevos vasos.","Menos inflamación (extrapolado)."],"f":"No aprobado por la FDA. Prohibido en el deporte. Comité asesor 2026: 8-6 a favor de compounding (no vinculante); verificar decisión final.","e":[["Ensayos del fragmento","—","Ninguno"],["Timosina β4 completa (gotas oculares, fase III)","Queratopatía neurotrófica","Datos de otra molécula y otro uso"]],"en":"Evidencia baja.","s":["Sin datos de seguridad humanos del fragmento."],"sg":["Producto del mercado gris."]}},{"id":135,"n":"Teduglutide","al":"Gattex","ar":"digestivo","ca":"fda","cl":"GLP-2 analog","ev":"fda","u":"Análogo de GLP-2 utilizado en síndrome de intestino corto con dependencia de soporte parenteral; exige seguimiento especializado.","c":"Análogo de GLP-2: mejora absorción intestinal.","m":"Gattex · SC diario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/teduglutide","ci":["https://doi.org/10.1038/ctg.2015.69","https://www.accessdata.fda.gov/drugsatfda_docs/label/2021/203441s018lbl.pdf"],"x":{"r":"Teduglutide (Gattex) es un análogo de GLP-2 de larga acción que ayuda al intestino a absorber más nutrientes. Se usa en síndrome de intestino corto para depender menos de la nutrición IV.","q":"Análogo de GLP-2 de inyección diaria.","m":"Se une al receptor GLP-2 del intestino. Un cambio de un aminoácido lo hace resistente a la enzima que destruye el GLP-2 en minutos. Estimula el crecimiento de la mucosa: vellosidades más altas y criptas más profundas, más superficie para absorber. Ese mismo efecto obliga a vigilar pólipos en el colon.","mp":["Receptor GLP-2.","Resistente a DPP-4.","Vellosidades más altas → más superficie.","Más absorción → menos nutrición IV."],"f":"Aprobado en 2012 para adultos; luego para niños desde 1 año.","e":[["Programa pivotal y extensión","Síndrome de intestino corto con nutrición parenteral","La gran mayoría redujo el soporte parenteral; algunos lograron independencia total"]],"en":"Aprobado.","s":["Dolor y distensión abdominal","Náusea y vómito","Infección respiratoria alta","Reacción en sitio","Sobrecarga de líquido"],"sg":["Pólipos colorrectales: colonoscopía antes y durante el tratamiento.","Obstrucción intestinal.","Problemas de vesícula, vías biliares y páncreas."]}},{"id":136,"n":"Teriparatide","al":"","ar":"huesos","ca":"fda","cl":"PTH analog","ev":"fda","u":"Análogo de PTH utilizado para osteoporosis de alto riesgo; estimula formación ósea y requiere evaluación de contraindicaciones.","c":"Fragmento de PTH (1-34) que construye hueso.","m":"Forteo (y genéricos) · pluma SC diaria","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/teriparatide","ci":["https://doi.org/10.1056/NEJM200105103441904","https://uspl.lilly.com/forteo/forteo.html"],"x":{"r":"Teriparatide (Forteo y genéricos) es un fragmento de la hormona paratiroidea (PTH 1-34) que construye hueso en osteoporosis con alto riesgo de fractura. Es de los pocos fármacos que forman hueso nuevo en lugar de solo frenar la pérdida.","q":"Agente anabólico óseo de inyección diaria.","m":"El efecto de la PTH sobre el hueso depende de cómo se da. Niveles altos y continuos destruyen hueso, pero un pulso breve una vez al día inclina el balance hacia la formación. Cada inyección estimula más a los osteoblastos que a los osteoclastos, y en meses sube la densidad y la fuerza del hueso.","mp":["Pulso diario de PTH(1-34).","Estimula osteoblastos más que osteoclastos.","Más densidad y fuerza ósea.","Menos fracturas."],"f":"Aprobado en 2002. En 2020 la FDA quitó la advertencia en recuadro de osteosarcoma y el límite estricto de 2 años.","e":[["Fracture Prevention Trial","Mujeres posmenopáusicas con fracturas vertebrales previas","≈ −65% fracturas vertebrales nuevas vs placebo"]],"en":"Aprobado con ensayos aleatorizados.","s":["Dolor articular","Dolor","Náusea","Mareo y calambres","Hipotensión ortostática tras la dosis"],"sg":["Subidas pasajeras de calcio en sangre y orina.","Depósitos de calcio en piel (calcifilaxis).","Evitar si hay riesgo de osteosarcoma (Paget, radiación ósea previa)."]}},{"id":137,"n":"Terlipressin","al":"","ar":"digestivo","ca":"fda","cl":"Vasopressin analog","ev":"fda","u":"Análogo de vasopresina utilizado en adultos con síndrome hepatorrenal con deterioro rápido de función renal; presenta riesgo respiratorio importante.","c":"Análogo de vasopresina de larga acción.","m":"Terlivaz · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/terlipressin","ci":["https://doi.org/10.1056/NEJMoa2008290","https://drugs.com/pro/terlivaz.html"],"x":{"r":"Terlipresina (Terlivaz) es un análogo de vasopresina de larga acción que mejora la función renal en adultos con síndrome hepatorrenal, una falla renal grave de la enfermedad hepática avanzada. Tiene advertencia en recuadro por falla respiratoria grave o fatal.","q":"Agonista V1 (prodroga de lisina-vasopresina) IV.","m":"Es una prodroga: las enzimas la convierten poco a poco en lisina-vasopresina, que actúa en receptores V1a. En el síndrome hepatorrenal las arterias del intestino están muy dilatadas y la sangre se estanca ahí, de modo que el riñón recibe poca. Terlipresina contrae esos vasos y redirige la sangre hacia el riñón.","mp":["Prodroga → lisina-vasopresina.","Receptor V1a → contrae vasos esplácnicos.","Más sangre al riñón.","Puente hacia el trasplante hepático."],"f":"Aprobada en 2022 en EE.UU. tras largo uso en otros países.","e":[["CONFIRM","Síndrome hepatorrenal","Reversión en ~32% vs 17% con placebo; más complicaciones respiratorias"]],"en":"Aprobada con ensayo aleatorizado.","s":["Dolor abdominal","Náusea y diarrea","Falta de aire"],"sg":["Advertencia en recuadro: falla respiratoria grave o fatal; evitar en hipoxia y vigilar oxigenación.","Isquemia cardíaca, cerebral, intestinal, de dedos o piel.","Puede volver al paciente no elegible para trasplante."]}},{"id":138,"n":"Tesamorelin","al":"","ar":"digestivo","ca":"fda","cl":"GHRH analog","ev":"fda","u":"Grasa abdominal en lipodistrofia por VIH.","c":"Análogo de GHRH.","m":"Egrifta SV / WR · SC diario","a":"Vigilar glucosa.","src":"https://superpower.com/guides/peptides/tesamorelin","ci":["https://doi.org/10.1097/QAI.0b013e3181cbdaff","https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/022505s020lbl.pdf","https://pubmed.ncbi.nlm.nih.gov/23015655/","https://pubmed.ncbi.nlm.nih.gov/31611038/","https://pubmed.ncbi.nlm.nih.gov/18057338/","https://pubmed.ncbi.nlm.nih.gov/20554713/","https://pubmed.ncbi.nlm.nih.gov/20101189/","https://pubmed.ncbi.nlm.nih.gov/28617838/"],"x":{"r":"Tesamorelin (Egrifta) es un análogo sintético de GHRH aprobado para reducir el exceso de grasa abdominal en personas con VIH y lipodistrofia. Hace que la hipófisis libere su propia hormona de crecimiento, que degrada grasa, sobre todo la visceral.","q":"Análogo de GHRH de inyección diaria.","m":"Se une a receptores de GHRH en la hipófisis y estimula la liberación natural y pulsátil de GH, lo que sube el IGF-1. La GH degrada grasa (lipólisis) y la grasa visceral responde especialmente bien. La grasa regresa si se suspende, porque la causa de fondo no cambia.","mp":["Receptor de GHRH.","GH pulsátil propia.","Lipólisis, sobre todo visceral.","Efecto se pierde al suspender."],"f":"Aprobado en 2010 (Egrifta); luego Egrifta SV y Egrifta WR.","e":[["Ensayos en lipodistrofia por VIH","Pacientes con VIH","Grasa visceral −11% a 6 meses; ≈ −18% con tratamiento continuo; placebo sin cambio"]],"en":"Aprobado con ensayos aleatorizados.","s":["Reacciones en sitio (enrojecimiento, picor, dolor)","Dolor articular, muscular y en extremidades","Edema","Hormigueo"],"sg":["Glucosa alta e intolerancia a la glucosa.","Retención de líquido.","Riesgo de tumores nuevos: cáncer debe estar inactivo y tratado.","Vigilar IGF-1.","Alergias."]}},{"id":139,"n":"Thymosin alpha-1","al":"","ar":"inmune","ca":"wellness","cl":"Immunomodulatory peptide","ev":"moderada","u":"Péptido inmunomodulador estudiado en infecciones y otras condiciones. El uso en otros países no equivale a una indicación aprobada por FDA para fortalecer defensas.","c":"Péptido del timo que modula linfocitos T.","m":"Zadaxin · SC (no aprobado en EE.UU.)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/thymosin-alpha-1","ci":["https://pubmed.ncbi.nlm.nih.gov/19392576/","https://pubmed.ncbi.nlm.nih.gov/9581695/","https://doi.org/10.1186/cc11932","https://doi.org/10.1136/bmj-2024-082583","https://doi.org/10.1111/j.1365-2893.2005.00633.x","https://doi.org/10.3389/fcimb.2025.1673959","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks","https://pubmed.ncbi.nlm.nih.gov/19405116/"],"x":{"r":"La timosina alfa-1 es un péptido inmunomodulador aprobado como timalfasina (Zadaxin) en muchos países, pero no en EE.UU. En hepatitis B hay resultados alentadores; en el gran ensayo TESTS de sepsis (1,089 pacientes) no redujo la mortalidad.","q":"Péptido del timo que modula el sistema inmune.","m":"Influye en la maduración y función de los linfocitos T, aumenta señales como interferón gamma e interleucina-2 y potencia a las células NK, en parte a través de receptores tipo Toll.","mp":["Maduración de linfocitos T.","Más IFN-γ e IL-2.","Más actividad de células NK."],"f":"No aprobado por la FDA; aprobado como Zadaxin en muchos otros países.","e":[["Hepatitis B crónica","98 pacientes vs sin tratamiento","Respuesta virológica completa 40.6% vs 9.4% con curso de 26 semanas (p=0.004)"],["Sepsis (multicéntrico previo)","361 pacientes","Mortalidad 26% vs 35% a 28 días (p=0.062, limítrofe)"],["TESTS (fase 3, 2025)","1,089 pacientes con sepsis","Mortalidad 23.4% vs 24.1%; sin beneficio (p=0.93)"]],"en":"Evidencia moderada: estudios reales pero mixtos; ninguno respalda uso wellness.","s":["Pocos efectos adversos; elevaciones leves de enzimas hepáticas"],"sg":["Sin evidencia para uso general de 'refuerzo inmune'."]}},{"id":140,"n":"Thymosin beta-4","al":"","ar":"huesos","ca":"wellness","cl":"Actin-regulating peptide","ev":"baja","u":"Péptido endógeno investigado en reparación y cicatrización; no deben trasladarse sus resultados a productos etiquetados TB-500.","c":"Péptido natural que regula actina y migración celular.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/thymosin-beta-4","ci":["https://doi.org/10.1517/14712598.2012.634793","https://doi.org/10.1196/annals.1415.003","https://clinicaltrials.gov/study/NCT03937882","https://pubmed.ncbi.nlm.nih.gov/36613994/","https://pubmed.ncbi.nlm.nih.gov/41570941/","https://pubmed.ncbi.nlm.nih.gov/23084823/","https://pubmed.ncbi.nlm.nih.gov/41229390/","https://www.fda.gov/drugs/human-drug-compounding/certain-bulk-drug-substances-use-compounding-may-present-significant-safety-risks"],"x":{"r":"La timosina beta-4 es un péptido natural de reparación de tejidos que participa en el movimiento celular y la cicatrización. Se vende como 'research peptide' para recuperación. Hay mucha evidencia animal, pero poca humana; está prohibida en el deporte.","q":"Péptido regulador de actina.","m":"Se une a la actina, una proteína del esqueleto celular, y favorece la migración de células, la movilización de células madre, la formación de vasos y menos inflamación y cicatriz. Está bien caracterizado en modelos de heridas, ojo, corazón y sistema nervioso.","mp":["Se une a actina.","Migración celular.","Movilización de células madre.","Nuevos vasos; menos cicatriz."],"f":"No aprobado por la FDA. Prohibido en el deporte.","e":[["Fase III gotas oculares","Queratopatía neurotrófica","Curación completa a 4 semanas en 6/10 vs 1/8 (p=0.066)"],["Fase I","Voluntarios sanos","Bien tolerada hasta 1,260 mg IV"],["Úlceras venosas","Estudio de dosis","Enfocado en seguridad"]],"en":"Evidencia baja para recuperación o wellness.","s":["Bien tolerada en fase I"],"sg":["Seguridad a largo plazo del uso subcutáneo crónico desconocida."]}},{"id":141,"n":"Thymulin","al":"","ar":"inmune","ca":"wellness","cl":"Thymic immune peptide","ev":"baja","u":"Péptido relacionado con función tímica estudiado principalmente en investigación; no hay beneficio clínico establecido para rejuvenecer o reforzar defensas.","c":"Péptido del timo dependiente de zinc.","m":"Inyectable (no aprobado)","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/thymulin","ci":["https://doi.org/10.1111/j.1749-6632.2008.03964.x","https://doi.org/10.1093/jn/137.5.1345"],"x":{"r":"La timulina es un péptido del timo que depende del zinc y participa en el desarrollo de células inmunes. Se vende como 'research peptide' para el sistema inmune. No hay ensayos humanos modernos de su administración.","q":"Hormona tímica activa solo unida a zinc.","m":"Participa en el desarrollo y diferenciación de los linfocitos T. En animales tiene efectos antiinflamatorios y sobre el dolor. Su actividad depende del zinc: con déficit de zinc baja la timulina activa y cambia la respuesta inmune.","mp":["Desarrollo de linfocitos T.","Requiere zinc para ser activa.","Efectos antiinflamatorios (animales)."],"f":"No aprobado por la FDA.","e":[["Observaciones fisiológicas","Humanos","Actividad de timulina sigue al estado de zinc y del timo"],["Ensayos de administración","—","Ninguno moderno"]],"en":"Evidencia baja.","s":["Sin datos humanos."],"sg":["Producto del mercado gris."]}},{"id":142,"n":"Tirzepatide","al":"","ar":"digestivo","ca":"fda","cl":"Dual GIP + GLP-1 receptor agonist","ev":"fda","u":"Agonista dual GIP/GLP-1 utilizado en diabetes tipo 2 y manejo de peso según producto; beneficios e indicaciones dependen de la etiqueta. Añadir glicina o B6 no confiere aprobación a una preparación compuesta.","c":"Agonista dual GIP + GLP-1.","m":"Mounjaro, Zepbound · SC semanal / viales","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/tirzepatide","ci":["https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/215866s031lbl.pdf","https://doi.org/10.1056/NEJMoa2206038","https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/217806s031lbl.pdf","https://www.fda.gov/news-events/press-announcements/fda-approves-first-medication-obstructive-sleep-apnea","https://doi.org/10.3390/ijms232314631","https://doi.org/10.1007/s00125-024-06144-1","https://doi.org/10.1001/jama.2023.24945","https://doi.org/10.1016/S0140-6736(23)01200-X"],"x":{"r":"Tirzepatide (Mounjaro, Zepbound) es un péptido semanal que activa dos receptores de hormonas intestinales, GIP y GLP-1. Está aprobado para diabetes tipo 2 (adultos y niños ≥10 años), reducción de riesgo cardiovascular en diabetes, control de peso y apnea obstructiva del sueño. En SURMOUNT-1 logró hasta 20.9% de pérdida de peso.","q":"Agonista dual GIP/GLP-1 en pluma o vial semanal.","m":"Imita a dos hormonas intestinales a la vez. A través de GIP y GLP-1 libera insulina cuando la glucosa está alta, baja el glucagón, retrasa el vaciado del estómago y actúa en los centros del apetito para reducir el hambre. GIP potencia el efecto de GLP-1 sobre el peso y la glucosa.","mp":["Receptor GIP + receptor GLP-1.","Insulina dependiente de glucosa.","Menos glucagón.","Vaciado gástrico lento y menos hambre."],"f":"Mounjaro (diabetes tipo 2 y riesgo CV en diabetes) y Zepbound (peso y apnea del sueño).","e":[["SURMOUNT-1","Adultos con obesidad sin diabetes, 72 semanas","−15.0% a −20.9% según dosis vs −3.1% placebo"],["Programa SURPASS","Diabetes tipo 2","Grandes reducciones de A1c y de peso"],["Metanálisis en red 2024","28 ensayos, 23,622 adultos con diabetes tipo 2","15 mg comparable o superior a semaglutide 2 mg en A1c y peso"]],"en":"Aprobado con programas de ensayos muy grandes.","s":["Náusea","Diarrea","Vómito","Estreñimiento","Dolor abdominal","Menos apetito","Indigestión","Fatiga","Reacción en sitio","Eructos","Caída de cabello"],"sg":["Advertencia de tumores tiroideos C.","Pancreatitis.","Vesícula y cálculos.","Daño renal por deshidratación.","Empeoramiento de retinopatía.","Hipoglucemia con insulina/sulfonilureas.","Puede reducir la eficacia de anticonceptivos orales: usar método adicional 4 semanas tras iniciar o subir dosis."]}},{"id":143,"n":"Tripeptide-10 citrulline","al":"","ar":"piel","ca":"cosmetico","cl":"Signal peptide","ev":"baja","u":"Ingrediente cosmético estudiado para organización de matriz cutánea y apariencia de piel; los datos clínicos son limitados.","c":"Imita la decorina y organiza fibras de colágeno.","m":"Decorinyl · tópico","a":"Un uso investigado no equivale a un beneficio clínico demostrado ni a una recomendación de tratamiento. Consulta a un profesional de salud.","src":"https://superpower.com/guides/peptides/tripeptide-10-citrulline","ci":["https://doi.org/10.1111/j.1468-2494.2008.00429.x"],"x":{"r":"El tripéptido-10 citrulina (Decorinyl) es un péptido 'señal' que imita a la decorina, una proteína que organiza cómo se ensamblan las fibras de colágeno. Busca mejorar la calidad del colágeno más que la cantidad. Su apoyo es un estudio de laboratorio y datos del fabricante.","q":"Péptido cosmético mimético de decorina.","m":"En la piel joven la decorina guía a las fibras de colágeno para que se formen con diámetro y espacio uniformes. En la piel envejecida la decorina se fragmenta. Este péptido imitaría esa función para que el colágeno sea más ordenado y la piel luzca más lisa.","mp":["Imita a la decorina.","Regula el diámetro de las fibras de colágeno.","Colágeno más ordenado (laboratorio)."],"f":"Ingrediente cosmético; no requiere aprobación de la FDA.","e":[["Estudio fundacional","Laboratorio / cultivo de tejido","Regula la formación de fibras de colágeno"],["Dato del fabricante","Grupo pequeño","Más flexibilidad de la piel con crema de baja concentración"]],"en":"Evidencia baja.","s":["Bien tolerado"],"sg":[]}},{"id":144,"n":"Triptorelin","al":"","ar":"sexual","ca":"fda","cl":"GnRH agonist","ev":"fda","u":"Agonista de GnRH utilizado en supresión hormonal para indicaciones específicas, como cáncer de próstata o pubertad precoz según producto.","c":"Agonista GnRH depot.","m":"Trelstar, Triptodur · IM","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/triptorelin","ci":["https://doi.org/10.1046/j.1464-410x.2003.04308.x","https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/020715s052lbl.pdf"],"x":{"r":"Triptorelin (Trelstar, Triptodur) es un decapéptido agonista de GnRH en inyección de depósito que suprime la testosterona. Se usa en cáncer de próstata avanzado y en pubertad precoz central, con depósitos de 1, 3 o 6 meses.","q":"Agonista de GnRH en depósito IM.","m":"La primera dosis estimula brevemente la hipófisis (flare de LH, FSH y testosterona). El depósito luego expone el receptor de forma continua, la hipófisis se desensibiliza y la testosterona baja a nivel de castración. En próstata deja sin estímulo al tumor; en pubertad precoz detiene el desarrollo prematuro.","mp":["Flare inicial.","Exposición continua → desensibilización.","Testosterona a nivel de castración.","Depósitos de 1, 3 o 6 meses."],"f":"Trelstar (2000) para cáncer de próstata avanzado; Triptodur (2017, 6 meses) para pubertad precoz central.","e":[["Comparación aleatorizada vs leuprolide","Cáncer de próstata","Bajó la testosterona algo más lento al inicio, pero mantuvo castración igual a 9 meses"]],"en":"Aprobado con ensayos aleatorizados.","s":["Hombres: sofocos, dolor óseo, dolor de cabeza, disfunción eréctil, atrofia testicular, edema de piernas","Niños: reacción en sitio, sangrado vaginal al inicio, sofocos, tos"],"sg":["Flare inicial de testosterona.","Hiperglucemia, diabetes y eventos CV con privación prolongada.","Alergias y reacciones de piel graves.","Convulsiones.","Niños: cambios de ánimo e hipertensión intracraneal."]}},{"id":145,"n":"Trofinetide (programas en investigación)","al":"","ar":"cerebro","ca":"ensayos","cl":"IGF-1-derived peptide","ev":"baja","u":"Síndrome de X frágil y otros (programas previos en investigación).","c":"Derivado de IGF-1 (mismo fármaco que DAYBUE).","m":"Oral (estudios)","a":"Solo Rett está aprobado; lo demás es investigación.","src":"https://superpower.com/guides/peptides/trofinetide-predecessor-programs","ci":["https://doi.org/10.1016/j.pediatrneurol.2020.04.019"],"x":{"r":"Esta ficha cubre los programas de trofinetide que no llegaron a aprobarse (síndrome de X frágil y trauma craneal). En X frágil solo hubo una señal preliminar en un estudio exploratorio de 28 días. El uso aprobado (síndrome de Rett, DAYBUE) está en su propia ficha.","q":"Usos en investigación de un péptido derivado de IGF-1.","m":"Como péptido relacionado con IGF-1, se propone que apoya la maduración de las sinapsis y reduce la neuroinflamación y la disfunción de las células de soporte del cerebro (glía).","mp":["Maduración sináptica.","Menos neuroinflamación.","Mejor función de la glía."],"f":"Aprobado solo para Rett (DAYBUE). Otros usos: investigación sin aprobación.","e":[["Fase 2 doble ciego","Varones adolescentes y adultos con X frágil, 28 días","Dosis alta cumplió criterios exploratorios (señal preliminar)"],["Trauma craneal","Programa previo","Sin indicación aprobada"]],"en":"Evidencia baja para estos usos.","s":["Diarrea (como en Rett)"],"sg":[]}},{"id":146,"n":"Trofinetide","al":"DAYBUE and DAYBUE STIX","ar":"cerebro","ca":"fda","cl":"IGF-1-derived tripeptide analog","ev":"fda","u":"Síndrome de Rett (adultos y niños ≥2 años).","c":"Análogo sintético de un fragmento de IGF-1.","m":"DAYBUE / DAYBUE STIX · oral","a":"Diarrea muy común; ajustar laxantes.","src":"https://superpower.com/guides/peptides/trofinetide","ci":["https://doi.org/10.1038/s41591-023-02398-1","https://www.accessdata.fda.gov/drugsatfda_docs/nda/2023/217026Orig1s000lbl.pdf","https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=67e6f2d9-21f6-466f-9def-826c6a4b8257"],"x":{"r":"Trofinetide (DAYBUE, DAYBUE STIX) es un análogo sintético de un pequeño fragmento de IGF-1 y el primer medicamento aprobado por la FDA para el síndrome de Rett (2023), un trastorno genético raro.","q":"Análogo oral del tripéptido GPE (glicina-prolina-glutamato).","m":"Su mecanismo exacto en Rett no está totalmente establecido. Según estudios preclínicos, reduce la neuroinflamación al modular microglía y astrocitos, apoya la formación y maduración de sinapsis y dendritas, y normaliza la señalización de IGF-1 en el cerebro. La meta es mejorar circuitos afectados por la pérdida del gen MECP2.","mp":["Menos neuroinflamación (microglía y astrocitos).","Maduración de sinapsis y dendritas.","Normaliza señal de IGF-1 en el cerebro."],"f":"Aprobado en 2023 para Rett en adultos y niños ≥2 años. DAYBUE STIX (polvo) en la etiqueta revisada en diciembre 2025.","e":[["LAVENDER (fase 3)","187 niñas y mujeres con Rett, 12 semanas","Cuestionario de conducta −4.9 vs −1.7 puntos (p=0.0175); mejor impresión clínica global"]],"en":"Aprobado con ensayo de fase 3.","s":["Diarrea (la mayoría de los pacientes)","Vómito","Fiebre","Menos apetito y fatiga","Ansiedad","Convulsiones","Resfriados"],"sg":["Diarrea y deshidratación: ajustar laxantes y líquidos.","Vómito severo con riesgo de aspiración.","Pérdida de peso significativa: vigilar."]}},{"id":147,"n":"Vancomycin","al":"","ar":"corazon","ca":"fda","cl":"Glycopeptide antibiotic","ev":"fda","u":"Antibiótico glucopéptido para determinadas infecciones grampositivas; la vía oral y la intravenosa tienen indicaciones y exposición muy diferentes.","c":"Glicopéptido que bloquea la pared bacteriana.","m":"Genérico IV, Vancocin/Firvanq oral","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/vancomycin","ci":["https://doi.org/10.1056/NEJMoa053783","https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/050671s043lbl.pdf"],"x":{"r":"La vancomicina es un antibiótico glicopéptido usado por décadas contra infecciones gram-positivas graves, incluido MRSA. Por vena trata infecciones sistémicas; por boca casi no se absorbe y trata la infección intestinal por C. difficile.","q":"Glicopéptido IV u oral.","m":"Se une al extremo D-alanil-D-alanina de las piezas del peptidoglicano, la malla que da fuerza a la pared bacteriana. Al tapar ese sitio impide que las piezas se entrelacen y la bacteria no puede mantener su estructura. Es un blanco distinto al de las penicilinas, por eso funciona contra muchas bacterias resistentes a ellas.","mp":["Se une a D-Ala-D-Ala.","Bloquea el entrecruzamiento de la pared.","IV: actúa en todo el cuerpo.","Oral: se queda en el intestino (C. difficile)."],"f":"Aprobada desde 1958.","e":[["Décadas de uso","Infecciones gram-positivas graves y C. difficile","Estándar de tratamiento"]],"en":"Aprobada y de uso establecido.","s":["IV: daño renal, pérdida auditiva, glóbulos blancos bajos, reacción a infusión rápida (rubor)","Oral: náusea, dolor abdominal, potasio bajo"],"sg":["Reacciones graves de piel.","Daño renal o auditivo permanente con niveles altos u otros nefrotóxicos."]}},{"id":148,"n":"Vasopressin","al":"","ar":"corazon","ca":"fda","cl":"V1/V2 receptor agonist","ev":"fda","u":"Hormona vasopresora utilizada en shock vasodilatador seleccionado; requiere monitorización hospitalaria.","c":"Hormona antidiurética: contrae vasos (V1).","m":"Vasostrict · IV","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/vasopressin","ci":["https://doi.org/10.1056/NEJMoa067373","https://www.drugs.com/pro/vasostrict.html"],"x":{"r":"La vasopresina (Vasostrict) es una copia sintética de la hormona antidiurética. Se usa en cuidado intensivo para subir la presión de pacientes en choque vasodilatador que no responden a líquidos y catecolaminas.","q":"Vasopresor IV (arginina vasopresina).","m":"Actúa sobre todo en receptores V1a del músculo de los vasos, que se contraen y suben la presión. También actúa en receptores V2 del riñón, que retienen agua. Su vía es distinta a la de la norepinefrina, por eso suma presión cuando las catecolaminas no bastan.","mp":["V1a → vasoconstricción.","V2 → reabsorción de agua.","Vía independiente de catecolaminas."],"f":"Vasostrict con aprobación completa en 2014 para choque vasodilatador.","e":[["VASST","Choque séptico","Agregar vasopresina a norepinefrina no mejoró la supervivencia global"]],"en":"Aprobada.","s":["Menor gasto cardíaco","Bradicardia o arritmias"],"sg":["Isquemia de corazón, intestino, dedos o piel.","Hiponatremia.","Daño tisular si se extravasa."]}},{"id":149,"n":"Vosoritide","al":"","ar":"huesos","ca":"fda","cl":"CNP analog","ev":"fda","u":"Análogo de péptido natriurético tipo C utilizado para aumentar crecimiento lineal en pacientes pediátricos con acondroplasia y epífisis abiertas.","c":"Análogo de CNP que promueve crecimiento del hueso.","m":"Voxzogo · SC diario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/vosoritide","ci":["https://doi.org/10.1016/S0140-6736(20)31541-5","https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/214938s004lbl.pdf"],"x":{"r":"Vosoritide (Voxzogo) es una forma modificada del péptido natriurético tipo C (CNP) que aumenta el crecimiento en niños con acondroplasia mientras sus placas de crecimiento estén abiertas.","q":"Análogo de CNP de inyección diaria.","m":"En la acondroplasia una mutación deja el receptor FGFR3 siempre encendido, y eso frena el crecimiento del cartílago en la placa de crecimiento. Vosoritide activa otro receptor (NPR-B), sube el GMP cíclico en esas células y bloquea la vía hiperactiva de FGFR3. Así el hueso largo crece más. El CNP natural dura minutos; vosoritide está diseñado para durar lo suficiente para una dosis diaria.","mp":["FGFR3 hiperactivo frena el cartílago.","Vosoritide activa NPR-B → GMPc.","GMPc inhibe la vía de FGFR3.","Más crecimiento de huesos largos."],"f":"Aprobación acelerada en 2021; desde octubre 2023 para niños de todas las edades con placas abiertas.","e":[["Fase 3 aleatorizada","Niños con acondroplasia","≈ +1.6 cm/año más que placebo"]],"en":"Aprobado.","s":["Reacción en sitio","Vómito","Baja transitoria de presión","Dolor articular","Erupción (menores de 5 años)"],"sg":["Hipotensión: el niño debe comer y beber antes de la dosis."]}},{"id":150,"n":"Ziconotide","al":"","ar":"cerebro","ca":"fda","cl":"N-type Ca-channel blocker (conotoxin)","ev":"fda","u":"Analgésico intratecal bloqueador de canales de calcio utilizado en dolor crónico grave seleccionado; requiere manejo especializado por riesgos neuropsiquiátricos.","c":"Bloquea canales de calcio tipo N (de caracol cono).","m":"Prialt · intratecal","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/ziconotide","ci":["https://doi.org/10.1001/jama.291.1.63","https://www.drugs.com/pro/prialt.html"],"x":{"r":"Ziconotide (Prialt) es una copia sintética de un péptido del veneno del caracol cono. Es un analgésico no opioide que se administra directamente en el líquido espinal para dolor crónico severo resistente a otros tratamientos. Tiene advertencia en recuadro por efectos psiquiátricos y neurológicos graves.","q":"Bloqueador de canales de calcio tipo N intratecal.","m":"Bloquea de forma selectiva los canales de calcio tipo N de los nervios del dolor que terminan en el asta dorsal de la médula. Esos canales controlan la liberación de los neurotransmisores que llevan el dolor al cerebro. Al bloquearlos, el mensaje de dolor se interrumpe en la médula. No cruza bien al cerebro desde la sangre, por eso se infunde con bomba intratecal.","mp":["Bloquea canales de calcio tipo N.","Menos liberación de neurotransmisores del dolor.","Señal interrumpida en la médula.","Sin depresión respiratoria ni tolerancia tipo opioide."],"f":"Aprobado en 2004 para dolor crónico severo que requiere terapia intratecal.","e":[["Ensayo controlado","Dolor refractario por cáncer y SIDA","Reducción de dolor muy superior al placebo"]],"en":"Aprobado con ensayos aleatorizados.","s":["Mareo y náusea","Confusión y problemas de memoria","Marcha anormal, somnolencia, nistagmo"],"sg":["Advertencia en recuadro: depresión, ideas suicidas, alucinaciones y deterioro neurológico.","Contraindicado con antecedentes de psicosis.","Meningitis por contaminación de la bomba."]}},{"id":151,"n":"Zilucoplan","al":"","ar":"huesos","ca":"fda","cl":"Complement C5 inhibitor peptide","ev":"fda","u":"Inhibidor de complemento C5 utilizado en adultos seleccionados con miastenia gravis generalizada; requiere medidas específicas frente a infección meningocócica.","c":"Bloquea la proteína C5 del complemento.","m":"Zilbrysq · SC diario","a":"La aprobación corresponde a productos e indicaciones específicas; no se extiende automáticamente a otras formulaciones, vías o combinaciones.","src":"https://superpower.com/guides/peptides/zilucoplan","ci":["https://doi.org/10.1016/S1474-4422(23)00080-7","https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/216834s001lbl.pdf"],"x":{"r":"Zilucoplan (Zilbrysq) es un péptido macrocíclico que bloquea la proteína C5 del complemento. Trata la miastenia gravis generalizada en adultos con anticuerpos contra el receptor de acetilcolina y se autoinyecta una vez al día.","q":"Inhibidor de C5 en autoinyección diaria.","m":"En la miastenia con anticuerpos, estos atraen al complemento a la unión nervio-músculo y se forma el complejo de ataque a la membrana, que perfora la superficie del músculo y daña los receptores. Zilucoplan se une a C5 e impide que se divida en C5a y C5b, así que ese complejo no se forma y la unión queda protegida.","mp":["Se une a C5.","Impide C5a y C5b.","No se forma el complejo de ataque a la membrana.","Protege la unión neuromuscular."],"f":"Aprobado en 2023 para miastenia gravis generalizada AChR+ en adultos. Advertencia en recuadro por infecciones meningocócicas; programa REMS.","e":[["RAISE (fase 3)","Miastenia gravis generalizada AChR+, 12 semanas","Mejoría significativa en actividades de la vida diaria vs placebo"]],"en":"Aprobado con ensayo de fase 3.","s":["Reacciones y moretones en sitio","Infecciones respiratorias altas","Diarrea"],"sg":["Infecciones meningocócicas graves: vacunación obligatoria y REMS.","Otras infecciones graves.","Pancreatitis y quistes pancreáticos."]}}];
